/* Character Forge — SRD 5.2.1 items: the rest of the Adventuring Gear, and Magic Items A–Z. Material from the System Reference Document 5.2.1 by Wizards of the Coast LLC, CC-BY-4.0. */
(function (root) {
  'use strict';
  root.CF.content.extendPack('srd-5.2', { items: [{"id":"tinkers-tools","name":"Tinker’s Tools","kind":"tool","toolGroup":"artisan","w":10,"c":50,"text":"Ability: Dexterity Weight: 10 lb.\nUtilize: Assemble a Tiny item composed of scrap, which falls apart in 1 minute (DC 20)\nCraft: Musket, Pistol, Bell, Bullseye Lantern, Flask,\nHooded Lantern, Hunting Trap, Lock, Manacles, Mir- ror, Shovel, Signal Whistle, Tinderbox"},{"id":"weavers-tools","name":"Weaver’s Tools","kind":"tool","toolGroup":"artisan","w":5,"c":1,"text":"Ability: Dexterity Weight: 5 lb.\nUtilize: Mend a tear in clothing (DC 10), or sew a Tiny design (DC 10)\nCraft: Padded Armor, Basket, Bedroll, Blanket, Fine\nClothes, Net, Robe, Rope, Sack, String, Tent, Traveler’s\nClothes"},{"id":"woodcarvers-tools","name":"Woodcarver’s Tools","kind":"tool","toolGroup":"artisan","w":5,"c":1,"text":"Ability: Dexterity Weight: 5 lb.\nUtilize: Carve a pattern in wood (DC 10)\nCraft: Club, Greatclub, Quarterstaff, Ranged weapons (except Pistol, Musket, and Sling), Arcane Focus, Ar- rows, Bolts, Druidic Focus, Ink Pen, Needles\nOther Tools"},{"id":"disguise-kit","name":"Disguise Kit","kind":"tool","w":3,"c":25,"notes":"Create disguises","text":"Ability: Charisma Weight: 3 lb.\nUtilize: Apply makeup (DC 10)\nCraft: Costume"},{"id":"forgery-kit","name":"Forgery Kit","kind":"tool","w":5,"c":15,"notes":"Forge documents","text":"Ability: Dexterity Weight: 5 lb.\nUtilize: Mimic 10 or fewer words of someone else’s handwriting (DC 15), or duplicate a wax seal (DC 20)"},{"id":"herbalism-kit","name":"Herbalism Kit","kind":"tool","w":3,"c":5,"notes":"Identify plants, make antitoxin and potions of healing","text":"Ability: Intelligence Weight: 3 lb.\nUtilize: Identify a plant (DC 10)\nCraft: Antitoxin, Candle, Healer’s Kit, Potion of Healing"},{"id":"navigators-tools","name":"Navigator’s Tools","kind":"tool","w":2,"c":25,"notes":"Plot a course, find north","text":"Ability: Wisdom Weight: 2 lb.\nUtilize: Plot a course (DC 10), or determine position by stargazing (DC 15)"},{"id":"poisoners-kit","name":"Poisoner’s Kit","kind":"tool","w":2,"c":50,"notes":"Detect and apply poisons","text":"Ability: Intelligence Weight: 2 lb.\nUtilize: Detect a poisoned object (DC 10)\nCraft: Basic Poison"},{"id":"thieves-tools","name":"Thieves’ Tools","kind":"tool","w":1,"c":25,"notes":"Pick locks and disarm traps","text":"Ability: Dexterity Weight: 1 lb.\nUtilize: Pick a lock (DC 15), or disarm a trap (DC 15)\nAdventuring Gear The Adventuring Gear table in this section includes gear that adventurers often find useful. These items are described here in alphabetical order, with an item’s price appearing after its name."},{"id":"backpack","name":"Backpack","kind":"container","w":5,"c":2,"holds":"Holds up to 30 lb","text":"A Backpack holds up to 30 pounds within 1 cubic foot. It can also serve as a saddlebag."},{"id":"ball-bearings","name":"Ball Bearings (bag of 1,000)","kind":"gear","w":2,"c":1,"notes":"Cover a 10-ft square: DEX save DC 10 or fall Prone","text":"As a Utilize action, you can spill Ball Bearings from their pouch. They spread to cover a level, 10-footsquare area within 10 feet of yourself. A creature that enters this area for the first time on a turn must succeed on a DC 10 Dexterity saving throw or have the Prone condition. It takes 10 minutes to recover the Ball Bearings."},{"id":"basket","name":"Basket","kind":"gear","w":2,"c":0.4,"text":"A Basket holds up to 40 pounds within 2 cubic feet."},{"id":"bedroll","name":"Bedroll","kind":"gear","w":7,"c":1,"text":"A Bedroll sleeps one Small or Medium creature.\nWhile in a Bedroll, you automatically succeed on saving throws against extreme cold (see “Gameplay Toolbox”)."},{"id":"bell","name":"Bell","kind":"gear","w":0,"c":1,"text":"When rung as a Utilize action, a Bell produces a sound that can be heard up to 60 feet away."},{"id":"blanket","name":"Blanket","kind":"gear","w":3,"c":0.5,"text":"While wrapped in a blanket, you have Advantage on saving throws against extreme cold (see “Gameplay Toolbox”)."},{"id":"block-and-tackle","name":"Block and Tackle","kind":"gear","w":5,"c":1,"text":"A Block and Tackle allows you to hoist up to four times the weight you can normally lift."},{"id":"book","name":"Book","kind":"gear","w":5,"c":25,"text":"A Book contains fiction or nonfiction. If you consult an accurate nonfiction Book about its topic, you gain a +5 bonus to Intelligence (Arcana, History, Nature, or Religion) checks you make about that topic."},{"id":"glass-bottle","name":"Glass Bottle","kind":"gear","w":2,"c":2,"text":"A Glass Bottle holds up to 11/2 pints."},{"id":"bucket","name":"Bucket","kind":"gear","w":2,"c":0.05,"text":"A Bucket holds up to half a cubic foot of contents."},{"id":"burglars-pack","name":"Burglar’s Pack","kind":"gear","sub":"Pack","w":42,"c":16,"notes":"Backpack, ball bearings, bell, 10 candles, crowbar, hooded lantern, 7 flasks of oil, 5 days of rations, rope, tinderbox, waterskin","contents":[["backpack",1],["ball-bearings",1],["bell",1],["candle",10],["crowbar",1],["hooded-lantern",1],["oil",7],["rations",5],["rope",1],["tinderbox",1],["waterskin",1]],"text":"A Burglar’s Pack contains the following items:\nBackpack, Ball Bearings, Bell, 10 Candles, Crowbar, Hooded Lantern, 7 flasks of Oil, 5 days of Rations, Rope, Tinderbox, and Waterskin."},{"id":"caltrops","name":"Caltrops (bag of 20)","kind":"gear","w":2,"c":1,"notes":"Cover a 5-ft square: DEX save DC 15 or 1 piercing and Speed 0","text":"As a Utilize action, you can spread Caltrops from their bag to cover a 5-foot-square area within 5 feet of yourself. A creature that enters this area for the first time on a turn must succeed on a DC 15 Dexterity saving throw or take 1 Piercing damage and have its Speed reduced to 0 until the start of its next turn. It takes 10 minutes to recover the Caltrops."},{"id":"candle","name":"Candle","kind":"gear","sub":"Light","w":0,"c":0.01,"stack":true,"notes":"Bright light 5 ft for 1 hour","text":"For 1 hour, a lit Candle sheds Bright Light in a 5-foot radius and Dim Light for an additional 5 feet."},{"id":"case-crossbow-bolt","name":"Crossbow Bolt Case","kind":"gear","w":1,"c":1,"text":"A Crossbow Bolt Case holds up to 20 Bolts."},{"id":"map-case","name":"Map or Scroll Case","kind":"container","w":1,"c":1,"stack":true,"holds":"Holds up to 10 sheets","text":"A Map or Scroll Case holds up to 10 sheets of paper or 5 sheets of parchment."},{"id":"chain","name":"Chain (10 ft)","kind":"gear","w":10,"c":5,"text":"As a Utilize action, you can wrap a Chain around an unwilling creature within 5 feet of yourself that has the Grappled, Incapacitated, or Restrained condition if you succeed on a DC 13 Strength (Athletics) check. If the creature’s legs are bound, the creature has the Restrained condition until it escapes. Escaping the Chain requires the creature to make a successful DC 18 Dexterity (Acrobatics) check as an action. Bursting the Chain requires a successful DC 20 Strength (Athletics) check as an action."},{"id":"chest","name":"Chest","kind":"container","w":25,"c":5,"holds":"Holds up to 300 lb","text":"A Chest holds up to 12 cubic feet of contents."},{"id":"climbers-kit","name":"Climber’s Kit","kind":"gear","w":12,"c":25,"text":"A Climber’s Kit includes boot tips, gloves, pitons, and a harness. As a Utilize action, you can use the Climber’s Kit to anchor yourself; when you do, you can’t fall more than 25 feet from the anchor point, and you can’t move more than 25 feet from there without undoing the anchor as a Bonus Action."},{"id":"fine-clothes","name":"Fine Clothes","kind":"gear","sub":"Clothes","w":6,"c":15,"text":"Fine Clothes are made of expensive fabrics and adorned with expertly crafted details. Some events and locations admit only people wearing these clothes."},{"id":"travelers-clothes","name":"Traveler’s Clothes","kind":"gear","sub":"Clothes","w":4,"c":2,"text":"Traveler’s Clothes are resilient garments designed for travel in various environments."},{"id":"costume","name":"Costume","kind":"gear","sub":"Clothes","w":4,"c":5,"stack":true,"notes":"Advantage on checks to impersonate the person or type it portrays","text":"While wearing a Costume, you have Advantage on any ability check you make to impersonate the person or type of person it represents."},{"id":"crowbar","name":"Crowbar","kind":"gear","w":5,"c":2,"notes":"Advantage on STR checks where leverage helps","text":"Using a Crowbar gives you Advantage on Strength checks where the Crowbar’s leverage can be applied."},{"id":"diplomats-pack","name":"Diplomat’s Pack","kind":"gear","sub":"Pack","w":39,"c":39,"notes":"Chest, 2 map cases, fine clothes, ink, ink pen, lamp, 2 flasks of oil, 5 sheets of paper, perfume, tinderbox","contents":[["chest",1],["map-case",2],["fine-clothes",1],["ink",1],["ink-pen",1],["lamp",1],["oil",2],["paper",5],["perfume",1],["tinderbox",1]],"text":"A Diplomat’s Pack contains the following items:\nChest, Fine Clothes, Ink, 5 Ink Pens, Lamp, 2 Map or Scroll Cases, 4 flasks of Oil, 5 sheets of Paper, 5 sheets of Parchment, Perfume, and Tinderbox."},{"id":"dungeoneers-pack","name":"Dungeoneer’s Pack","kind":"gear","sub":"Pack","w":55,"c":12,"notes":"Backpack, caltrops, crowbar, 2 flasks of oil, 10 days of rations, rope, tinderbox, 10 torches, waterskin","contents":[["backpack",1],["caltrops",1],["crowbar",1],["oil",2],["rations",10],["rope",1],["tinderbox",1],["torch",10],["waterskin",1]],"text":"A Dungeoneer’s Pack contains the following items:\nBackpack, Caltrops, Crowbar, 2 flasks of Oil, 10 days of Rations, Rope, Tinderbox, 10 Torches, and Waterskin."},{"id":"entertainers-pack","name":"Entertainer’s Pack","kind":"gear","sub":"Pack","w":58.5,"c":40,"notes":"Backpack, bedroll, bell, bullseye lantern, 3 costumes, mirror, 8 flasks of oil, 9 days of rations, tinderbox, waterskin","contents":[["backpack",1],["bedroll",1],["bell",1],["bullseye-lantern",1],["costume",3],["mirror",1],["oil",8],["rations",9],["tinderbox",1],["waterskin",1]],"text":"An Entertainer’s Pack contains the following items:\nBackpack, Bedroll, Bell, Bullseye Lantern, 3 Costumes, Mirror, 8 flasks of Oil, 9 days of Rations, Tinderbox, and Waterskin."},{"id":"explorers-pack","name":"Explorer’s Pack","kind":"gear","sub":"Pack","w":55,"c":10,"notes":"Backpack, bedroll, 2 flasks of oil, 10 days of rations, rope, tinderbox, 10 torches, waterskin","contents":[["backpack",1],["bedroll",1],["oil",2],["rations",10],["rope",1],["tinderbox",1],["torch",10],["waterskin",1]],"text":"An Explorer’s Pack contains the following items:\nBackpack, Bedroll, 2 flasks of Oil, 10 days of Rations, Rope, Tinderbox, 10 Torches, and Waterskin."},{"id":"grappling-hook","name":"Grappling Hook","kind":"gear","w":4,"c":2,"text":"As a Utilize action, you can throw the Grappling Hook at a railing, a ledge, or another catch within 50 feet of yourself, and the hook catches on if you succeed on a DC 13 Dexterity (Acrobatics) check. If you tied a Rope to the hook, you can then climb it."},{"id":"healers-kit","name":"Healer’s Kit","kind":"gear","w":3,"c":5,"notes":"10 uses: stabilize a creature at 0 HP without a check","text":"A Healer’s Kit has ten uses. As a Utilize action, you can expend one of its uses to stabilize an Unconscious creature that has 0 Hit Points without needing to make a Wisdom (Medicine) check."},{"id":"holy-water","name":"Holy Water (flask)","kind":"gear","w":1,"c":25,"stack":true,"notes":"Throw it: 2d8 radiant to a Fiend or Undead (DEX save)","text":"When you take the Attack action, you can replace one of your attacks with throwing a flask of Holy Water. Target one creature you can see within 20 feet of yourself. The target must succeed on a Dexterity saving throw (DC 8 plus your Dexterity modifier and Proficiency Bonus) or take 2d8 Radiant damage if it is a Fiend or an Undead."},{"id":"hunting-trap","name":"Hunting Trap","kind":"gear","w":25,"c":5,"text":"As a Utilize action, you can set a Hunting Trap, which is a sawtooth steel ring that snaps shut when a creature steps on a pressure plate in the center. The trap is affixed by a heavy chain to an immobile object, such as a tree or a spike driven into the ground. A creature that steps on the plate must succeed on a DC 13 Dexterity saving throw or take 1d4 Piercing damage and have its Speed reduced to 0 until the start of its next turn. Thereafter, until the creature breaks free of the trap, its movement is limited by the length of the chain (typically 3 feet). A creature can use its action to make a DC 13 Strength (Athletics) check, freeing itself or another creature within its reach on a success. Each failed check deals 1 Piercing damage to the trapped creature."},{"id":"ink","name":"Ink (1-ounce bottle)","kind":"gear","w":0,"c":10,"text":"Ink comes in a 1-ounce bottle, which provides enough ink to write about 500 pages."},{"id":"ink-pen","name":"Ink Pen","kind":"gear","w":0,"c":0.02,"text":"Using Ink, an Ink Pen is used to write or draw."},{"id":"ladder","name":"Ladder (10 ft)","kind":"gear","w":25,"c":0.1,"text":"A Ladder is 10 feet tall. You must climb to move up or down it."},{"id":"lamp","name":"Lamp","kind":"gear","sub":"Light","w":1,"c":0.5,"notes":"Bright light 15 ft for 6 hours per flask of oil","text":"A Lamp burns Oil as fuel to cast Bright Light in a 15- foot radius and Dim Light for an additional 30 feet."},{"id":"bullseye-lantern","name":"Bullseye Lantern","kind":"gear","sub":"Light","w":2,"c":10,"notes":"Bright light in a 60-ft cone for 6 hours per flask of oil","text":"A Bullseye Lantern burns Oil as fuel to cast Bright Light in a 60-foot Cone and Dim Light for an additional 60 feet."},{"id":"hooded-lantern","name":"Hooded Lantern","kind":"gear","sub":"Light","w":2,"c":5,"notes":"Bright light 30 ft for 6 hours per flask of oil","text":"A Hooded Lantern burns Oil as fuel to cast Bright Light in a 30-foot radius and Dim Light for an additional 30 feet. As a Bonus Action, you can lower the hood, reducing the light to Dim Light in a 5-foot radius, or raise it again."},{"id":"manacles","name":"Manacles","kind":"gear","w":6,"c":2,"text":"As a Utilize action, you can use Manacles to bind an unwilling Small or Medium creature within 5 feet of yourself that has the Grappled, Incapacitated, or Restrained condition if you succeed on a DC 13 Dexterity (Sleight of Hand) check. While bound, a creature has Disadvantage on attack rolls, and the creature is Restrained if the Manacles are attached to a chain or hook that is fixed in place. Escaping the Manacles requires a successful DC 20 Dexterity (Sleight of Hand) check as an action. Bursting them requires a successful DC 25 Strength (Athletics) check as an action. Each set of Manacles comes with a key. Without the key, a creature can use Thieves’ Tools to pick the Manacles’ lock with a successful DC 15 Dexterity (Sleight of Hand) check."},{"id":"map","name":"Map","kind":"gear","w":0,"c":1,"text":"If you consult an accurate Map, you gain a +5 bonus to Wisdom (Survival) checks you make to find your way in the place represented on it."},{"id":"mirror","name":"Mirror","kind":"gear","w":0.5,"c":5,"text":"A handheld steel Mirror is useful for personal cosmetics but also for peeking around corners and reflecting light as a signal."},{"id":"net","name":"Net","kind":"gear","w":3,"c":1,"text":"When you take the Attack action, you can replace one of your attacks with throwing a Net. Target a creature you can see within 15 feet of yourself. The target must succeed on a Dexterity saving throw (DC 8 plus your Dexterity modifier and Proficiency Bonus) or have the Restrained condition until it escapes. The target succeeds automatically if it is Huge or larger. To escape, the target or a creature within 5 feet of it must take an action to make a DC 10 Strength (Athletics) check, freeing the Restrained creature on a success. Destroying the Net (AC 10; 5 HP; Immunity to Bludgeoning, Poison, and Psychic damage) also frees the target, ending the effect."},{"id":"oil","name":"Oil (flask)","kind":"gear","w":1,"c":0.1,"stack":true,"notes":"Can be thrown or lit","text":"You can douse a creature, object, or space with Oil or use it as fuel, as detailed below. Dousing a Creature or an Object. When you take the Attack action, you can replace one of your attacks with throwing an Oil flask. Target one creature or object within 20 feet of yourself. The target must succeed on a Dexterity saving throw (DC 8 plus your Dexterity modifier and Proficiency Bonus) or be covered in oil. If the target takes Fire damage before the oil dries (after 1 minute), the target takes an extra 5 Fire damage from burning oil. Dousing a Space. You can take the Utilize action to pour an Oil flask on level ground to cover a 5-foot-square area within 5 feet of yourself. If lit, the oil burns until the end of the turn 2 rounds from when the oil was lit (or 12 seconds) and deals 5 Fire damage to any creature that enters the area or ends its turn there. A creature can take this damage only once per turn. Fuel. Oil serves as fuel for Lamps and Lanterns. Once lit, a flask of Oil burns for 6 hours in a Lamp or Lantern. That duration doesn’t need to be consecutive; you can extinguish the burning Oil (as a Utilize action) and rekindle it again until it has burned for a total of 6 hours."},{"id":"paper","name":"Paper (sheet)","kind":"gear","w":0,"c":0.2,"stack":true,"text":"One sheet of Paper can hold about 250 handwritten words."},{"id":"parchment","name":"Parchment (sheet)","kind":"gear","w":0,"c":0.1,"stack":true,"text":"One sheet of Parchment can hold about 250 handwritten words."},{"id":"perfume","name":"Perfume","kind":"gear","w":0,"c":5,"text":"Perfume comes in a 4-ounce vial. For 1 hour after applying Perfume to yourself, you have Advantage on Charisma (Persuasion) checks made to influence an Indifferent Humanoid within 5 feet of yourself."},{"id":"pole","name":"Pole (10 ft)","kind":"gear","w":7,"c":0.05,"text":"A Pole is 10 feet long. You can use it to touch something up to 10 feet away. If you must make a Strength (Athletics) check as part of a High or Long Jump, you can use the Pole to vault, giving yourself Advantage on the check."},{"id":"iron-pot","name":"Iron Pot","kind":"gear","w":10,"c":2,"text":"An Iron Pot holds up to 1 gallon."},{"id":"pouch","name":"Pouch","kind":"container","w":1,"c":0.5,"holds":"Holds up to 6 lb","stack":true,"text":"A Pouch holds up to 6 pounds within one-fifth of a cubic foot."},{"id":"priests-pack","name":"Priest’s Pack","kind":"gear","sub":"Pack","w":29,"c":33,"notes":"Backpack, blanket, holy water, lamp, 7 days of rations, robe, tinderbox","contents":[["backpack",1],["blanket",1],["holy-water",1],["lamp",1],["rations",7],["robe",1],["tinderbox",1]],"text":"A Priest’s Pack contains the following items: Backpack, Blanket, Holy Water, Lamp, 7 days of Rations, Robe, and Tinderbox."},{"id":"quiver","name":"Quiver","kind":"container","w":1,"c":1,"holds":"Holds up to 20 arrows","text":"A Quiver holds up to 20 Arrows."},{"id":"portable-ram","name":"Portable Ram","kind":"gear","w":35,"c":4,"text":"You can use a Portable Ram to break down doors.\nWhen doing so, you gain a +4 bonus to the Strength check. One other character can help you use the ram, giving you Advantage on this check."},{"id":"rations","name":"Rations","kind":"gear","sub":"Food","w":2,"c":0.5,"stack":true,"notes":"1 day of food each","text":"Rations consist of travel-ready food, including jerky, dried fruit, hardtack, and nuts. See “Malnutrition” in “Rules Glossary” for the risks of not eating."},{"id":"robe","name":"Robe","kind":"gear","sub":"Clothes","w":4,"c":1,"text":"A Robe has vocational or ceremonial significance.\nSome events and locations admit only people wearing a Robe bearing certain colors or symbols."},{"id":"rope","name":"Rope (50 ft)","kind":"gear","w":5,"c":1,"notes":"Burst it: DC 20 STR (Athletics)","text":"As a Utilize action, you can tie a knot with Rope if you succeed on a DC 10 Dexterity (Sleight of Hand) check. The Rope can be burst with a successful DC 20 Strength (Athletics) check. You can bind an unwilling creature with the Rope only if the creature has the Grappled, Incapacitated, or Restrained condition. If the creature’s legs are bound, the creature has the Restrained condition until it escapes. Escaping the Rope requires the creature to make a successful DC 15 Dexterity (Acrobatics) check as an action."},{"id":"sack","name":"Sack","kind":"gear","w":0.5,"c":0.01,"text":"A Sack holds up to 30 pounds within 1 cubic foot."},{"id":"scholars-pack","name":"Scholar’s Pack","kind":"gear","sub":"Pack","w":22,"c":40,"notes":"Backpack, book, ink, ink pen, lamp, 10 flasks of oil, 10 sheets of parchment, tinderbox","contents":[["backpack",1],["book",1],["ink",1],["ink-pen",1],["lamp",1],["oil",10],["parchment",10],["tinderbox",1]],"text":"A Scholar’s Pack contains the following items: Backpack, Book, Ink, Ink Pen, Lamp, 10 flasks of Oil, 10 sheets of Parchment, and Tinderbox."},{"id":"shovel","name":"Shovel","kind":"gear","w":5,"c":2,"text":"Working for 1 hour, you can use a Shovel to dig a hole that is 5 feet on each side in soil or similar material."},{"id":"signal-whistle","name":"Signal Whistle","kind":"gear","w":0,"c":0.05,"text":"When blown as a Utilize action, a Signal Whistle produces a sound that can be heard up to 600 feet away."},{"id":"iron-spikes","name":"Iron Spikes (10)","kind":"gear","w":5,"c":1,"text":"Iron Spikes come in bundles of ten. As a Utilize action, you can use a blunt object, such as a Light Hammer, to hammer a spike into wood, earth, or a similar material. You can do so to jam a door shut or to then tie a Rope or Chain to the Spike."},{"id":"string","name":"String (10 ft)","kind":"gear","w":0,"c":0.1,"text":"String is 10 feet long. You can tie a knot in it as a Utilize action."},{"id":"tent","name":"Tent (two-person)","kind":"gear","w":20,"c":2,"text":"A Tent sleeps up to two Small or Medium creatures."},{"id":"tinderbox","name":"Tinderbox","kind":"gear","w":1,"c":0.5,"notes":"Light a fire","text":"A Tinderbox is a small container holding flint, fire steel, and tinder (usually dry cloth soaked in light oil) used to kindle a fire. Using it to light a Candle, Lamp, Lantern, or Torch—or anything else with exposed fuel—takes a Bonus Action. Lighting any other fire takes 1 minute."},{"id":"torch","name":"Torch","kind":"gear","sub":"Light","w":1,"c":0.01,"stack":true,"notes":"Bright light 20 ft for 1 hour","text":"A Torch burns for 1 hour, casting Bright Light in a 20-foot radius and Dim Light for an additional 20 feet. When you take the Attack action, you can attack with the Torch, using it as a Simple Melee weapon. On a hit, the target takes 1 Fire damage."},{"id":"vial","name":"Vial","kind":"gear","w":0,"c":1,"text":"A Vial holds up to 4 ounces."},{"id":"waterskin","name":"Waterskin","kind":"gear","w":5,"c":0.2,"notes":"Weight when full","text":"A Waterskin holds up to 4 pints. If you don’t drink sufficient water, you risk dehydration (see “Rules Glossary”). Mounts and Vehicles A mount can help you move more quickly through the wilderness, but its primary purpose is to carry gear that would otherwise slow you down. The Mounts and Other Animals table shows each animal’s carrying capacity. See “Monsters” for the animals’ stat blocks. Mounts and Cargo An animal pulling a carriage, cart, chariot, sled, or wagon can move weight up to five times its base carrying capacity, including the weight of the vehicle. If multiple animals pull the same vehicle, add their carrying capacities together. Barding Barding is armor designed for a mount. Any type of armor on the Armor table in “Equipment” can be purchased as barding. The cost is four times the normal cost, and it weighs twice as much. Saddles A saddle comes with a bit, a bridle, reins, and any other equipment needed to use the saddle. A Military Saddle gives Advantage on any ability check you make to remain mounted. An Exotic Saddle is\nMounts required and for riding Other an Animals aquatic or a flying mount.\nItem Carrying Capacity Cost\nTack, Harness, and Drawn Vehicles\nSaddle Large Vehicles The Airborne and Waterborne Vehicles table provides statistics for various types of large vehicles. The following notes apply."},{"id":"acid","name":"Acid","kind":"gear","w":1,"c":25,"text":"When you take the Attack action, you can replace one of your attacks with throwing a vial of Acid. Target one creature or object you can see within 20 feet of yourself. The target must succeed on a Dexterity saving throw (DC 8 plus your Dexterity modifier and Proficiency Bonus) or take 2d6 Acid damage.","stack":true},{"id":"alchemists-fire","name":"Alchemist’s Fire","kind":"gear","w":1,"c":50,"text":"When you take the Attack action, you can replace one of your attacks with throwing a flask of Alchemist’s Fire. Target one creature or object you can see within 20 feet of yourself. The target must succeed on a Dexterity saving throw (DC 8 plus your Dexterity modifier and Proficiency Bonus) or take 1d4 Fire damage and start burning (see “Rules Glossary”).","stack":true},{"id":"antitoxin","name":"Antitoxin","kind":"gear","w":0,"c":50,"text":"As a Bonus Action, you can drink a vial of Antitoxin to gain Advantage on saving throws to avoid or end the Poisoned condition for 1 hour.","stack":true},{"id":"barrel","name":"Barrel","kind":"gear","w":70,"c":2,"text":"A Barrel holds up to 40 gallons of liquid or up to 4 cubic feet of dry goods."},{"id":"component-pouch","name":"Component Pouch","kind":"gear","w":2,"c":25,"text":"A Component Pouch is watertight and filled with compartments that hold all the free Material components of your spells."},{"id":"flask","name":"Flask","kind":"gear","w":1,"c":0.02,"text":"A Flask holds up to 1 pint.","stack":true},{"id":"jug","name":"Jug","kind":"gear","w":4,"c":0.02,"text":"A Jug holds up to 1 gallon.","stack":true},{"id":"lock","name":"Lock","kind":"gear","w":1,"c":10,"text":"A Lock comes with a key. Without the key, a creature can use Thieves’ Tools to pick this Lock with a successful DC 15 Dexterity (Sleight of Hand) check."},{"id":"magnifying-glass","name":"Magnifying Glass","kind":"gear","w":0,"c":100,"text":"A Magnifying Glass grants Advantage on any ability check made to appraise or inspect a highly detailed item. Lighting a fire with a Magnifying Glass requires light as bright as sunlight to focus, tinder to ignite, and about 5 minutes for the fire to ignite."},{"id":"basic-poison","name":"Basic Poison","kind":"gear","w":0,"c":100,"text":"As a Bonus Action, you can use a vial of Basic Poison to coat one weapon or up to three pieces of ammunition. A creature that takes Piercing or Slashing damage from the poisoned weapon or ammunition takes an extra 1d4 Poison damage. Once applied, the poison retains potency for 1 minute or until its damage is dealt, whichever comes first.","stack":true},{"id":"spyglass","name":"Spyglass","kind":"gear","w":1,"c":1000,"text":"Objects viewed through a Spyglass are magnified to twice their size."},{"id":"rod-arcane-focus","name":"Rod (arcane focus)","kind":"gear","w":2,"c":10,"text":"An Arcane Focus. A Sorcerer, Warlock, or Wizard can use it as a Spellcasting Focus."},{"id":"staff-arcane-focus","name":"Staff (arcane focus)","kind":"gear","w":4,"c":5,"text":"An Arcane Focus (also a Quarterstaff). A Sorcerer, Warlock, or Wizard can use it as a Spellcasting Focus."},{"id":"wooden-staff-druidic-focus","name":"Wooden Staff (druidic focus)","kind":"gear","w":4,"c":5,"text":"A Druidic Focus (also a Quarterstaff). A Druid or Ranger can use it as a Spellcasting Focus."},{"id":"yew-wand-druidic-focus","name":"Yew Wand (druidic focus)","kind":"gear","w":1,"c":10,"text":"A Druidic Focus. A Druid or Ranger can use it as a Spellcasting Focus."},{"id":"holy-symbol-emblem","name":"Holy Symbol (emblem)","kind":"gear","w":0,"c":5,"text":"A Holy Symbol borne on fabric or a Shield. A Cleric or Paladin can use it as a Spellcasting Focus."},{"id":"holy-symbol-reliquary","name":"Holy Symbol (reliquary)","kind":"gear","w":2,"c":5,"text":"A Holy Symbol you hold. A Cleric or Paladin can use it as a Spellcasting Focus."},{"id":"firearm-bullets-10","name":"Firearm Bullets (10)","kind":"gear","w":2,"c":3,"text":"Ammunition for firearms. Usually kept in a Pouch.","stack":true},{"id":"sling-bullets-20","name":"Sling Bullets (20)","kind":"gear","w":1.5,"c":0.04,"text":"Ammunition for a Sling. Usually kept in a Pouch.","stack":true},{"id":"needles-50","name":"Needles (50)","kind":"gear","w":1,"c":1,"text":"Ammunition for a Blowgun. Usually kept in a Pouch.","stack":true},{"id":"adamantine-armor","name":"Adamantine Armor","kind":"gear","sub":"Magic item · Armor (Any Medium or Heavy, Except Hide Armor), Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"This suit of armor is reinforced with adamantine, one of the hardest substances in existence.","text":"This suit of armor is reinforced with adamantine, one of the hardest substances in existence. While you’re wearing it, any Critical Hit against you becomes a normal hit."},{"id":"ammunition-plus1-plus2-or-plus3","name":"Ammunition, +1, +2, or +3","kind":"gear","sub":"Magic item · Weapon (Any Ammunition), Uncommon (+1), Rare (+2), or Very Rare (+3)","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"You have a bonus to attack rolls and damage rolls made with this piece of magic ammunition.","text":"You have a bonus to attack rolls and damage rolls made with this piece of magic ammunition. The bonus is determined by the rarity of the ammunition. Once it hits a target, the ammunition is no longer magical. This ammunition is typically found or sold in quantities of ten or twenty pieces. Ten pieces of this ammunition are equivalent in value to a potion of the same rarity."},{"id":"ammunition-of-slaying","name":"Ammunition of Slaying","kind":"gear","sub":"Magic item · Weapon (Any Ammunition), Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0,"c":40000,"notes":"This magic ammunition is meant to slay creatures of a particular type, which the GM chooses or determines randomly by rolling on the table below.","text":"This magic ammunition is meant to slay creatures of a particular type, which the GM chooses or determines randomly by rolling on the table below. If a creature of that type takes damage from the ammunition, the creature makes a DC 17 Constitution saving throw, taking an extra 6d10 Force damage on a failed save or half as much extra damage on a successful one. After dealing its extra damage to a creature, the ammunition becomes nonmagical.\n1d100 Creature Type 1d100 Creature Type\n01–10 Aberrations 51–60 Fey\n11–15 Beasts 61–70 Fiends\n16–20 Celestials 71–75 Giants\n21–25 Constructs 76–80 Monstrosities\n26–35 Dragons 81–85 Oozes\n36–45 Elementals 86–90 Plants\n46–50 Humanoids 91–00 Undead"},{"id":"amulet-of-health","name":"Amulet of Health","kind":"gear","sub":"Magic item · Wondrous Item, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"Your Constitution is 19 while you wear this amulet.","text":"Your Constitution is 19 while you wear this amulet.\nIt has no effect on you if your Constitution is 19 or higher without it."},{"id":"amulet-of-proof-against-detection-and-location","name":"Amulet of Proof against Detection and Location","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While wearing this amulet, you can’t be targeted by Divination spells or perceived through magical scrying sensors unless you allow it.","text":"While wearing this amulet, you can’t be targeted by Divination spells or perceived through magical scrying sensors unless you allow it."},{"id":"amulet-of-the-planes","name":"Amulet of the Planes","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"While wearing this amulet, you can take a Magic action to name a location that you are familiar with on another plane of existence.","text":"While wearing this amulet, you can take a Magic action to name a location that you are familiar with on another plane of existence. Then make a DC 15 Intelligence (Arcana) check. On a successful check, you cast Plane Shift . On a failed check, you and each creature and object within 15 feet of you travel to a random destination determined by rolling 1d100 and consulting the following table.\n1d100 Destination\n01–60 Random location on the plane you named\n61–70 Random location on an Inner Plane deter-\nmined by rolling 1d6: on a 1, the Plane of Air;\non a 2, the Plane of Earth; on a 3, the Plane of\nFire; on a 4, the Plane of Water; on a 5, the\nFeywild; on a 6, the Shadowfell\n71–80 Random location on an Outer Plane deter-\nmined by rolling 1d8: on a 1, Arborea; on a 2,\nArcadia; on a 3, the Beastlands; on a 4, Byto-\npia; on a 5, Elysium; on a 6, Mechanus; on a 7,\nMount Celestia; on an 8, Ysgard\n81–90 Random location on an Outer Plane deter-\nmined by rolling 1d8: on a 1, the Abyss; on a\n2, Acheron; on a 3, Carceri; on a 4, Gehenna;\non a 5, Hades; on a 6, Limbo; on a 7, the Nine\nHells; on an 8, Pandemonium\n91–00 Random location on the Astral Plane"},{"id":"animated-shield","name":"Animated Shield","kind":"gear","sub":"Magic item · Armor (Shield), Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"While holding this Shield, you can take a Bonus Action to cause it to animate.","text":"While holding this Shield, you can take a Bonus Action to cause it to animate. The Shield leaps into the air and hovers in your space to protect you as if you were wielding it, leaving your hands free. The Shield remains animate for 1 minute, until you take a Bonus Action to end this effect, or until you die or have the Incapacitated condition, at which point the Shield falls to the ground or into your hand if you have one free."},{"id":"apparatus-of-the-crab","name":"Apparatus of the Crab","kind":"gear","sub":"Magic item · Wondrous Item, Legendary","magic":true,"rarity":"Legendary","attunement":false,"w":0,"c":200000,"notes":"This item first appears to be a sealed iron barrel weighing 500 pounds.","text":"This item first appears to be a sealed iron barrel weighing 500 pounds. The barrel has a hidden catch, which can be found with a successful DC 20 Intelligence (Investigation) check. Releasing the catch unlocks a hatch at one end of the barrel, allowing two Medium or smaller creatures to crawl inside. Ten levers are set in a row at the far end, each in a neutral position, able to move up or down. When certain levers are used, the apparatus transforms to resemble a giant lobster. The Apparatus of the Crab is a Large object with the following statistics: AC 20; HP 200; Speed 30 ft., Swim 30 ft. (or 0 ft. for both if the legs aren’t extended); Immunity to Poison and Psychic damage. To be used as a vehicle, the apparatus requires one pilot. While the apparatus’s hatch is closed, the compartment is airtight and watertight. The compartment holds enough air for 10 hours of breathing, divided by the number of breathing creatures inside. The apparatus floats on water. It can also go underwater to a depth of 900 feet. Below that, the vehicle takes 2d6 Bludgeoning damage each minute from pressure. A creature in the compartment can take a Utilize action to move as many as two of the apparatus’s levers up or down. After each use, a lever goes back to its neutral position. Each lever, from left to right, functions as shown in the Apparatus of the Crab Levers table.\nApparatus of the Crab Levers\nLever Up\n1 Legs extend, allowing the apparatus to walk and sw\n2 Forward window shutter opens.\n3 Side window shutters open (two per side).\n4 Two claws extend from the front side of the\napparatus.\n5 Each extended claw makes the following melee atta\n+8 to hit, reach 5 ft. Hit: 7 (2d6) Bludgeoning dama\n6 The apparatus walks or swims forward provided its\nlegs are extended.\n7 The apparatus turns 90 degrees counterclockwise\nprovided its legs are extended.\n8 Eyelike fixtures emit Bright Light in a 30-foot radiu\nand Dim Light for an additional 30 feet.\n9 The apparatus sinks up to 20 feet if it’s in liquid.\n10 The rear hatch unseals and opens."},{"id":"armor-plus1-plus2-or-plus3","name":"Armor, +1, +2, or +3","kind":"gear","sub":"Magic item · Armor (Any Light, Medium, or Heavy), Rare (+1), Very Rare (+2), or Legendary (+3)","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"You have a bonus to Armor Class while wearing this armor.","text":"You have a bonus to Armor Class while wearing this armor. The bonus is determined by its rarity."},{"id":"armor-of-invulnerability","name":"Armor of Invulnerability","kind":"gear","sub":"Magic item · Armor (Plate Armor), Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"You have Resistance to Bludgeoning, Piercing, and Slashing damage while you wear this armor.","text":"You have Resistance to Bludgeoning, Piercing, and Slashing damage while you wear this armor. Metal Shell. You can take a Magic action to give yourself Immunity to Bludgeoning, Piercing, and Slashing damage for 10 minutes or until you are no longer wearing the armor. Once this property is used, it can’t be used again until the next dawn."},{"id":"armor-of-resistance","name":"Armor of Resistance","kind":"gear","sub":"Magic item · Armor (Any Light, Medium, or Heavy), Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"You have Resistance to one type of damage while you wear this armor.","text":"You have Resistance to one type of damage while you wear this armor. The GM chooses the type or determines it randomly by rolling on the following table.\n1d10 Damage Type 1d10 Damage Type\n1 Acid 6 Necrotic\n2 Cold 7 Poison\n3 Fire 8 Psychic\n4 Force 9 Radiant\n5 Lightning 10 Thunder\nDown\nwim. Legs retract, reducing the apparatus’s Speed and Swim\nSpeed to 0 and making it unable to benefit from bo -\nnuses to speed.\nForward window shutter closes.\nSide window shutters close (two per side).\nThe claws retract.\nack:\nage.\nEach extended claw makes the following melee attack:\n+8 to hit, reach 5 ft. Hit: The target has the Grappled\ncondition (escape DC 15).\ns The apparatus walks or swims backward provided its\nlegs are extended.\nThe apparatus turns 90 degrees clockwise provided its\nlegs are extended.\nus The light turns off.\nThe apparatus rises up to 20 feet if it’s in liquid.\nThe rear hatch closes and seals."},{"id":"armor-of-vulnerability","name":"Armor of Vulnerability","kind":"gear","sub":"Magic item · Armor (Any Light, Medium, or Heavy), Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"While wearing this armor, you have Resistance to one of the following damage types: Bludgeoning, Piercing, or Slashing.","text":"While wearing this armor, you have Resistance to one of the following damage types: Bludgeoning, Piercing, or Slashing. The GM chooses the type or determines it randomly. Curse. This armor is cursed, a fact that is revealed only when the Identify spell is cast on the armor or you attune to it. Attuning to the armor curses you until you are targeted by a Remove Curse spell or similar magic; removing the armor fails to end the curse. While cursed, you have Vulnerability to two of the three damage types associated with the armor (not the one to which it grants Resistance)."},{"id":"arrow-catching-shield","name":"Arrow-Catching Shield","kind":"gear","sub":"Magic item · Armor (Shield), Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"You gain a +2 bonus to Armor Class against ranged attack rolls while you wield this Shield.","text":"You gain a +2 bonus to Armor Class against ranged attack rolls while you wield this Shield. This bonus is in addition to the Shield’s normal bonus to AC. Whenever an attacker makes a ranged attack roll against a target within 5 feet of you, you can take a Reaction to become the target of the attack instead."},{"id":"bag-of-beans","name":"Bag of Beans","kind":"gear","sub":"Magic item · Wondrous Item, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"This heavy cloth bag contains 3d4 dry beans when found.","text":"This heavy cloth bag contains 3d4 dry beans when found. The bag weighs half a pound regardless of how many beans it contains and becomes a nonmagical item when it no longer contains any beans. If you dump one or more beans out of the bag, they explode in a 10-foot-radius Sphere centered on them. All the dumped beans are destroyed in the explosion, and each creature in the Sphere, including you, makes a DC 15 Dexterity saving throw, taking 5d4 Force damage on a failed save or half as much damage on a successful one. If you remove a bean from the bag, plant it in dirt or sand, and then water it, the bean disappears as it produces an effect 1 minute later from the ground where it was planted. The GM can choose an effect from the following table or determine it randomly.\n1d100 Effect\n01 5d4 toadstools sprout. If a creature eats a\ntoadstool, roll any die. On an odd roll, the\neater must succeed on a DC 15 Constitution\nsaving throw or take 5d6 Poison damage and\nhave the Poisoned condition for 1 hour. On\nan even roll, the eater gains 5d6 Temporary\nHit Points for 1 hour.\n02–10 A geyser erupts and spouts water, beer,\nmayonnaise, tea, vinegar, wine, or oil (GM’s\nchoice) 30 feet into the air for 1d4 minutes.\n1d100 Effect\n11–20 A Treant sprouts. Roll any die. On an odd\nroll, the treant is Chaotic Evil. On an even\nroll, the treant is Chaotic Good.\n21–30 An animate but immobile stone statue in\nyour likeness rises and makes verbal threats\nagainst you. If you leave it and others come\nnear, it describes you as the most heinous\nof villains and directs the newcomers to find\nand attack you. If you are on the same plane\nof existence as the statue, it knows where\nyou are. The statue becomes inanimate after\n24 hours.\n31–40 A campfire with green flames springs\nforth and burns for 24 hours or until it is\nextinguished.\n41–50 Three Shrieker Fungi sprout.\n51–60 1d4 + 4 bright-pink toads crawl forth. When-\never a toad is touched, it transforms into a\nLarge or smaller monster of the GM’s choice\nthat acts in accordance with its alignment\nand nature. The monster remains for 1 min-\nute, then disappears in a puff of bright-pink\nsmoke.\n61–70 A hungry Bulette burrows up and attacks.\n71–80 A fruit tree grows. It has 1d10 + 20 fruit, 1d8\nof which act as randomly determined po-\ntions. The tree vanishes after 1 hour. Picked\nfruit remains, retaining any magic for 30 days.\n81–90 A nest of 1d4 + 3 rainbow-colored eggs\nsprings up. Any creature that eats an egg\nmakes a DC 20 Constitution saving throw.\nOn a successful save, a creature permanently\nincreases its lowest ability score by 1, ran-\ndomly choosing among equally low scores.\nOn a failed save, the creature takes 10d6\nForce damage from an internal explosion.\n91–95 A pyramid with a 60-foot-square base bursts\nupward. Inside is a burial chamber containing\na Mummy, a Mummy Lord, or some other\nUndead of the GM’s choice. Its sarcophagus\ncontains treasure of the GM’s choice.\n96–00 A giant beanstalk sprouts, growing to a\nheight of the GM’s choice. The top leads\nwhere the GM chooses, such as to a great\nview, a cloud giant’s castle, or another plane\nof existence."},{"id":"bag-of-devouring","name":"Bag of Devouring","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0,"c":40000,"notes":"This bag resembles a Bag of Holding but is a feeding orifice for a gigantic extradimensional creature.","text":"This bag resembles a Bag of Holding but is a feeding orifice for a gigantic extradimensional creature. Turning the bag inside out closes the orifice. The extradimensional creature attached to the bag can sense whatever is placed inside the bag. Animal or vegetable matter placed wholly in the bag is devoured and lost forever. When part of a living creature is placed in the bag, as happens when someone reaches inside it, there is a 50 percent chance that the creature is pulled inside the bag. A creature inside the bag can take an action to try to escape, doing so with a successful DC 15 Strength (Athletics) check. Another creature can take an action to reach into the bag to pull a creature out, doing so with a successful DC 20 Strength (Athletics) check, provided the puller isn’t pulled inside the bag first. Any creature that starts its turn inside the bag is devoured, its body destroyed. Inanimate objects can be stored in the bag, which can hold a cubic foot of such material. However, once each day, the bag swallows any objects inside it and spits them out into another plane of existence. The GM determines the time and plane. If the bag is pierced or torn, it is destroyed, and anything contained within it is transported to a random location on the Astral Plane."},{"id":"bag-of-holding","name":"Bag of Holding","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":5,"c":400,"notes":"This bag has an interior space considerably larger than its outside dimensions—roughly 2 feet square and 4 feet deep on the inside.","text":"This bag has an interior space considerably larger than its outside dimensions—roughly 2 feet square and 4 feet deep on the inside. The bag can hold up to 500 pounds, not exceeding a volume of 64 cubic feet. The bag weighs 5 pounds, regardless of its contents. Retrieving an item from the bag requires a Utilize action. If the bag is overloaded, pierced, or torn, it is destroyed, and its contents are scattered in the Astral Plane. If the bag is turned inside out, its contents spill forth unharmed, but the bag must be put right before it can be used again. The bag holds enough air for 10 minutes of breathing, divided by the number of breathing creatures inside. Placing a Bag of Holding inside an extradimensional space created by a Handy Haversack , Portable Hole , or similar item instantly destroys both items and opens a gate to the Astral Plane. The gate originates where the one item was placed inside the other. Any creature within a 10-foot-radius Sphere centered on the gate is sucked through it to a random location on the Astral Plane. The gate then closes. The gate is one-way and can’t be reopened."},{"id":"bag-of-tricks","name":"Bag of Tricks","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"This bag made from gray, rust, or tan cloth appears empty.","text":"This bag made from gray, rust, or tan cloth appears empty. Reaching inside the bag, however, reveals the presence of a small, fuzzy object. You can take a Magic action to pull the fuzzy object from the bag and throw it up to 20 feet. When the object lands, it transforms into a creature you determine by rolling on the table that corresponds to the bag’s color. See “Monsters” for the creature’s stat block. The creature vanishes at the next dawn or when it is reduced to 0 Hit Points. The creature is Friendly to you and your allies, and it acts immediately after you on your Initiative count. You can take a Bonus Action to command how the creature moves and what action it takes on its next turn, such as attacking an enemy. In the absence of such orders, the creature acts in a fashion appropriate to its nature. Once three fuzzy objects have been pulled from the bag, the bag can’t be used again until the next dawn. Gray Bag of Tricks\n1d8 Creature 1d8 Creature\n1 Weasel 5 Panther\n2 Giant Rat 6 Giant Badger\n3 Badger 7 Dire Wolf\n4 Boar 8 Giant Elk\nRust Bag of Tricks\n1d8 Creature 1d8 Creature\n1 Rat 5 Giant Goat\n2 Owl 6 Giant Boar\n3 Mastiff 7 Lion\n4 Goat 8 Brown Bear\nTan Bag of Tricks\n1d8 Creature 1d8 Creature\n1 Jackal 5 Black Bear\n2 Ape 6 Giant Weasel\n3 Baboon 7 Giant Hyena\n4 Axe Beak 8 Tiger"},{"id":"bead-of-force","name":"Bead of Force","kind":"gear","sub":"Magic item · Wondrous Item, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"This small black sphere measures 3/4 of an inch in diameter and weighs an ounce.","text":"This small black sphere measures 3/4 of an inch in diameter and weighs an ounce. Typically, 1d4 + 4 Beads of Force are found together. You can take a Magic action to throw the bead up to 60 feet. The bead explodes in a 10-foot-radius Sphere on impact and is destroyed. Each creature in the Sphere must succeed on a DC 15 Dexterity saving throw or take 5d4 Force damage. A sphere of transparent force then encloses the area for 1 minute. Any creature that failed the save and is completely within the area is trapped inside this sphere. Creatures that succeeded on the save or are partially within the area are pushed away from the center of the sphere until they are no longer inside it. Only breathable air can pass through the sphere’s wall. No attack or other effect can pass through. An enclosed creature can take a Utilize action to push against the sphere’s wall, moving the sphere up to half the creature’s Speed. The sphere can be picked up, and its magic causes it to weigh only 1 pound, regardless of the weight of creatures inside."},{"id":"bead-of-nourishment","name":"Bead of Nourishment","kind":"gear","sub":"Magic item · Wondrous Item, Common","magic":true,"rarity":"Common","attunement":false,"w":0,"c":100,"notes":"This flavorless, gelatinous bead dissolves on your tongue and provides as much nourishment as 1 day of Rations.","text":"This flavorless, gelatinous bead dissolves on your tongue and provides as much nourishment as 1 day of Rations."},{"id":"belt-of-dwarvenkind","name":"Belt of Dwarvenkind","kind":"gear","sub":"Magic item · Wondrous Item, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"While wearing this belt, you gain the following benefits:","text":"While wearing this belt, you gain the following benefits:\nDwarvish.\nYou know Dwarvish.\nFriend of Dwarvenkind.\nYou have Advantage on Charisma (Persuasion) checks made to interact with dwarves and duergar. Toughness. Your Constitution increases by 2, to a maximum of 20. In addition, while attuned to the belt, you have a 50 percent chance each day at dawn of growing a full beard if you can grow one, or a thicker beard if you already have one. If you aren’t a dwarf or duergar, you gain the following additional benefits while wearing the belt: Darkvision. You have Darkvision with a range of 60 feet. Resilience. You have Resistance to Poison damage. You also have Advantage on saving throws you make to avoid or end the Poisoned condition."},{"id":"belt-of-giant-strength","name":"Belt of Giant Strength","kind":"gear","sub":"Magic item · Wondrous Item, Rarity Varies (Requires Attunement)","magic":true,"rarity":"Varies","attunement":true,"w":0,"c":0,"notes":"While wearing this belt, your Strength changes to a score granted by the belt.","text":"While wearing this belt, your Strength changes to a score granted by the belt. The type of giant determines the score (see the table below). The item has no effect on you if your Strength without the belt is equal to or greater than the belt’s score.\nBelt Str. Rarity\nBelt of Giant Strength (hill) 21 Rare\nBelt of Giant Strength (frost or\nstone)\n23 Very Rare\nBelt of Giant Strength (fire) 25 Very Rare\nBelt of Giant Strength (cloud) 27 Legendary\nBelt of Giant Strength (storm) 29 Legendary"},{"id":"berserker-axe","name":"Berserker Axe","kind":"gear","sub":"Magic item · Weapon (Battleaxe, Greataxe, or Halberd), Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon.","text":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. In addition, while you are attuned to this weapon, your Hit Point maximum increases by 1 for each level you have attained. Curse. This weapon is cursed, and becoming attuned to it extends the curse to you. As long as you remain cursed, you are unwilling to part with the weapon, keeping it within reach at all times. You also have Disadvantage on attack rolls with weapons other than this one. Whenever another creature damages you while the weapon is in your possession, you must succeed on a DC 15 Wisdom saving throw or go berserk. This berserk state ends when you start your turn and there are no creatures within 60 feet of you that you can see or hear. While berserk, you regard the creature nearest to you that you can see or hear as your enemy. If there are multiple possible creatures, choose one at random. On each of your turns, you must move as close to the creature as possible and take the Attack action, targeting the creature. If you’re unable to get close enough to the creature to attack it with the weapon, your turn ends after you’ve used up all your available movement. If the creature dies or can no longer be seen or heard by you, the next nearest creature that you can see or hear becomes your new target."},{"id":"boots-of-elvenkind","name":"Boots of Elvenkind","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"While you wear these boots, your steps make no sound, regardless of the surface you are moving across.","text":"While you wear these boots, your steps make no sound, regardless of the surface you are moving across. You also have Advantage on Dexterity (Stealth) checks."},{"id":"boots-of-levitation","name":"Boots of Levitation","kind":"gear","sub":"Magic item · Wondrous Item, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"While you wear these boots, you can cast Levitate on yourself.","text":"While you wear these boots, you can cast Levitate on yourself."},{"id":"boots-of-speed","name":"Boots of Speed","kind":"gear","sub":"Magic item · Wondrous Item, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"While you wear these boots, you can take a Bonus Action to click the boots’ heels together.","text":"While you wear these boots, you can take a Bonus Action to click the boots’ heels together. If you do, the boots double your Speed, and any creature that makes an Opportunity Attack against you has Disadvantage on the attack roll. If you click your heels together again, you end the effect. When you’ve used the boots’ property for a total of 10 minutes, the magic ceases to function for you until you finish a Long Rest."},{"id":"boots-of-striding-and-springing","name":"Boots of Striding and Springing","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While you wear these boots, your Speed becomes 30 feet unless your Speed is higher, and your Speed isn’t reduced by you carrying weight in excess of your carrying capacity or wearing Heavy Armor.","text":"While you wear these boots, your Speed becomes 30 feet unless your Speed is higher, and your Speed isn’t reduced by you carrying weight in excess of your carrying capacity or wearing Heavy Armor. Once on each of your turns, you can jump up to 30 feet by spending only 10 feet of movement."},{"id":"boots-of-the-winterlands","name":"Boots of the Winterlands","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"These furred boots are snug and feel warm.","text":"These furred boots are snug and feel warm. While wearing them, you gain the following benefits. Cold Resistance. You have Resistance to Cold damage and can tolerate temperatures of 0 degrees Fahrenheit or lower without any additional protection. Winter Strider. You ignore Difficult Terrain created by ice or snow."},{"id":"bowl-of-commanding-water-elementals","name":"Bowl of Commanding Water Elementals","kind":"gear","sub":"Magic item · Wondrous Item, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"While this bowl is filled with water and you are within 5 feet of it, you can take a Magic action to summon a Water Elemental .","text":"While this bowl is filled with water and you are within 5 feet of it, you can take a Magic action to summon a Water Elemental . The elemental appears in an unoccupied space as close to the bowl as possible, understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. The elemental disappears after 1 hour, when it dies, or when you dismiss it as a Bonus Action. The bowl can’t be used this way again until the next dawn. The bowl is about 1 foot in diameter and half as deep. It holds about 3 gallons."},{"id":"bracers-of-archery","name":"Bracers of Archery","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While wearing these bracers, you have proficiency with the Longbow and Shortbow, and you gain a +2 bonus to damage rolls made with such weapons.","text":"While wearing these bracers, you have proficiency with the Longbow and Shortbow, and you gain a +2 bonus to damage rolls made with such weapons."},{"id":"bracers-of-defense","name":"Bracers of Defense","kind":"gear","sub":"Magic item · Wondrous Item, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"While wearing these bracers, you gain a +2 bonus to Armor Class if you are wearing no armor and using no Shield.","text":"While wearing these bracers, you gain a +2 bonus to Armor Class if you are wearing no armor and using no Shield."},{"id":"brazier-of-commanding-fire-elementals","name":"Brazier of Commanding Fire Elementals","kind":"gear","sub":"Magic item · Wondrous Item, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"While you are within 5 feet of this brazier, you can take a Magic action to summon a Fire Elemental .","text":"While you are within 5 feet of this brazier, you can take a Magic action to summon a Fire Elemental . The elemental appears in an unoccupied space as close to the brazier as possible, understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. The elemental disappears after 1 hour, when it dies, or when you dismiss it as a Bonus Action. The brazier can’t be used this way again until the next dawn."},{"id":"brooch-of-shielding","name":"Brooch of Shielding","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While wearing this brooch, you have Resistance to Force damage, and you have Immunity to damage from the Magic Missile spell.","text":"While wearing this brooch, you have Resistance to Force damage, and you have Immunity to damage from the Magic Missile spell."},{"id":"broom-of-flying","name":"Broom of Flying","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"This wooden broom functions like a mundane broom until you stand astride it and take a Magic action to make it hover beneath you, at which time it can be ridden in the air.","text":"This wooden broom functions like a mundane broom until you stand astride it and take a Magic action to make it hover beneath you, at which time it can be ridden in the air. It has a Fly Speed of 50 feet. It can carry up to 400 pounds, but its Fly Speed becomes 30 feet while carrying over 200 pounds. The broom stops hovering when you land or when you’re no longer riding it. As a Magic action, you can send the broom to travel alone to a destination within 1 mile of you if you name the location and are familiar with it. The broom comes back to you when you take a Magic action and use a command word if the broom is still within 1 mile of you."},{"id":"candle-of-invocation","name":"Candle of Invocation","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"This candle’s magic is activated when the candle is lit, which requires a Magic action.","text":"This candle’s magic is activated when the candle is lit, which requires a Magic action. After burning for 4 hours, the candle is destroyed. You can snuff it out early for use at a later time. Deduct the time it burned in increments of 1 minute from its total burn time. While lit, the candle sheds Dim Light in a 30-foot radius. While you are within that light, you have Advantage on D20 Tests. In addition, a Cleric or Druid in the light can cast level 1 spells they have prepared without expending spell slots. Alternatively, when you light the candle for the first time, you can cast Gate with it. Doing so destroys the candle. The portal created by the spell links to a particular Outer Plane chosen by the GM or determined by rolling on the following table.\n1d100 Outer Plane 1d100 Outer Plane\n01–05 Abyss 55–59 Gehenna\n06–10 Acheron 60–64 Hades\n11–17 Arborea 65–69 Limbo\n18–25 Arcadia 70–77 Mechanus\n26–33 Beastlands 78–85 Mount Celestia\n34–41 Bytopia 86–90 Nine Hells\n42–46 Carceri 91–95 Pandemonium\n47–54 Elysium 96–00 Ysgard"},{"id":"cape-of-the-mountebank","name":"Cape of the Mountebank","kind":"gear","sub":"Magic item · Wondrous Item, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"This cape smells faintly of brimstone.","text":"This cape smells faintly of brimstone. While wearing it, you can use it to cast Dimension Door as a Magic action. This property can’t be used again until the next dawn. When you teleport with that spell, you leave behind a cloud of smoke. The space you left is Lightly Obscured by that smoke until the end of your next turn."},{"id":"carpet-of-flying","name":"Carpet of Flying","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0,"c":40000,"notes":"You can make this carpet hover and fly by taking a Magic action and using the carpet’s command word.","text":"You can make this carpet hover and fly by taking a Magic action and using the carpet’s command word. It moves according to your directions if you are within 30 feet of it. Four sizes of Carpet of Flying exist. The GM chooses the size of a given carpet or determines it randomly by rolling on the following table. A carpet can carry up to twice the weight shown on the table, but its Fly Speed is halved if it carries more than its normal capacity.\n1d100 Size Capacity Fly Speed\n01–20 3 ft. × 5 ft. 200 lb. 80 feet\n21–55 4 ft. × 6 ft. 400 lb. 60 feet\n56–80 5 ft. × 7 ft. 600 lb. 40 feet\n81–00 6 ft. × 9 ft. 800 lb. 30 feet"},{"id":"censer-of-controlling-air-elementals","name":"Censer of Controlling Air Elementals","kind":"gear","sub":"Magic item · Wondrous Item, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"While gently swinging this censer, you can take a Magic action to summon an Air Elemental .","text":"While gently swinging this censer, you can take a Magic action to summon an Air Elemental . The elemental appears in an unoccupied space as close to the censer as possible, understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. The elemental disappears after 1 hour, when it dies, or when you dismiss it as a Bonus Action. The censer can’t be used this way again until the next dawn."},{"id":"chime-of-opening","name":"Chime of Opening","kind":"gear","sub":"Magic item · Wondrous Item, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"This hollow metal tube measures about 1 foot long and weighs 1 pound.","text":"This hollow metal tube measures about 1 foot long and weighs 1 pound. As a Magic action, you can strike the chime to cast Knock . The spell’s customary knocking sound is replaced by the clear, ringing tone of the chime, which is audible out to 300 feet. The chime can be used 10 times. After the tenth time, it cracks and becomes useless."},{"id":"circlet-of-blasting","name":"Circlet of Blasting","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"While wearing this circlet, you can cast Scorching Ray with it (+5 to hit).","text":"While wearing this circlet, you can cast Scorching Ray with it (+5 to hit). The circlet can’t cast this spell again until the next dawn."},{"id":"cloak-of-arachnida","name":"Cloak of Arachnida","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"This fine garment is made of black silk interwoven with faint, silvery threads.","text":"This fine garment is made of black silk interwoven with faint, silvery threads. While wearing it, you gain the following benefits. Poison Resistance. You have Resistance to Poison damage. Spider Climb. You have a Climb Speed equal to your Speed and can move up, down, and across vertical surfaces and along ceilings, while leaving your hands free. Spider Walk. You can’t be caught in webs of any sort and can move through webs as if they were Difficult Terrain. Web. You can cast Web (save DC 13). The web created by the spell fills twice its normal area. Once used, this property can’t be used again until the next dawn."},{"id":"cloak-of-displacement","name":"Cloak of Displacement","kind":"gear","sub":"Magic item · Wondrous Item, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"While you wear this cloak, it magically projects an illusion that makes you appear to be standing in a place near your actual location, causing any creature to have Disadvantage on attack rolls against you.","text":"While you wear this cloak, it magically projects an illusion that makes you appear to be standing in a place near your actual location, causing any creature to have Disadvantage on attack rolls against you. If you take damage, the property ceases to function until the start of your next turn. This property is suppressed while your Speed is 0."},{"id":"cloak-of-elvenkind","name":"Cloak of Elvenkind","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While you wear this cloak, Wisdom (Perception) checks made to perceive you have Disadvantage, and you have Advantage on Dexterity (Stealth) checks.","text":"While you wear this cloak, Wisdom (Perception) checks made to perceive you have Disadvantage, and you have Advantage on Dexterity (Stealth) checks."},{"id":"cloak-of-invisibility","name":"Cloak of Invisibility","kind":"gear","sub":"Magic item · Wondrous Item, Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"This cloak has 3 charges and regains 1d3 expended charges daily at dawn.","text":"This cloak has 3 charges and regains 1d3 expended charges daily at dawn. While wearing the cloak, you can take a Magic action to pull its hood over your head and expend 1 charge to give yourself the Invisible condition for 1 hour. The effect ends early if you pull the hood down (no action required) or cease wearing the cloak."},{"id":"cloak-of-protection","name":"Cloak of Protection","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"You gain a +1 bonus to Armor Class and saving throws while you wear this cloak.","text":"You gain a +1 bonus to Armor Class and saving throws while you wear this cloak."},{"id":"cloak-of-the-bat","name":"Cloak of the Bat","kind":"gear","sub":"Magic item · Wondrous Item, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"While wearing this cloak, you have Advantage on Dexterity (Stealth) checks.","text":"While wearing this cloak, you have Advantage on Dexterity (Stealth) checks. In an area of Dim Light or Darkness, you can grip the edges of the cloak and use it to gain a Fly Speed of 40 feet. If you ever fail to grip the cloak’s edges while flying in this way, or if you are no longer in Dim Light or Darkness, you lose this Fly Speed. While wearing the cloak in an area of Dim Light or Darkness, you can cast Polymorph on yourself, shape-shifting into a Bat . While in that form, you retain your Intelligence, Wisdom, and Charisma scores. The cloak can’t be used this way again until the next dawn."},{"id":"cloak-of-the-manta-ray","name":"Cloak of the Manta Ray","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While wearing this cloak, you can breathe underwater, and you have a Swim Speed of 60 feet.","text":"While wearing this cloak, you can breathe underwater, and you have a Swim Speed of 60 feet."},{"id":"crystal-ball","name":"Crystal Ball","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"While touching this crystal orb, you can cast Scrying (save DC 17) with it.","text":"While touching this crystal orb, you can cast Scrying (save DC 17) with it."},{"id":"crystal-ball-of-mind-reading","name":"Crystal Ball of Mind Reading","kind":"gear","sub":"Magic item · Wondrous Item, Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"While touching this crystal orb, you can cast Scrying (save DC 17) with it.","text":"While touching this crystal orb, you can cast Scrying (save DC 17) with it. In addition, you can cast Detect Thoughts (save DC 17) targeting creatures you can see within 30 feet of the spell’s sensor. You don’t need to concentrate on this Detect Thoughts spell to maintain it during its duration, but it ends if the Scrying spell ends."},{"id":"crystal-ball-of-telepathy","name":"Crystal Ball of Telepathy","kind":"gear","sub":"Magic item · Wondrous Item, Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"While touching this crystal orb, you can cast Scrying (save DC 17) with it.","text":"While touching this crystal orb, you can cast Scrying (save DC 17) with it. In addition, you can communicate telepathically with creatures you can see within 30 feet of the spell’s sensor. You can also cast Suggestion (save DC 17) through the sensor on one of those creatures. You don’t need to concentrate on this Suggestion to maintain it during its duration, but it ends if Scrying ends. You can’t cast Suggestion in this way again until the next dawn."},{"id":"crystal-ball-of-true-seeing","name":"Crystal Ball of True Seeing","kind":"gear","sub":"Magic item · Wondrous Item, Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"While touching this crystal orb, you can cast Scrying (save DC 17) with it.","text":"While touching this crystal orb, you can cast Scrying (save DC 17) with it. In addition, you have Truesight with a range of 120 feet centered on the spell’s sensor."},{"id":"cube-of-force","name":"Cube of Force","kind":"gear","sub":"Magic item · Wondrous Item, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This cube is about an inch across.","text":"This cube is about an inch across. Each face has a distinct marking on it. You can press one of those faces, expend the number of charges required for it, and thereby cast the spell associated with it (save DC 17), as shown in the Cube of Force Faces table. The cube starts with 10 charges, and it regains 1d6 Cube expended of Force charges Faces daily at dawn.\nSpell Charge Cost\nMage Armor 1\nShield 1\nTiny Hut 3\nPrivate Sanctum 4\nResilient Sphere 4\nWall of Force 5"},{"id":"cubic-gate","name":"Cubic Gate","kind":"gear","sub":"Magic item · Wondrous Item, Legendary","magic":true,"rarity":"Legendary","attunement":false,"w":0,"c":200000,"notes":"This cube is 3 inches across and radiates palpable magical energy.","text":"This cube is 3 inches across and radiates palpable magical energy. The six sides of the cube are each keyed to a different plane of existence, one of which is the Material Plane. The other sides are linked to planes determined by the GM. The cube has 3 charges and regains 1d3 expended charges daily at dawn. As a Magic action, you can expend 1 of the cube’s charges to cast one of the following spells using the cube. Gate. Pressing one side of the cube, you cast Gate , opening a portal to the plane of existence keyed to that side. Plane Shift. Pressing one side of the cube twice, you cast Plane Shift , transporting the targets to the plane of existence keyed to that side."},{"id":"dagger-of-venom","name":"Dagger of Venom","kind":"gear","sub":"Magic item · Weapon (Dagger), Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon.","text":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. You can take a Bonus Action to magically coat the blade with poison. The poison remains for 1 minute or until an attack using this weapon hits a creature. That creature must succeed on a DC 15 Constitution saving throw or take 2d10 Poison damage and have the Poisoned condition for 1 minute. The weapon can’t be used this way again until the next dawn."},{"id":"dancing-sword","name":"Dancing Sword","kind":"gear","sub":"Magic item · Weapon (Greatsword, Longsword, Rapier, Scimitar, or Shortsword), Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"You can take a Bonus Action to toss this magic weapon into the air.","text":"You can take a Bonus Action to toss this magic weapon into the air. When you do so, the weapon begins to hover, flies up to 30 feet, and attacks one creature of your choice within 5 feet of itself. The weapon uses your attack roll and adds your ability modifier to damage rolls. While the weapon hovers, you can take a Bonus Action to cause it to fly up to 30 feet to another spot within 30 feet of you. As part of the same Bonus Action, you can cause the weapon to attack one creature within 5 feet of the weapon. After the hovering weapon attacks for the fourth time, it flies back to you and tries to return to your hand. If you have no hand free, the weapon falls to the ground in your space. If the weapon has no unobstructed path to you, it moves as close to you as it can and then falls to the ground. It also ceases to hover if you grasp it or are more than 30 feet away from it."},{"id":"decanter-of-endless-water","name":"Decanter of Endless Water","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"This stoppered flask sloshes when shaken, as if it contains water.","text":"This stoppered flask sloshes when shaken, as if it contains water. The decanter weighs 2 pounds. You can take a Magic action to remove the stopper and issue one of three command words, whereupon an amount of fresh water or salt water (your choice) pours out of the flask. The water stops pouring out at the start of your next turn. Choose from the following command words: Splash. The decanter produces 1 gallon of water. Fountain. The decanter produces 5 gallons of water. Geyser. The decanter produces 30 gallons of water that gushes forth in a Line 30 feet long and 1 foot wide. If you’re holding the decanter, you can aim the geyser in one direction (no action required). One creature of your choice in the Line must succeed on a DC 13 Strength saving throw or take 1d4 Bludgeoning damage and have the Prone condition. Instead of a creature, you can target one object in the Line that isn’t being worn or carried and that weighs no more than 200 pounds. The object is knocked over by the geyser."},{"id":"deck-of-illusions","name":"Deck of Illusions","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"This box contains a set of cards.","text":"This box contains a set of cards. A full deck has 34 cards: 32 depicting specific creatures and two with a mirrored surface. A deck found as treasure is usually missing 1d20 − 1 cards. The magic of the deck functions only if its cards are drawn at random. You can take a Magic action to draw a card at random from the deck and throw it to the ground at a point within 30 feet of yourself. An illusion of a creature, determined by rolling on the Deck of Illusions table, forms over the thrown card and remains until dispelled. The illusory creature created by the card looks and behaves like a real creature of its kind, except that it can do no harm. While you are within 120 feet of the illusory creature and can see it, you can take a Magic action to move it anywhere within 30 feet of its card. Any physical interaction with the illusory creature reveals it to be false, because objects pass through it. A creature that takes a Study action to visually inspect the illusory creature identifies it as an illusion with a successful DC 15 Intelligence (Investigation) check. The illusion lasts until its card is moved or the illusion is dispelled (using a Dispel Magic spell or a similar effect). When the illusion ends, the image on its card disappears, and that\nDeck card can’t of Illusions be used again.\n1d100 Illusion*\n01–03 Adult Red Dragon\n04–06 Archmage\n07–09 Assassin\n10–12 Bandit Captain\n13–15 Basilisk\n16–18 Berserker\n19–21 Bugbear Warrior\n22–24 Cloud Giant\n25–27 Druid\n28–30 Erinyes\n31–33 Ettin\n34–36 Fire Giant\n37–39 Frost Giant\n40–42 Gnoll Warrior\n43–45 Goblin Warrior\n46–48 Guardian Naga\n49–51 Hill Giant\n52–54 Hobgoblin Warrior\n55–57 Incubus\n58–60 Iron Golem\n61–63 Knight\n64–66 Kobold Warrior\n67–69 Lich\n70–72 Medusa\n73–75 Night Hag\n76–78 Ogre\n79–81 Oni\n1d100 Illusion*\n82–84 Priest\n85–87 Succubus\n88–90 Troll\n91–93 Veteran Warrior\n94–96 Wyvern\n97–00 The card drawer\n*Stat blocks for these creatures (except the card drawer) appear in\n“Monsters.”"},{"id":"defender","name":"Defender","kind":"gear","sub":"Magic item · Weapon (Any Melee Weapon), Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon.","text":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. The first time you attack with the weapon on each of your turns, you can transfer some or all of the weapon’s bonus to your Armor Class. For example, you could reduce the bonus to your attack rolls and damage rolls to +1 and gain a +2 bonus to Armor Class. The adjusted bonuses remain in effect until the start of your next turn, although you must hold the weapon to gain a bonus to AC from it."},{"id":"demon-armor","name":"Demon Armor","kind":"gear","sub":"Magic item · Armor (Any Light, Medium, or Heavy), Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"While wearing this armor, you gain a +1 bonus to Armor Class, and you know Abyssal.","text":"While wearing this armor, you gain a +1 bonus to Armor Class, and you know Abyssal. In addition, the armor’s clawed gauntlets allow your Unarmed Strikes to deal 1d8 Slashing damage instead of the usual Bludgeoning damage, and you gain a +1 bonus to the attack and damage rolls of your Unarmed Strikes. Curse. Once you don this cursed armor, you can’t doff it unless you are targeted by a Remove Curse spell or similar magic. While wearing the armor, you have Disadvantage on attack rolls against demons and on saving throws against their spells and special abilities."},{"id":"dimensional-shackles","name":"Dimensional Shackles","kind":"gear","sub":"Magic item · Wondrous Item, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"You can take a Utilize action to place these shackles on a creature that has the Incapacitated condition.","text":"You can take a Utilize action to place these shackles on a creature that has the Incapacitated condition. The shackles adjust to fit a creature of Small to Large size. The shackles prevent a creature bound by them from using any method of extradimensional movement, including teleportation or travel to a different plane of existence. They don’t prevent the creature from passing through an interdimensional portal. You and any creature you designate when you use the shackles can take a Utilize action to remove them. Once every 30 days, the bound creature can make a DC 30 Strength (Athletics) check. On a successful check, the creature breaks free and destroys the shackles."},{"id":"dragon-orb","name":"Dragon Orb","kind":"gear","sub":"Magic item · Wondrous Item, Artifact (Requires Attunement)","magic":true,"rarity":"Artifact","attunement":true,"w":0,"c":0,"notes":"An orb is an etched crystal globe about 10 inches in diameter.","text":"An orb is an etched crystal globe about 10 inches in diameter. When used, it grows to about 20 inches in diameter, and mist swirls inside it. While attuned to an orb, you can take a Magic action to peer into the orb’s depths. You must then make a DC 15 Charisma saving throw. On a successful save, you control the orb for as long as you remain attuned to it. On a failed save, the orb imposes the Charmed condition on you for as long as you remain attuned to it. While you are Charmed by the orb, you can’t voluntarily end your Attunement to it, and the orb casts Suggestion on you at will (save DC 18), urging you to work toward the evil ends it desires. The dragon essence within the orb might want many things: the annihilation of a particular society or organization, freedom from the orb, to spread suffering in the world, to advance the worship of Tiamat, or something else the GM decides. Spells. The orb has 7 charges and regains 1d4 + 3 expended charges daily at dawn. If you control the orb, you can cast one of the spells on the following table from it. The table indicates how many charges you must expend to cast the spell.\nSpell Charge\nCost\nCure Wounds (level 9 version) 4\nDaylight 1\nDeath Ward 2\nDetect Magic 0\nScrying (save DC 18) 3\nCall Dragons.\nWhile you control the orb, you can take a Magic action to cause the orb to issue a telepathic call that extends in all directions for 40 miles. Chromatic dragons in range feel compelled to come to the orb as soon as possible by the most direct route. Dragon deities such as Tiamat are unaffected by this call. Chromatic dragons drawn to the orb might be Hostile toward you for compelling them against their will. Once you have used this property, it can’t be used again for 1 hour. Destroying an Orb. A Dragon Orb has AC 20 and is destroyed if it takes damage from a +3 Weapon or a Disintegrate spell. Nothing else can harm it."},{"id":"dragon-scale-mail","name":"Dragon Scale Mail","kind":"gear","sub":"Magic item · Armor (Scale Mail), Very Rare (Requires Attunement) Dragon Scale Mail","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"is made of the scales of one kind of dragon.","text":"is made of the scales of one kind of dragon. Sometimes dragons collect their cast-off scales and gift them. Other times, hunters carefully preserve the hide of a dead dragon. In either case, Dragon Scale Mail is highly valued. While wearing this armor, you gain a +1 bonus to Armor Class, you have Advantage on saving throws against the breath weapons of Dragons, and you have Resistance to one damage type determined by the kind of dragon that provided the scales (see the accompanying table). Additionally, you can focus your senses as a Magic action to discern the distance and direction to the closest dragon within 30 miles of yourself that is of the same type as the armor. This action can’t be used again until the next dawn.\nDragon Resistance Dragon Resistance\nBlack Acid Gold Fire\nBlue Lightning Green Poison\nBrass Fire Red Fire\nBronze Lightning Silver Cold\nCopper Acid White Cold"},{"id":"dragon-slayer","name":"Dragon Slayer","kind":"gear","sub":"Magic item · Weapon (Any Simple or Martial), Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon.","text":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. The weapon deals an extra 3d6 damage of the weapon’s type if the target is a Dragon."},{"id":"dust-of-disappearance","name":"Dust of Disappearance","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"This powder resembles fine sand.","text":"This powder resembles fine sand. There is enough of it for one use. When you take a Utilize action to throw the dust into the air, you and each creature and object within a 10-foot Emanation originating from you have the Invisible condition for 2d4 minutes. The duration is the same for all subjects, and the dust is consumed when its magic takes effect. Immediately after an affected creature makes an attack roll, deals damage, or casts a spell, the Invisible condition ends for that creature."},{"id":"dust-of-dryness","name":"Dust of Dryness","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"This small packet contains 1d6 + 4 pinches of dust.","text":"This small packet contains 1d6 + 4 pinches of dust.\nAs a Utilize action, you can sprinkle a pinch of the dust over water, turning up to a 15-foot Cube of water into one marble-sized pellet, which floats or rests near where the dust was sprinkled. The pellet’s weight is negligible. A creature can take a Utilize action to smash the pellet against a hard surface, causing the pellet to shatter and release the water the dust absorbed. Doing so destroys the pellet and ends its magic. As a Utilize action, you can sprinkle a pinch of the dust on an Elemental within 5 feet of yourself that is composed mostly of water (such as a Water Elemental ). Such a creature exposed to a pinch of the dust makes a DC 13 Constitution saving throw, taking 10d6 Necrotic damage on a failed save or half as much damage on a successful one."},{"id":"dust-of-sneezing-and-choking","name":"Dust of Sneezing and Choking","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"Found in a small container, this powder resembles Dust of Disappearance , and Identify reveals it to be such.","text":"Found in a small container, this powder resembles Dust of Disappearance , and Identify reveals it to be such. There is enough of it for one use. As a Utilize action, you can throw the dust into the air, forcing yourself and every creature in a 30-foot Emanation originating from you to make a DC 15 Constitution saving throw. Constructs, Elementals, Oozes, Plants, and Undead succeed on the save automatically. On a failed save, a creature begins sneezing uncontrollably; it has the Incapacitated condition and is suffocating. The creature repeats the save at the end of each of its turns, ending the effect on itself on a success. The effect also ends on any creature targeted by a Lesser Restoration spell."},{"id":"dwarven-plate","name":"Dwarven Plate","kind":"gear","sub":"Magic item · Armor (Half Plate Armor or Plate Armor), Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0,"c":40000,"notes":"While wearing this armor, you gain a +2 bonus to Armor Class.","text":"While wearing this armor, you gain a +2 bonus to Armor Class. In addition, if an effect moves you against your will along the ground, you can take a Reaction to reduce the distance you are moved by up to 10 feet."},{"id":"dwarven-thrower","name":"Dwarven Thrower","kind":"gear","sub":"Magic item · Weapon (Warhammer), Very Rare (Requires Attunement by a Dwarf or a Creature Attuned to a Belt of Dwarvenkind)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon.","text":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. It has the Thrown property with a normal range of 20 feet and a long range of 60 feet. When you hit with a ranged attack using this weapon, it deals an extra 1d8 Force damage, or an extra 2d8 Force damage if the target is a Giant. Immediately after hitting or missing, the weapon flies back to your hand."},{"id":"efficient-quiver","name":"Efficient Quiver","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"Each of the quiver’s three compartments connects to an extradimensional space that allows the quiver to hold numerous items while never weighing more than 2 pounds.","text":"Each of the quiver’s three compartments connects to an extradimensional space that allows the quiver to hold numerous items while never weighing more than 2 pounds. The shortest compartment can hold up to 60 Arrows, Bolts, or similar objects. The midsize compartment holds up to 18 Javelins or similar objects. The longest compartment holds up to 6 long objects, such as bows, Quarterstaffs, or Spears. You can draw any item the quiver contains as if doing so from a regular quiver or scabbard."},{"id":"efreeti-bottle","name":"Efreeti Bottle","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0,"c":40000,"notes":"When you take a Magic action to remove the stopper of this painted brass bottle, a cloud of thick smoke flows out of it.","text":"When you take a Magic action to remove the stopper of this painted brass bottle, a cloud of thick smoke flows out of it. At the end of your turn, the smoke disappears with a flash of harmless fire, and an Efreeti appears in an unoccupied space within 30 feet of you. The first time the bottle is opened, the GM rolls on the following table to determine what happens.\n1d10 Effect\n1 The efreeti attacks you. After fighting for 5\nrounds, the efreeti disappears, and the bottle\nloses its magic.\n2–9 The efreeti understands your languages and\nobeys your commands for 1 hour, after which\nit returns to the bottle, and a new stopper\ncontains it. The stopper can’t be removed for\n24 hours. The next two times the bottle is\nopened, the same effect occurs. If the bottle is\nopened a fourth time, the efreeti escapes and\ndisappears, and the bottle loses its magic.\n10 The efreeti understands your languages and can\ncast Wish once for you. It disappears when it\ngrants the wish or after 1 hour, and the bottle\nloses its magic."},{"id":"elemental-gem","name":"Elemental Gem","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"This gem contains a mote of elemental energy.","text":"This gem contains a mote of elemental energy.\nWhen you take a Utilize action to break the gem, an elemental is summoned (see “Monsters” for its stat block), and the gem ceases to be magical. The elemental appears in an unoccupied space as close to the broken gem as possible, understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. The elemental disappears after 1 hour, when it dies, or when you dismiss it as a Bonus Action. The type of gem determines the elemental, as shown in the following table.\nGem Summoned Elemental\nBlue sapphire Air Elemental\nEmerald Water Elemental\nRed corundum Fire Elemental\nYellow diamond Earth Elemental"},{"id":"elixir-of-health","name":"Elixir of Health","kind":"gear","sub":"Magic item · Potion, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0.5,"c":2000,"notes":"When you drink this potion, you are cured of all magical contagions.","text":"When you drink this potion, you are cured of all magical contagions. In addition, the following conditions end on you: Blinded, Deafened, Paralyzed, and Poisoned. The clear, red liquid has tiny bubbles of light in it.","stack":true},{"id":"elven-chain","name":"Elven Chain","kind":"gear","sub":"Magic item · Armor (Chain Mail or Chain Shirt), Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"You gain a +1 bonus to Armor Class while you wear this armor.","text":"You gain a +1 bonus to Armor Class while you wear this armor. You are considered trained with this armor even if you lack training with Medium or Heavy armor."},{"id":"energy-bow","name":"Energy Bow","kind":"gear","sub":"Magic item · Weapon (Longbow or Shortbow), Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon, which has no string.","text":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon, which has no string. Each time you pull your arm back in a firing motion, a magical arrow made of golden energy appears nocked and ready to fire. An arrow produced by this weapon deals Force damage instead of Piercing damage on a hit, and it disappears after it hits or misses its target. Until it disappears, the arrow emits Bright Light in a 20-foot radius and Dim Light for an additional 20 feet. This weapon has the following additional properties. Arrow of Restraint. Whenever you use this weapon to make a ranged attack against a creature, you can try to restrain the target instead of dealing damage to it. If the arrow hits, the target must succeed on a DC 15 Strength saving throw or have the Restrained condition for 1 minute. As an action, a creature Restrained by an arrow can make a DC 20 Strength (Athletics) check to try to break the restraint, ending the effect on itself on a successful check. Arrow of Transport. As a Magic action, you can fire one energy arrow from this weapon at a target you can see within 60 feet of yourself. The target can be either a willing Medium or smaller creature or an object that isn’t being worn or carried, provided the object is small enough to fit inside a 5-foot Cube. The arrow teleports the target to an unoccupied space you can see within 10 feet of you. Energy Ladder. As a Magic action, you can loose a flurry of energy arrows from this weapon at a wall up to 60 feet away from yourself. The arrows become glowing rungs that stick out of the wall, forming a magical ladder up to 60 feet long on the wall. This ladder lasts for 1 minute before disappearing."},{"id":"eversmoking-bottle","name":"Eversmoking Bottle","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"As a Magic action, you can open or close this bottle.","text":"As a Magic action, you can open or close this bottle.\nOpening the bottle causes thick smoke to billow out, forming a cloud that fills a 60-foot Emanation originating from the bottle. The area within the smoke is Heavily Obscured. Each minute the bottle remains open, the size of the Emanation increases by 10 feet until it reaches its maximum size of 120 feet. Closing the bottle causes the cloud to become fixed in place until it disperses after 10 minutes. A strong wind (such as that created by the Gust of Wind spell) disperses the cloud after 1 minute."},{"id":"eyes-of-charming","name":"Eyes of Charming","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"These crystal lenses fit over the eyes.","text":"These crystal lenses fit over the eyes. They have 3 charges. While wearing them, you can expend 1 or more charges to cast Charm Person (save DC 13). For 1 charge, you cast the level 1 version of the spell. You increase the spell’s level by one for each additional charge you expend. The lenses regain all expended charges daily at dawn."},{"id":"eyes-of-minute-seeing","name":"Eyes of Minute Seeing","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"These crystal lenses fit over the eyes.","text":"These crystal lenses fit over the eyes. While wearing them, your vision improves significantly out to a range of 1 foot, granting you Darkvision within that range and Advantage on Intelligence (Investigation) checks made to examine something within that range."},{"id":"eyes-of-the-eagle","name":"Eyes of the Eagle","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"These crystal lenses fit over the eyes.","text":"These crystal lenses fit over the eyes. While wearing them, you have Advantage on Wisdom (Perception) checks that rely on sight. In conditions of clear visibility, you can make out details of even extremely distant creatures and objects as small as 2 feet across."},{"id":"feather-token","name":"Feather Token","kind":"gear","sub":"Magic item · Wondrous Item, Rarity Varies","magic":true,"rarity":"Varies","attunement":false,"w":0,"c":0,"notes":"This object looks like a feather.","text":"This object looks like a feather. Different types of feather tokens exist, each with a different single-use effect. The GM chooses the kind of token or determines it randomly by rolling on the Feather Tokens table. The type of token determines its rarity. Anchor (Uncommon). You can take a Magic action to touch the token to a boat or ship. For the next 24 hours, the vessel can’t be moved by any means. Touching the token to the vessel again ends the effect. When the effect ends, the token disappears. Bird (Rare). You can take a Magic action to toss the token 5 feet into the air. The token disappears and an enormous, multicolored bird takes its place. The bird has the statistics of a Roc , but it can’t attack. It obeys your simple commands and can carry up to 500 pounds while flying at its maximum speed (16 miles per hour for a maximum of 144 miles per day, with a 1-hour rest for every 3 hours of flying) or 1,000 pounds at half that speed. The bird disappears after flying its maximum distance for a day or if it drops to 0 Hit Points. You can dismiss the bird as a Magic action. Fan (Uncommon). If you are on a boat or ship, you can take a Magic action to toss the token up to 10 feet in the air. The token disappears, and a giant flapping fan takes its place. The fan floats and creates a strong wind. This wind can fill the sails of one ship, increasing its speed by 5 miles per hour for 8 hours. You can dismiss the fan as a Magic action. Swan Boat (Rare). You can take a Magic action to touch the token to a body of water at least 60 feet in diameter. The token disappears, and a 50-footlong, 20-foot-wide boat shaped like a swan takes its place. The boat is self-propelled and moves across water at a speed of 6 miles per hour. You can take a Magic action while on the boat to command it to move or to turn up to 90 degrees. The boat remains for 24 hours and then disappears. You can dismiss the boat as a Magic action. Tree (Uncommon). You must be outdoors to use this token. You can take a Magic action to touch it to an unoccupied space on the ground. The token disappears, and in its place a nonmagical oak tree springs into existence. The tree is 60 feet tall and has a 5-foot-diameter trunk, and its branches at the top spread out in a 20-foot radius. Whip (Rare). You can take a Magic action to throw the token to a point within 10 feet of yourself. The token disappears, and a floating whip takes its place. You can then take a Bonus Action to make a melee spell attack against a creature within 10 feet of the whip, with an attack bonus of +9. On a hit, the target takes 1d6 + 5 Force damage. As a Bonus Action, you can direct the whip to fly up to 20 feet and repeat the attack against a creature within 10 feet of the whip. The whip disappears after 1 hour, when you take a Magic action to dismiss it, or\nFeather when you Tokens die or have the Incapacitated condition.\n1d100 Token Rarity\n01–20 Anchor Uncommon\n21–35 Bird Rare\n36–50 Fan Uncommon\n51–65 Swan boat Rare\n66–90 Tree Uncommon\n91–00 Whip Rare"},{"id":"figurine-of-wondrous-power","name":"Figurine of Wondrous Power","kind":"gear","sub":"Magic item · Wondrous Item, Rarity Varies","magic":true,"rarity":"Varies","attunement":false,"w":0,"c":0,"notes":"A Figurine of Wondrous Power is a statuette small enough to fit in a pocket.","text":"A Figurine of Wondrous Power is a statuette small enough to fit in a pocket. If you take a Magic action to throw the figurine to a point on the ground within 60 feet of yourself, the figurine becomes a living creature specified in the figurine’s description below. If the space where the creature would appear is occupied by other creatures or objects, or if there isn’t enough space for the creature, the figurine doesn’t become a creature. The creature is Friendly to you and your allies. It understands your languages, obeys your commands, and takes its turn immediately after you on your Initiative count. If you issue no commands, the creature defends itself but takes no other actions. The creature exists for a duration specific to each figurine. At the end of the duration, the creature reverts to its figurine form. It reverts to a figurine early if its creature form drops to 0 Hit Points or if you take a Magic action while touching the creature to make it revert to figurine form. When the creature becomes a figurine again, its property can’t be used again until a certain amount of time has passed, as specified in the figurine’s description. Bronze Griffon (Rare). This bronze statuette is of a griffon rampant. It can become a Griffon for up to 6 hours. Once it has been used, it can’t be used again until 5 days have passed. Ebony Fly (Rare). This ebony statuette, carved in the likeness of a horsefly, can become a Giant Fly (see the accompanying stat block) for up to 12 hours and can be ridden as a mount. Once it has been used, it Giant can’t be Fly used again until 2 days have passed. Large Beast, Unaligned AC 11 Initiative +1 (11) HP 19 (3d10 + 3) Speed 30 ft., Fly 60 ft.\nMOD SAVE MOD SAVE MOD SAVE\nS tr 14 +2 +2 D ex 13 +1 +1 C on 13 +1 +1\nI nt 2 −4 −4 W IS 10 +0 +0 C ha 3 −4 −4\nSenses Darkvision 60 ft., Passive Perception 10 Languages None CR 0 (XP 0; PB +2) Golden Lions (Rare). These gold statuettes of lions are always created in pairs. You can use one figurine or both simultaneously. Each can become a Lion for up to 1 hour. Once a lion has been used, it can’t be used again until 7 days have passed. Ivory Goats (Rare). These ivory statuettes of goats are always created in sets of three. Each goat looks unique and functions differently from the others. Their properties are as follows: Goat of Terror. This figurine can become a Giant Goat for up to 3 hours. The goat can’t attack, but you can (harmlessly) remove its horns and use them as weapons. One horn becomes a +1 Lance , and the other becomes a +2 Longsword . Removing a horn requires a Magic action, and the weapons disappear and the horns return when the goat reverts to figurine form. While you ride the goat, any Hostile creature that starts its turn within a 30-foot Emanation originating from the goat must succeed on a DC 15 Wisdom saving throw or have the Frightened condition for 1 minute, until you are no longer riding the goat, or until the goat reverts to figurine form. The Frightened creature repeats the save at the end of each of its turns, ending the effect on itself on a success. Once it succeeds on the save, a creature is immune to this effect for the next 24 hours. Once the figurine has been used, it can’t be used again until 15 days have passed. Goat of Traveling. This figurine can become a Large goat with the same statistics as a Riding Horse . It has 24 charges, and each hour or portion thereof it spends in goat form costs 1 charge. While it has charges, you can use it as often as you wish. When it runs out of charges, it reverts to a figurine and can’t be used again until 7 days have passed, when it regains all expended charges. Goat of Travail. This figurine can become a Giant Goat for up to 3 hours. Once it has been used, it can’t be used again until 30 days have passed. Marble Elephant (Rare). This marble statuette resembles a trumpeting elephant. It can become an Elephant for up to 24 hours. Once it has been used, it can’t be used again until 7 days have passed. Obsidian Steed (Very Rare). This polished obsidian horse can become a Nightmare for up to 24 hours. The nightmare fights only to defend itself. Once it has been used, it can’t be used again until 5 days have passed. The figurine has a 10 percent chance each time you use it to ignore your orders, including a command to revert to figurine form. If you mount the nightmare while it is ignoring your orders, you and the nightmare are instantly transported to a random location on the plane of Hades, where the nightmare reverts to figurine form. Onyx Dog (Rare). This onyx statuette of a dog can become a Mastiff for up to 6 hours. The mastiff has an Intelligence of 8 and can speak Common. It also has Blindsight with a range of 60 feet. Once it has been used, it can’t be used again until 7 days have passed. Serpentine Owl (Rare). This serpentine statuette of an owl can become a Giant Owl for up to 8 hours. The owl can communicate telepathically with you at any range if you and it are on the same plane of existence. Once it has been used, it can’t be used again until 2 days have passed. Silver Raven (Uncommon). This silver statuette of a raven can become a Raven for up to 12 hours. Once it has been used, it can’t be used again until 2 days have passed. While in raven form, the figurine grants you the ability to cast Animal Messenger on it."},{"id":"flame-tongue","name":"Flame Tongue","kind":"gear","sub":"Magic item · Weapon (Any Melee Weapon), Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"While holding this magic weapon, you can take a Bonus Action and use a command word to cause flames to engulf the damage-dealing part of the weapon.","text":"While holding this magic weapon, you can take a Bonus Action and use a command word to cause flames to engulf the damage-dealing part of the weapon. These flames shed Bright Light in a 40- foot radius and Dim Light for an additional 40 feet. While the weapon is ablaze, it deals an extra 2d6 Fire damage on a hit. The flames last until you take a Bonus Action to issue the command again or until you drop, stow, or sheathe the weapon."},{"id":"folding-boat","name":"Folding Boat","kind":"gear","sub":"Magic item · Wondrous Item, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"This object appears as a wooden box that measures 12 inches long, 6 inches wide, and 6 inches deep.","text":"This object appears as a wooden box that measures 12 inches long, 6 inches wide, and 6 inches deep. It weighs 4 pounds and floats. It can be opened to store items inside. This item also has three command words, each requiring a Magic action to use: First Command Word. The box unfolds into a Rowboat. Second Command Word. The box unfolds into a Keelboat. Third Command Word. The Folding Boat folds back into a box if no creatures are aboard. Any objects in the vessel that can’t fit inside the box remain outside the box as it folds. Any objects in the vessel that can fit inside the box do so. When the box becomes a vessel, its weight becomes that of a normal vessel its size, and anything that was stored in the box remains in the boat. Statistics for the Rowboat and Keelboat appear in “Equipment.” If either vessel is reduced to 0 Hit Points, the Folding Boat is destroyed."},{"id":"frost-brand","name":"Frost Brand","kind":"gear","sub":"Magic item · Weapon (Glaive, Greatsword, Longsword, Rapier, Scimitar, or Shortsword), Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"When you hit with an attack roll using this magic weapon, the target takes an extra 1d6 Cold damage.","text":"When you hit with an attack roll using this magic weapon, the target takes an extra 1d6 Cold damage. In addition, while you hold the weapon, you have Resistance to Fire damage. In freezing temperatures, the weapon sheds Bright Light in a 10-foot radius and Dim Light for an additional 10 feet. When you draw this weapon, you can extinguish all nonmagical flames within 30 feet of yourself. Once used, this property can’t be used again for 1 hour."},{"id":"gauntlets-of-ogre-power","name":"Gauntlets of Ogre Power","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"Your Strength is 19 while you wear these gauntlets.","text":"Your Strength is 19 while you wear these gauntlets.\nThey have no effect on you if your Strength is 19 or higher without them."},{"id":"gem-of-brightness","name":"Gem of Brightness","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"This prism has 50 charges.","text":"This prism has 50 charges. While you are holding it, you can take a Magic action and use one of three command words to cause one of the following effects: First Command Word. The gem sheds Bright Light in a 30-foot radius and Dim Light for an additional 30 feet. This effect doesn’t expend a charge. It lasts until you take a Bonus Action to repeat the command word or until you use another function of the gem. Second Command Word. You expend 1 charge and cause the gem to fire a brilliant beam of light at one creature you can see within 60 feet of yourself. The creature must succeed on a DC 15 Constitution saving throw or have the Blinded condition for 1 minute. The creature repeats the save at the end of each of its turns, ending the effect on itself on a success. Third Command Word. You expend 5 charges and cause the gem to flare with intense light in a 30- foot Cone. Each creature in the Cone makes a saving throw as if struck by the beam created with the second command word. When all of the gem’s charges are expended, the gem becomes a nonmagical jewel worth 50 GP."},{"id":"gem-of-seeing","name":"Gem of Seeing","kind":"gear","sub":"Magic item · Wondrous Item, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This gem has 3 charges.","text":"This gem has 3 charges. As a Magic action, you can expend 1 charge. For the next 10 minutes, you have Truesight out to 120 feet when you peer through the gem. The gem regains 1d3 expended charges daily at dawn."},{"id":"giant-slayer","name":"Giant Slayer","kind":"gear","sub":"Magic item · Weapon (Any Simple or Martial), Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon.","text":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. When you hit a Giant with this weapon, the Giant takes an extra 2d6 damage of the weapon’s type and must succeed on a DC 15 Strength saving throw or have the Prone condition."},{"id":"glamoured-studded-leather","name":"Glamoured Studded Leather","kind":"gear","sub":"Magic item · Armor (Studded Leather Armor), Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"While wearing this armor, you gain a +1 bonus to Armor Class.","text":"While wearing this armor, you gain a +1 bonus to Armor Class. You can also take a Bonus Action to cause the armor to assume the appearance of a normal set of clothing or some other kind of armor. You decide what it looks like—including color, style, and accessories—but the armor retains its normal bulk and weight. The illusory appearance lasts until you use this property again or doff the armor."},{"id":"gloves-of-missile-snaring","name":"Gloves of Missile Snaring","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"If you’re hit by an attack roll made with a Ranged or Thrown weapon while wearing these gloves, you can take a Reaction to reduce the damage by 1d10 plus your Dexterity modifier if you have a free hand.","text":"If you’re hit by an attack roll made with a Ranged or Thrown weapon while wearing these gloves, you can take a Reaction to reduce the damage by 1d10 plus your Dexterity modifier if you have a free hand. If you reduce the damage to 0, you can catch the ammunition or weapon if it is small enough for you to hold in that hand."},{"id":"gloves-of-swimming-and-climbing","name":"Gloves of Swimming and Climbing","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While wearing these gloves, you have a Climb Speed and a Swim Speed equal to your Speed, and you gain a +5 bonus to Strength (Athletics) checks made to climb or swim.","text":"While wearing these gloves, you have a Climb Speed and a Swim Speed equal to your Speed, and you gain a +5 bonus to Strength (Athletics) checks made to climb or swim."},{"id":"gloves-of-thievery","name":"Gloves of Thievery","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"These gloves are imperceptible while worn.","text":"These gloves are imperceptible while worn. While wearing them, you gain a +5 bonus to Dexterity (Sleight of Hand) checks."},{"id":"goggles-of-night","name":"Goggles of Night","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"While wearing these dark lenses, you have Darkvision out to 60 feet.","text":"While wearing these dark lenses, you have Darkvision out to 60 feet. If you already have Darkvision, wearing the goggles increases its range by 60 feet."},{"id":"hammer-of-thunderbolts","name":"Hammer of Thunderbolts","kind":"gear","sub":"Magic item · Weapon (Maul or Warhammer), Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon.","text":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. The weapon has 5 charges. You can expend 1 charge and make a ranged attack with the weapon, hurling it as if it had the Thrown property with a normal range of 20 feet and a long range of 60 feet. If the attack hits, the weapon unleashes a thunderclap audible out to 300 feet. The target and every creature within 30 feet of it other than you must succeed on a DC 17 Constitution saving throw or have the Stunned condition until the end of your next turn. Immediately after hitting or missing, the weapon flies back to your hand. The weapon regains 1d4 + 1 expended charges daily at dawn. Giant’s Bane. While you are attuned to the weapon and wearing either a Belt of Giant Strength or Gauntlets of Ogre Power to which you are also attuned, you gain the following benefits: Giants’ Bane. When you roll a 20 on the d20 for an attack roll made with this weapon against a Giant, the creature must succeed on a DC 17 Constitution saving throw or die. Might of Giants. The Strength score bestowed by your Belt of Giant Strength or Gauntlets of Ogre Power increases by 4, to a maximum of 30."},{"id":"handy-haversack","name":"Handy Haversack","kind":"gear","sub":"Magic item · Wondrous Item, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"This backpack has a central pouch and two side pouches, each of which is an extradimensional space.","text":"This backpack has a central pouch and two side pouches, each of which is an extradimensional space. Each side pouch can hold up to 200 pounds of material, not exceeding a volume of 25 cubic feet. The central pouch can hold up to 500 pounds of material, not exceeding a volume of 64 cubic feet. The haversack always weighs 5 pounds, regardless of its contents. Retrieving an item from the haversack requires a Utilize action or a Bonus Action (your choice). When you reach into the haversack for a specific item, the item is always magically on top. If any of its pouches is overloaded, pierced, or torn, the haversack ruptures and is destroyed. If the haversack is destroyed, its contents are lost forever, although an Artifact always turns up again somewhere. If the haversack is turned inside out, its contents spill forth unharmed, and the haversack must be put right before it can be used again. Each pouch of the haversack holds enough air for 10 minutes of breathing, divided by the number of breathing creatures inside. Placing the haversack inside an extradimensional space created by a Bag of Holding , Portable Hole , or similar item instantly destroys both items and opens a gate to the Astral Plane. The gate originates where the one item was placed inside the other. Any creature within 10 feet of the gate and not behind Total Cover is sucked through it and deposited in a random location on the Astral Plane. The gate then closes. The gate is one-way only and can’t be reopened."},{"id":"hat-of-disguise","name":"Hat of Disguise","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While wearing this hat, you can cast the Disguise Self spell.","text":"While wearing this hat, you can cast the Disguise Self spell. The spell ends if the hat is removed."},{"id":"hat-of-many-spells","name":"Hat of Many Spells","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare (Requires Attunement by a Wizard)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"This pointed hat has the following properties.","text":"This pointed hat has the following properties.\nSpellcasting Focus.\nWhile holding the hat, you can use it as a Spellcasting Focus for your Wizard spells. Any spell you cast using the hat gains a special Somatic component: you must reach into the hat and “pull” the spell out of it. Unknown Spell. While holding the hat, you can try to cast a level 1+ spell you don’t know. The spell must be on the Wizard spell list, it must be of a level you can cast, and it can’t have Material components costing more than 1,000 GP. Once you decide on the spell, you must expend a spell slot of the spell’s level. Then, to determine whether you cast the spell, make an Intelligence (Arcana) check (DC 10 plus the spell’s level). On a successful check, you cast the spell using its normal casting time, and you can’t use this property again until you finish a Short or Long Rest. On a failed check, you fail to cast the spell and a random effect occurs instead, determined by rolling on the following table. Any spell you cast from the hat uses your spell save DC and spell attack bonus.\n1d100 Effect\n01–50 You cast a random spell determined by rolling\n1d10: on a 1 , Enlarge/Reduce (enlarge effect);\non a 2 , Enlarge/Reduce (reduce effect); on a\n3 , Faerie Fire ; on a 4 , Fireball ; on a 5 , Gust of\nWind ; on a 6 , Invisibility (cast on yourself); on a\n7 , Lightning Bolt ; on an 8 , Phantasmal Force ; on\na 9 , Polymorph ; on a 10 , Stinking Cloud .\n51–55 You have the Stunned condition until the end\nof your next turn, believing something awe-\nsome just happened.\n56–60 A harmless swarm of butterflies fills a 10-foot\nCube within 30 feet of yourself. The swarm\ndisperses after 1 minute.\n61–65 You pull a nonmagical object out of the hat.\nRoll 1d4 to determine the object: on a 1 , a vial\nof Acid; on a 2 , a flask of Alchemist’s Fire; on a\n3 , a Crowbar; on a 4 , a lit Torch.\n66–70 You suffer a bout of “magic sickness” and have\nthe Poisoned condition for 1 hour.\n71–75 You have the Petrified condition until the end\nof your next turn.\n76–80 You pull a nonmagical object out of the hat.\nRoll 1d4 to determine the object: on a 1 , a\nDagger; on a 2 , a Rope with a Grappling Hook\ntied to one end; on a 3 , a bag of Caltrops; on a\n4 , a gem worth 50 GP.\n81–85 A creature appears in an unoccupied space\nas close to you as possible. The creature isn’t\nunder your control and acts as it normally\nwould, and it disappears after 1 hour or when\nit drops to 0 Hit Points. Roll 1d4 to deter-\nmine the creature: on a 1 , a Camel ; on a 2 , a\nConstrictor Snake ; on a 3 , an Elephant ;\non a 4 , a Mule .\n1d100 Effect\n86–90 A Hostile Swarm of Bats flies out of the\nhat, occupies your space, and attacks you.\n91–95 A vertical, 10-foot-diameter, two-way portal\nto another plane of existence opens in an\nunoccupied space within 30 feet of you and\nremains open until the end of your next turn.\nThe GM determines where it leads.\n96–00 You pull a magic item out of the hat. Roll\n1d6 to determine the item’s rarity: on a 1–3 ,\nCommon; on a 4–5 , Uncommon; on a 6 ,\nRare. The GM chooses the item, which dis-\nappears after 1 hour if it’s not consumed or\ndestroyed before then."},{"id":"headband-of-intellect","name":"Headband of Intellect","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"Your Intelligence is 19 while you wear this headband.","text":"Your Intelligence is 19 while you wear this headband. It has no effect on you if your Intelligence is 19 or higher without it."},{"id":"helm-of-brilliance","name":"Helm of Brilliance","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"This helm is set with 1d10 diamonds, 2d10 rubies, 3d10 fire opals, and 4d10 opals.","text":"This helm is set with 1d10 diamonds, 2d10 rubies, 3d10 fire opals, and 4d10 opals. Any gem pried from the helm crumbles to dust. When all the gems are removed or destroyed, the helm loses its magic. You gain the following benefits while wearing the helm. Diamond Light. As long as it has at least one diamond, the helm emits a 30-foot Emanation. When at least one Undead is within that area, the Emanation is filled with Dim Light. Any Undead that starts its turn in that area takes 1d6 Radiant damage. Fire Opal Flames. As long as the helm has at least one fire opal, you can take a Magic action to cause one weapon you are holding to burst into flames. The flames emit Bright Light in a 10-foot radius and Dim Light for an additional 10 feet. The flames are harmless to you and the weapon. When you hit with an attack using the blazing weapon, the target takes an extra 1d6 Fire damage. The flames last until you take a Bonus Action to extinguish them or until you drop or stow the weapon. Ruby Resistance. As long as the helm has at least one ruby, you have Resistance to Fire damage. Spells. You can cast one of the following spells (save DC 18), using one of the helm’s gems of the specified type as a component: Daylight (opal), Fireball (fire opal), Prismatic Spray (diamond), or Wall of Fire (ruby). The gem is destroyed when the spell is cast and disappears from the helm. Taking Fire Damage. Roll 1d20 if you are wearing the helm and take Fire damage as a result of failing a saving throw against a spell. On a roll of 1, the helm emits beams of light from its remaining gems and is then destroyed. Each creature within a 60- foot Emanation originating from you must succeed on a DC 17 Dexterity saving throw or be struck by a beam, taking Radiant damage equal to the number of gems in the helm."},{"id":"helm-of-comprehending-languages","name":"Helm of Comprehending Languages","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"While wearing this helm, you can cast Comprehend Languages from it.","text":"While wearing this helm, you can cast Comprehend Languages from it."},{"id":"helm-of-telepathy","name":"Helm of Telepathy","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While wearing this helm, you have telepathy with a range of 30 feet, and you can cast Detect Thoughts or Suggestion (save DC 13) from the helm.","text":"While wearing this helm, you have telepathy with a range of 30 feet, and you can cast Detect Thoughts or Suggestion (save DC 13) from the helm. Once either spell is cast from the helm, that spell can’t be cast from it again until the next dawn."},{"id":"helm-of-teleportation","name":"Helm of Teleportation","kind":"gear","sub":"Magic item · Wondrous Item, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This helm has 3 charges.","text":"This helm has 3 charges. While wearing it, you can expend 1 charge to cast Teleport from it. The helm regains 1d3 expended charges daily at dawn."},{"id":"holy-avenger","name":"Holy Avenger","kind":"gear","sub":"Magic item · Weapon (Any Simple or Martial), Legendary (Requires Attunement by a Paladin)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon.","text":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. When you hit a Fiend or an Undead with it, that creature takes an extra 2d10 Radiant damage. While you hold the drawn weapon, it creates a 10-foot Emanation originating from you. You and all creatures Friendly to you in the Emanation have Advantage on saving throws against spells and other magical effects. If you have 17 or more levels in the Paladin class, the size of the Emanation increases to 30 feet."},{"id":"horn-of-blasting","name":"Horn of Blasting","kind":"gear","sub":"Magic item · Wondrous Item, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"You can take a Magic action to blow the horn, which emits a thunderous blast in a 30-foot Cone that is audible out to 600 feet.","text":"You can take a Magic action to blow the horn, which emits a thunderous blast in a 30-foot Cone that is audible out to 600 feet. Each creature in the Cone makes a DC 15 Constitution saving throw. On a failed save, a creature takes 5d8 Thunder damage and has the Deafened condition for 1 minute. On a successful save, a creature takes half as much damage only. Glass or crystal objects in the Cone that aren’t being worn or carried take 10d8 Thunder damage. Each use of the horn’s magic has a 20 percent chance of causing the horn to explode. The explosion deals 10d6 Force damage to the user and destroys the horn."},{"id":"horn-of-valhalla","name":"Horn of Valhalla","kind":"gear","sub":"Magic item · Wondrous Item, Rare (Silver or Brass), Very Rare (Bronze), or Legendary (Iron)","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"You can take a Magic action to blow this horn.","text":"You can take a Magic action to blow this horn. In response, warrior spirits from the plane of Ysgard appear in unoccupied spaces within 60 feet of you. Each spirit uses the Berserker stat block and returns to Ysgard after 1 hour or when it drops to 0 Hit Points. The spirits look like living, breathing warriors, and they have Immunity to the Charmed and Frightened conditions. Once you use the horn, it can’t be used again until 7 days have passed. Four types of Horn of Valhalla are known to exist, each made of a different metal. The horn’s type determines how many spirits it summons, as well as the requirement for its use. The GM chooses the horn’s type or determines it randomly by rolling on the following table. If you blow the horn without meeting its requirement, the summoned spirits attack you. If you meet the requirement, they are Friendly to you and your allies and follow your commands.\n1d100 Horn Type Spirits Requirement\n01–40 Silver 2 None\n41–75 Brass 3 Proficiency with all\nSimple weapons\n76–90 Bronze 4 Training with all\nMedium armor\n91–00 Iron 5 Proficiency with all\nMartial weapons"},{"id":"horseshoes-of-a-zephyr","name":"Horseshoes of a Zephyr","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0,"c":40000,"notes":"These horseshoes come in a set of four.","text":"These horseshoes come in a set of four. As a Magic action, you can touch one of the horseshoes to the hoof of a horse or similar creature, whereupon the horseshoe affixes itself to the hoof. Removing a horseshoe also takes a Magic action. While all four shoes are affixed to the hooves of a horse or similar creature, they allow the creature to move normally while floating 4 inches above a surface. This effect means the creature can cross or stand above nonsolid or unstable surfaces, such as water or lava. The creature leaves no tracks and ignores Difficult Terrain. In addition, the creature can travel for up to 12 hours a day without gaining Exhaustion levels from extended travel."},{"id":"horseshoes-of-speed","name":"Horseshoes of Speed","kind":"gear","sub":"Magic item · Wondrous Item, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"These horseshoes come in a set of four.","text":"These horseshoes come in a set of four. As a Magic action, you can touch one of the horseshoes to the hoof of a horse or similar creature, whereupon the horseshoe affixes itself to the hoof. Removing a horseshoe also takes a Magic action. While all four horseshoes are attached to the same creature, its Speed is increased by 30 feet."},{"id":"immovable-rod","name":"Immovable Rod","kind":"gear","sub":"Magic item · Rod, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"This iron rod has a button on one end.","text":"This iron rod has a button on one end. You can take a Utilize action to press the button, which causes the rod to become magically fixed in place. Until you or another creature takes a Utilize action to push the button again, the rod doesn’t move, even if it defies gravity. The rod can hold up to 8,000 pounds of weight. More weight causes the rod to deactivate and fall. A creature can take a Utilize action to make a DC 30 Strength (Athletics) check, moving the fixed rod up to 10 feet on a successful check."},{"id":"instant-fortress","name":"Instant Fortress","kind":"gear","sub":"Magic item · Wondrous Item, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"As a Magic action, you can place this 1-inch adamantine statuette on the ground and, using a command word, cause it to grow rapidly into a square adamantine tower.","text":"As a Magic action, you can place this 1-inch adamantine statuette on the ground and, using a command word, cause it to grow rapidly into a square adamantine tower. Repeating the command word causes the tower to revert to statuette form, which works only if the tower is empty. Each creature in the area where the tower appears is pushed to an unoccupied space outside but next to the tower. Objects in the area that aren’t being worn or carried are also pushed clear of the tower. The tower is 20 feet on a side and 30 feet high, with arrow slits on all sides and a battlement atop it. Its interior is divided into two floors, with a ladder, staircase, or ramp (your choice) connecting them. This ladder, staircase, or ramp ends at a trapdoor leading to the roof. When created, the tower has a single door at ground level on the side facing you. The door opens only at your command, which you can issue as a Bonus Action. It is immune to the Knock spell and similar magic. Magic prevents the tower from being tipped over. The roof, the door, and the walls each have AC 20; HP 100; Immunity to Bludgeoning, Piercing, and Slashing damage except that which is dealt by siege equipment; and Resistance to all other damage. Shrinking the tower back down to statuette form doesn’t repair damage to the tower. Only a Wish spell can repair the tower (this use of the spell counts as replicating a spell of level 8 or lower). Each casting of Wish causes the tower to regain all its Hit Points."},{"id":"ioun-stone","name":"Ioun Stone","kind":"gear","sub":"Magic item · Wondrous Item, Rarity Varies (Requires Attunement)","magic":true,"rarity":"Varies","attunement":true,"w":0,"c":0,"notes":"Roughly marble sized, Ioun Stones are named after Ioun, a god of knowledge and prophecy revered on some worlds.","text":"Roughly marble sized, Ioun Stones are named after Ioun, a god of knowledge and prophecy revered on some worlds. Many types of Ioun Stones exist, each type a distinct combination of shape and color. When you take a Magic action to toss an Ioun Stone into the air, the stone orbits your head at a distance of 1d3 feet, conferring its benefit to you while doing so. You can have up to three Ioun Stones orbiting your head at the same time. Each Ioun Stone orbiting your head is considered to be an object you are wearing. The orbiting stone avoids contact with other creatures and objects, adjusting its orbit to avoid collisions and thwarting all attempts by other creatures to attack or snatch it. As a Utilize action, you can seize and stow any number of Ioun Stones orbiting your head. If your Attunement to an Ioun Stone ends while it’s orbiting your head, the stone falls as though you had dropped it. The type of stone determines its rarity and effects. Absorption (Very Rare). While this pale lavender ellipsoid orbits your head, you can take a Reaction to cancel a spell of level 4 or lower cast by a creature you can see. A canceled spell has no effect, and any resources used to cast it are wasted. Once the stone has canceled 20 levels of spells, it burns out, turns dull gray, and loses its magic. Agility (Very Rare). Your Dexterity increases by 2, to a maximum of 20, while this deep-red sphere orbits your head. Awareness (Rare). While this dark-blue rhomboid orbits your head, you have Advantage on Initiative rolls and Wisdom (Perception) checks. Fortitude (Very Rare). Your Constitution increases by 2, to a maximum of 20, while this pink rhomboid orbits your head. Greater Absorption (Legendary). While this marbled lavender and green ellipsoid orbits your head, you can take a Reaction to cancel a spell of level 8 or lower cast by a creature you can see. A canceled spell has no effect, and any resources used to cast it are wasted. Once the stone has canceled 20 levels of spells, it burns out, turns dull gray, and loses its magic. Insight (Very Rare). Your Wisdom increases by 2, to a maximum of 20, while this incandescent blue sphere orbits your head. Intellect (Very Rare). Your Intelligence increases by 2, to a maximum of 20, while this marbled scarlet and blue sphere orbits your head. Leadership (Very Rare). Your Charisma increases by 2, to a maximum of 20, while this marbled pink and green sphere orbits your head. Mastery (Legendary). Your Proficiency Bonus increases by 1 while this pale green prism orbits your head. Protection (Rare). You gain a +1 bonus to Armor Class while this dusty-rose prism orbits your head. Regeneration (Legendary). You regain 15 Hit Points at the end of each hour this pearly white spindle orbits your head if you have at least 1 Hit Point. Reserve (Rare). This vibrant purple prism stores spells cast into it, holding them until you use them. The stone can store up to 4 levels of spells at a time. When found, it contains 1d4 levels of stored spells chosen by the GM. Any creature can cast a spell of level 1 through 4 into the stone by touching it as the spell is cast. The spell has no effect, other than to be stored in the stone. If the stone can’t hold the spell, the spell is expended without effect. The level of the slot used to cast the spell determines how much space it uses. While this stone orbits your head, you can cast any spell stored in it. The spell uses the slot level, spell save DC, spell attack bonus, and spellcasting ability of the original caster but is otherwise treated as if you cast the spell. The spell cast from the stone is no longer stored in it, freeing up space. Strength (Very Rare). Your Strength increases by 2, to a maximum of 20, while this pale blue rhomboid orbits your head. Sustenance (Rare). You don’t need to eat or drink while this clear spindle orbits your head."},{"id":"iron-bands","name":"Iron Bands","kind":"gear","sub":"Magic item · Wondrous Item, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"This rusty iron sphere measures 3 inches in diameter and weighs 1 pound.","text":"This rusty iron sphere measures 3 inches in diameter and weighs 1 pound. You can take a Magic action to throw the sphere at a Huge or smaller creature you can see within 60 feet of yourself. As the sphere moves through the air, it opens into a tangle of metal bands. Make a ranged attack roll with an attack bonus equal to your Dexterity modifier plus your Proficiency Bonus. On a hit, the target has the Restrained condition until you take a Bonus Action to issue a command that releases it. Doing so or missing with the attack causes the bands to contract and become a sphere once more. A creature that can touch the bands, including the one Restrained, can take an action to make a DC 20 Strength (Athletics) check to break the iron bands. On a successful check, the item is destroyed, and the Restrained creature is freed. On a failed check, any further attempts made by that creature automatically fail until 24 hours have elapsed. Once the bands are used, they can’t be used again until the next dawn."},{"id":"iron-flask","name":"Iron Flask","kind":"gear","sub":"Magic item · Wondrous Item, Legendary","magic":true,"rarity":"Legendary","attunement":false,"w":0,"c":200000,"notes":"While holding this brass-stoppered iron flask, you can take a Magic action to target a creature that you can see within 60 feet of yourself.","text":"While holding this brass-stoppered iron flask, you can take a Magic action to target a creature that you can see within 60 feet of yourself. If the flask is empty and the target is native to a plane of existence other than the one you’re on, the target must succeed on a DC 17 Wisdom saving throw or be trapped in the flask. If the target has been trapped by the flask before, it has Advantage on the save. Once trapped, a creature remains in the flask until released. The flask can hold only one creature at a time. A creature trapped in the flask doesn’t age and doesn’t need to breathe, eat, or drink. You can take a Magic action to remove the flask’s stopper and release the creature in the flask. The creature then obeys your commands for 1 hour, understanding those commands even if it doesn’t know the language in which the commands are given. If you issue no commands or give the creature a command that is likely to result in its death or imprisonment, it defends itself but otherwise takes no actions. At the end of the duration, the creature acts in accordance with its normal disposition and alignment. An Identify spell reveals if the flask contains a creature, but the only way to determine the type of creature is to open the flask. A newly discovered Iron Flask might already contain a creature chosen by the GM."},{"id":"javelin-of-lightning","name":"Javelin of Lightning","kind":"gear","sub":"Magic item · Weapon (Javelin), Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"Each time you make an attack roll with this magic weapon and hit, you can have it deal Lightning damage instead of Piercing damage.","text":"Each time you make an attack roll with this magic weapon and hit, you can have it deal Lightning damage instead of Piercing damage. Lightning Bolt. When you throw this weapon at a target no farther than 120 feet from you, you can forgo making a ranged attack roll and instead turn the weapon into a bolt of lightning. This bolt forms a 5-foot-wide Line between you and the target. The target and each other creature in the Line (excluding you) makes a DC 13 Dexterity saving throw, taking 4d6 Lightning damage on a failed save or half as much damage on a successful one. Immediately after dealing this damage, the weapon reappears in your hand. This property can’t be used again until the next dawn."},{"id":"lantern-of-revealing","name":"Lantern of Revealing","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"While lit, this hooded lantern burns for 6 hours on 1 pint of oil, shedding Bright Light in a 30-foot radius and Dim Light for an additional 30 feet.","text":"While lit, this hooded lantern burns for 6 hours on 1 pint of oil, shedding Bright Light in a 30-foot radius and Dim Light for an additional 30 feet. Invisible creatures and objects are visible as long as they are in the lantern’s Bright Light. You can take a Utilize action to lower the hood, reducing the lantern’s light to Dim Light in a 5-foot radius."},{"id":"luck-blade","name":"Luck Blade","kind":"gear","sub":"Magic item · Weapon (Glaive, Greatsword, Longsword, Rapier, Scimitar, Sickle, or Shortsword), Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon.","text":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. While the weapon is on your person, you also gain a +1 bonus to saving throws. Luck. If the weapon is on your person, you can call on its luck (no action required) to reroll one failed D20 Test if you don’t have the Incapacitated condition. You must use the second roll. Once used, this property can’t be used again until the next dawn. Wish. The weapon has 1d3 charges. While holding it, you can expend 1 charge and cast Wish from it. Once used, this property can’t be used again until the next dawn. The weapon loses this property if it has no charges."},{"id":"mace-of-disruption","name":"Mace of Disruption","kind":"gear","sub":"Magic item · Weapon (Mace), Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"When you hit a Fiend or an Undead with this magic weapon, that creature takes an extra 2d6 Radiant damage.","text":"When you hit a Fiend or an Undead with this magic weapon, that creature takes an extra 2d6 Radiant damage. If the target has 25 Hit Points or fewer after taking this damage, it must succeed on a DC 15 Wisdom saving throw or be destroyed. On a successful save, the creature has the Frightened condition until the end of your next turn. Light. While you hold this weapon, it sheds Bright Light in a 20-foot radius and Dim Light for an additional 20 feet."},{"id":"mace-of-smiting","name":"Mace of Smiting","kind":"gear","sub":"Magic item · Weapon (Mace), Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon.","text":"You gain a +1 bonus to attack rolls and damage rolls made with this magic weapon. The bonus increases to +3 when you use the weapon to attack a Construct. When you roll a 20 on an attack roll made with this weapon, the target takes an extra 7 Bludgeoning damage, or 14 Bludgeoning damage if it’s a Construct. If a Construct has 25 Hit Points or fewer after taking this damage, it is destroyed."},{"id":"mace-of-terror","name":"Mace of Terror","kind":"gear","sub":"Magic item · Weapon (Mace), Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This magic weapon has 3 charges and regains 1d3 expended charges daily at dawn.","text":"This magic weapon has 3 charges and regains 1d3 expended charges daily at dawn. While holding the weapon, you can take a Magic action and expend 1 charge to release a wave of terror from it. Each creature of your choice within 30 feet of you must succeed on a DC 15 Wisdom saving throw or have the Frightened condition for 1 minute. While Frightened in this way, a creature must spend its turns trying to move as far away from you as it can, and it can’t make Opportunity Attacks. For its action, it can use only the Dash action or try to escape from an effect that prevents it from moving. If it has nowhere it can move, the creature can take the Dodge action. At the end of each of its turns, a creature repeats the save, ending the effect on itself on a success."},{"id":"mantle-of-spell-resistance","name":"Mantle of Spell Resistance","kind":"gear","sub":"Magic item · Wondrous Item, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"You have Advantage on saving throws against spells while you wear this cloak.","text":"You have Advantage on saving throws against spells while you wear this cloak."},{"id":"manual-of-bodily-health","name":"Manual of Bodily Health","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0,"c":40000,"notes":"This book contains health and nutrition tips, and its words are charged with magic.","text":"This book contains health and nutrition tips, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book’s contents and practicing its guidelines, your Constitution increases by 2, to a maximum of 30. The manual then loses its magic but regains it in a century."},{"id":"manual-of-gainful-exercise","name":"Manual of Gainful Exercise","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0,"c":40000,"notes":"This book describes fitness exercises, and its words are charged with magic.","text":"This book describes fitness exercises, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book’s contents and practicing its guidelines, your Strength increases by 2, to a maximum of 30. The manual then loses its magic but regains it in a century."},{"id":"manual-of-golems","name":"Manual of Golems","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0,"c":40000,"notes":"This tome contains information and incantations necessary to make a particular type of golem.","text":"This tome contains information and incantations necessary to make a particular type of golem. The GM chooses the type or determines it randomly by rolling on the accompanying table. To decipher and use the manual, you must be a spellcaster with at least two level 5 spell slots. A creature that can’t use a Manual of Golems and attempts to read it takes 6d6 Psychic damage. To create a golem, you must spend the time shown on the table, working without interruption with the manual at hand and resting no more than 8 hours per day. You must also pay the specified cost to purchase supplies. Once you finish creating the golem, the book is consumed in eldritch flames. The golem becomes animate when the ashes of the manual are sprinkled on it. See “Monsters” for the golem’s stat block. The golem is under your control, and it understands and obeys your commands.\n1d20 Golem Time Cost\n1–5 Clay Golem 30 days 65,000 GP\n6–17 Flesh Golem 60 days 50,000 GP\n18 Iron Golem 120 days 100,000 GP\n19–20 Stone Golem 90 days 80,000 GP"},{"id":"manual-of-quickness-of-action","name":"Manual of Quickness of Action","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0,"c":40000,"notes":"This book contains coordination and balance exercises, and its words are charged with magic.","text":"This book contains coordination and balance exercises, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book’s contents and practicing its guidelines, your Dexterity increases by 2, to a maximum of 30. The manual then loses its magic but regains it in a century."},{"id":"marvelous-pigments","name":"Marvelous Pigments","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0,"c":40000,"notes":"This fine wooden box contains 1d4 pots of pigment and a brush (weighing 1 pound in total).","text":"This fine wooden box contains 1d4 pots of pigment and a brush (weighing 1 pound in total). Using the brush and expending 1 pot of pigment, you can paint any number of three-dimensional objects and terrain features (such as walls, doors, trees, flowers, weapons, webs, and pits), provided these elements are all confined to a 20-foot Cube. The effort takes 10 minutes (regardless of the number of elements you create), during which time you must remain in the Cube, and requires Concentration. If your Concentration is broken or you leave the Cube before the work is done, all the painted elements vanish, and the pot of pigment is wasted. When the work is done, all the painted objects and terrain features become real. Thus, painting a door on a wall creates an actual door, which can be opened to whatever is beyond. Painting a pit creates a real pit, the entire depth of which must lie within the 20-foot Cube. No object created by a pot of pigment can have a value greater than 25 GP, and the total value of all objects created by a pot of pigment can’t exceed 500 GP. If you paint objects of greater value (such as a large pile of gold), they look authentic, but close inspection reveals they’re made from paste, cookies, or some other worthless material. If you paint a form of energy such as fire or lightning, the energy dissipates as soon as you complete the painting, doing no harm."},{"id":"medallion-of-thoughts","name":"Medallion of Thoughts","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"The medallion has 5 charges.","text":"The medallion has 5 charges. While wearing it, you can expend 1 charge to cast Detect Thoughts (save DC 13) from it. The medallion regains 1d4 expended charges daily at dawn."},{"id":"mirror-of-life-trapping","name":"Mirror of Life Trapping","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0,"c":40000,"notes":"When this 4-foot-tall, 2-foot-wide mirror is viewed indirectly, its surface shows faint images of creatures.","text":"When this 4-foot-tall, 2-foot-wide mirror is viewed indirectly, its surface shows faint images of creatures. The mirror weighs 50 pounds, and it has AC 11, HP 10, Immunity to Poison and Psychic damage, and Vulnerability to Bludgeoning damage. It shatters and is destroyed when reduced to 0 Hit Points. If the mirror is hanging on a vertical surface and you are within 5 feet of it, you can take a Magic action and use a command word to activate it. It remains activated until you take a Magic action and repeat the command word to deactivate it. Any creature other than you that sees its reflection in the activated mirror while within 30 feet of the mirror must succeed on a DC 15 Charisma saving throw or be trapped, along with anything it is wearing or carrying, in one of the mirror’s twelve extradimensional cells. A creature that knows the mirror’s nature makes the save with Advantage, and Constructs succeed on the save automatically. An extradimensional cell is an infinite expanse filled with thick fog that reduces visibility to 10 feet. Creatures trapped in the mirror’s cells don’t age, and they don’t need to eat, drink, or sleep. A creature trapped within a cell can escape using magic that permits planar travel. Otherwise, the creature is confined to the cell until freed. If the mirror traps a creature but its twelve extradimensional cells are already occupied, the mirror frees one trapped creature at random to accommodate the new prisoner. A freed creature appears in an unoccupied space within sight of the mirror but facing away from it. If the mirror is shattered, all creatures it contains are freed and appear in unoccupied spaces near it. While within 5 feet of the mirror, you can take a Magic action to name one creature trapped in it or call out a particular cell by number. The creature named or contained in the named cell appears as an image on the mirror’s surface. You and the creature can then communicate. In a similar way, you can take a Magic action and use a second command word to free one creature trapped in the mirror. The freed creature appears, along with its possessions, in the unoccupied space nearest to the mirror and facing away from it. Placing the mirror inside an extradimensional space created by a Bag of Holding , Portable Hole , or similar item instantly destroys both items and opens a gate to the Astral Plane. The gate originates where the one item was placed inside the other. Any creature within 10 feet of the gate and not behind Total Cover is sucked through it to a random location on the Astral Plane. The gate then closes. The gate is one-way only and can’t be reopened."},{"id":"mithral-armor","name":"Mithral Armor","kind":"gear","sub":"Magic item · Armor (Any Medium or Heavy, Except Hide Armor), Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"Mithral is a light, flexible metal.","text":"Mithral is a light, flexible metal. Armor made of this substance can be worn under normal clothes. If the armor normally imposes Disadvantage on Dexterity (Stealth) checks or has a Strength requirement, the mithral version of the armor doesn’t."},{"id":"mysterious-deck","name":"Mysterious Deck","kind":"gear","sub":"Magic item · Wondrous Item, Legendary","magic":true,"rarity":"Legendary","attunement":false,"w":0,"c":200000,"notes":"Usually found in a box or pouch, this deck contains a number of cards made of ivory or vellum.","text":"Usually found in a box or pouch, this deck contains a number of cards made of ivory or vellum. Most (75 percent) of these decks have thirteen cards, but some have twenty-two. Use the appropriate column of the Mysterious Deck table when randomly determining cards drawn from the deck. Before you draw a card, you must declare how many cards you intend to draw and then draw them randomly. Any cards drawn in excess of this number have no effect. Otherwise, as soon as you draw a card from the deck, its magic takes effect. You must draw each card no more than 1 hour after the previous draw. If you fail to draw the chosen number, the remaining number of cards fly from the deck on their own and take effect all at once. Once a card is drawn, it disappears. Unless the card is the Fool or Jester, the card reappears in the deck, making it possible to draw the same card twice. (Once the Fool or Jester has left the deck, re-\nMysterious roll on the table Deck if that card comes up again.)\n1d100\n(13-Card\nDeck)\n1d100\n(22-Card\nDeck)\nCard\n— 01–05 Balance\n— 06–10 Comet\n— 11–14 Donjon\n01–08 15–18 Euryale\n— 19–23 Fates\n09–16 24–27 Flames\n— 28–31 Fool\n— 32–36 Gem\n17–24 37–41 Jester\n25–32 42–46 Key\n33–40 47–51 Knight\n41–48 52–56 Moon\n— 57–60 Puzzle\n49–56 61–64 Rogue\n57–64 65–68 Ruin\n— 69–73 Sage\n1d100\n(13-Card\nDeck)\n1d100\n(22-Card\nDeck)\nCard\n65–72 74–77 Skull\n73–80 78–82 Star\n81–88 83–87 Sun\n— 88–91 Talons\n89–96 92–96 Throne\n97–00 97–00 Void\nEach card’s effect is described below.\nBalance.\nYou can increase one of your ability scores by 2, to a maximum of 22, provided you also decrease another one of your ability scores by 2. You can’t decrease an ability that has a score of 5 or lower. Alternatively, you can choose not to adjust your ability scores, in which case this card has no effect. Comet. The next time you enter combat against one or more Hostile creatures, you can select one of them as your foe when you roll Initiative. If you reduce your foe to 0 Hit Points during that combat, you have Advantage on Death Saving Throws for 1 year. If someone else reduces your chosen foe to 0 Hit Points or you don’t choose a foe, this card has no effect. Donjon. You disappear and become entombed in a state of suspended animation in an extradimensional sphere. Everything you’re wearing and carrying disappears with you except for Artifacts, which stay behind in the space you occupied when you disappeared. You remain imprisoned until you are found and removed from the sphere. You can’t be located by any Divination magic, but a Wish spell can reveal the location of your prison. You draw no more cards. Euryale. The card’s medusa-like visage curses you. You take a −2 penalty to saving throws while cursed in this way. Only a god or the magic of the Fates card can end this curse. Fates. Reality’s fabric unravels and spins anew, allowing you to avoid or erase one event as if it never happened. You can use the card’s magic as soon as you draw the card or at any other time before you die. Flames. A powerful devil becomes your enemy. The devil seeks your ruin and torments you, savoring your suffering before attempting to slay you. This enmity lasts until either you or the devil dies. Fool. You have Disadvantage on D20 Tests for the next 72 hours. Draw another card; this draw doesn’t count as one of your declared draws. Gem. Twenty-five pieces of jewelry worth 2,000 GP each or fifty gems worth 1,000 GP each appear at your feet. Jester. You have Advantage on D20 Tests for the next 72 hours, or you can draw two additional cards beyond your declared draws. Key. A Rare or rarer magic weapon with which you are proficient appears on your person. The GM chooses the weapon. Knight. You gain the service of a Knight , who magically appears in an unoccupied space you choose within 30 feet of yourself. The knight has the same alignment as you and serves you loyally until death, believing the two of you have been drawn together by fate. Work with your GM to create a name and backstory for this NPC. The GM can use a different stat block to represent the knight, as desired. Moon. You gain the ability to cast Wish 1d3 times. Puzzle. Permanently reduce your Intelligence or Wisdom by 1d4 + 1 (to a minimum score of 1). You can draw one additional card beyond your declared draws. Rogue. An NPC of the GM’s choice becomes Hostile toward you. You don’t know the identity of this NPC until they or someone else reveals it. Nothing less than a Wish spell or divine intervention can end the NPC’s hostility toward you. Ruin. All forms of wealth that you carry or own, other than magic items, are lost to you. Portable property vanishes. Businesses, buildings, and land you own are lost in a way that alters reality the least. Any documentation that proves you should own something lost to this card also disappears. Sage. At any time you choose within one year of drawing this card, you can ask a question in meditation and mentally receive a truthful answer to that question. Skull. An Avatar of Death (see the accompanying stat block) appears in an unoccupied space as close to you as possible. The avatar targets only you with its attacks, appearing as a ghostly skeleton clad in a tattered black robe and carrying a spectral scythe. The avatar disappears when it drops to 0 Hit Points or you die. If an ally of yours deals damage to the avatar, that ally summons another Avatar of Death . The new avatar appears in an unoccupied space as close to that ally as possible and targets only that ally with its attacks. You and your allies can each summon only one avatar as a consequence of this draw. A creature slain by an avatar can’t be restored to life. Star. Increase one of your ability scores by 2, to a maximum of 24. Sun. A magic item (chosen by the GM) appears on your person. In addition, you gain 10 Temporary Hit Points daily at dawn until you die. Talons. Every magic item you wear or carry disintegrates. Artifacts in your possession vanish instead. Throne. You gain proficiency and Expertise in your choice of History, Insight, Intimidation, or Persuasion. In addition, you gain rightful ownership of a small keep somewhere in the world. However, the keep is currently home to one or more monsters, which must be cleared out before you can claim the keep as yours. Void. Your soul is drawn from your body and contained in an object in a place of the GM’s choice. One or more powerful beings guard the place. While your soul is trapped in this way, your body is inert, ceases aging, and requires no food, air, or water. A Wish spell can’t return your soul to your body, but the spell reveals the location of the object that holds Avatar your soul. You of draw Death no more cards. Medium Undead, Neutral evil AC 20 Initiative +3 (13) HP Half the HP maximum of its summoner Speed 60 ft., Fly 60 ft. (hover)\nMOD SAVE MOD SAVE MOD SAVE\nS tr 16 +3 +3 D ex 16 +3 +3 C on 16 +3 +3\nI nt 16 +3 +3 W IS 16 +3 +3 C ha 16 +3 +3\nImmunities Necrotic, Poison; Charmed, Exhaustion, Frightened, Paralyzed, Petrified, Poisoned, Unconscious Senses Truesight 60 ft., Passive Perception 13 Languages All languages known to its summoner CR None (XP 0; PB equals its summoner’s) Traits Incorporeal Movement. The avatar can move through other creatures and objects as if they were Difficult Terrain. It takes 5 (1d10) Force damage if it ends its turn inside an object. Actions Multiattack. The avatar makes a number of Reaping Scythe attacks equal to half the summoner’s Proficiency Bonus (rounded up). Reaping Scythe. Melee Attack Roll: Automatic hit, reach 5 ft. Hit: 7 (1d8 + 3) Slashing damage plus 4 (1d8) Necrotic damage."},{"id":"necklace-of-adaptation","name":"Necklace of Adaptation","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While wearing this necklace, you can breathe normally in any environment, and you have Advantage on saving throws made to avoid or end the Poisoned condition.","text":"While wearing this necklace, you can breathe normally in any environment, and you have Advantage on saving throws made to avoid or end the Poisoned condition."},{"id":"necklace-of-fireballs","name":"Necklace of Fireballs","kind":"gear","sub":"Magic item · Wondrous Item, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"This necklace has 1d6 + 3 beads hanging from it.","text":"This necklace has 1d6 + 3 beads hanging from it.\nYou can take a Magic action to detach a bead and throw it up to 60 feet away. When it reaches the end of its trajectory, the bead detonates as a level 3 Fireball (save DC 15). You can hurl multiple beads, or even the whole necklace, at one time. When you do so, increase the damage of the Fireball by 1d6 for each bead after the first (maximum 12d6)."},{"id":"necklace-of-prayer-beads","name":"Necklace of Prayer Beads","kind":"gear","sub":"Magic item · Wondrous Item, Rare (Requires Attunement by a Cleric, Druid, or Paladin)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This necklace has 1d4 + 2 magic beads made from aquamarine, black pearl, or topaz.","text":"This necklace has 1d4 + 2 magic beads made from aquamarine, black pearl, or topaz. It also has many nonmagical beads made from stones such as amber, bloodstone, citrine, coral, jade, pearl, or quartz. If a magic bead is removed from the necklace, that bead loses its magic. Six types of magic beads exist. The GM decides the type of each bead on the necklace or determines it randomly by rolling on the table below. A necklace can have more than one bead of the same type. To use one, you must be wearing the necklace. Each bead contains a spell that you can cast from it as a Bonus Action (using your spell save DC if a save is necessary). Once a magic bead’s spell is cast, that bead can’t be used again until the next dawn.\n1d20 Bead Spell\n1–6 Bead of Blessing Bless\n7–12 Bead of Curing Cure Wounds (level 2\nversion)\n13–16 Bead of Favor Greater Restoration\n17–18 Bead of Smiting Shining Smite\n19 Bead of Summons Guardian of Faith\n20 Bead of Wind\nWalking\nWind Walk"},{"id":"nine-lives-stealer","name":"Nine Lives Stealer","kind":"gear","sub":"Magic item · Weapon (Any Simple or Martial), Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon.","text":"You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon. Life Stealing. The weapon has 1d8 + 1 charges. When you attack a creature that has fewer than 100 Hit Points with this weapon and roll a 20 on the d20 for the attack roll, the creature must succeed on a DC 15 Constitution saving throw or be slain instantly as the sword tears its life force from its body. Constructs and Undead succeed on the save automatically. The weapon loses 1 charge if the creature is slain. When the weapon has no charges remaining, it loses this property."},{"id":"oathbow","name":"Oathbow","kind":"gear","sub":"Magic item · Weapon (Longbow or Shortbow), Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"When you nock an arrow on this bow, it whispers in Elvish, “Swift defeat to my enemies.” When you use this weapon to make a ranged attack, you can utter or sign the following command words: “Swift dea","text":"When you nock an arrow on this bow, it whispers in Elvish, “Swift defeat to my enemies.” When you use this weapon to make a ranged attack, you can utter or sign the following command words: “Swift death to you who have wronged me.” The target of your attack becomes your sworn enemy until it dies or until dawn 7 days later. You can have only one such sworn enemy at a time. When your sworn enemy dies, you can choose a new one after the next dawn. When you make a ranged attack roll with this weapon against your sworn enemy, you have Advantage on the roll. In addition, your target gains no benefit from Half Cover or Three-Quarters Cover, and you suffer no Disadvantage due to long range. If the attack hits, your sworn enemy takes an extra 3d6 Piercing damage. While your sworn enemy lives, you have Disadvantage on attack rolls with all other weapons."},{"id":"oil-of-etherealness","name":"Oil of Etherealness","kind":"gear","sub":"Magic item · Potion, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0.5,"c":2000,"notes":"One vial of this oil can cover one Medium or smaller creature, along with the equipment it’s wearing and carrying (one additional vial is required for each size category above Medium).","text":"One vial of this oil can cover one Medium or smaller creature, along with the equipment it’s wearing and carrying (one additional vial is required for each size category above Medium). Applying the oil takes 10 minutes. The affected creature then gains the effect of the Etherealness spell for 1 hour. Beads of this cloudy, gray oil form on the outside of its container and quickly evaporate.","stack":true},{"id":"oil-of-sharpness","name":"Oil of Sharpness","kind":"gear","sub":"Magic item · Potion, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0.5,"c":20000,"notes":"One vial of this oil can coat one Melee weapon or twenty pieces of ammunition, but only ammunition and Melee weapons that are nonmagical and deal Slashing or Piercing damage are affected.","text":"One vial of this oil can coat one Melee weapon or twenty pieces of ammunition, but only ammunition and Melee weapons that are nonmagical and deal Slashing or Piercing damage are affected. Applying the oil takes 1 minute, after which the oil magically seeps into whatever it coats, turning the coated weapon into a +3 Weapon or the coated ammunition into +3 Ammunition . This clear, gelatinous oil sparkles with tiny, ultrathin silver shards.","stack":true},{"id":"oil-of-slipperiness","name":"Oil of Slipperiness","kind":"gear","sub":"Magic item · Potion, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0.5,"c":200,"notes":"One vial of this oil can cover one Medium or smaller creature, along with the equipment it’s wearing and carrying (one additional vial is required for each size category above Medium).","text":"One vial of this oil can cover one Medium or smaller creature, along with the equipment it’s wearing and carrying (one additional vial is required for each size category above Medium). Applying the oil takes 10 minutes. The affected creature then gains the effect of the Freedom of Movement spell for 8 hours. Alternatively, the oil can be poured on the ground as a Magic action, where it covers a 10-foot square, duplicating the effect of the Grease spell in that area for 8 hours. This sticky, black unguent is thick and heavy, but it flows quickly when poured.","stack":true},{"id":"pearl-of-power","name":"Pearl of Power","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement by a Spellcaster)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While this pearl is on your person, you can take a Magic action to regain one expended spell slot of level 3 or lower.","text":"While this pearl is on your person, you can take a Magic action to regain one expended spell slot of level 3 or lower. Once you use the pearl, it can’t be used again until the next dawn."},{"id":"periapt-of-health","name":"Periapt of Health","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While wearing this pendant, you can take a Magic action to regain 2d4 + 2 Hit Points.","text":"While wearing this pendant, you can take a Magic action to regain 2d4 + 2 Hit Points. Once used, this property can’t be used again until the next dawn. In addition, you have Advantage on saving throws to avoid or end the Poisoned condition while you wear this pendant."},{"id":"periapt-of-proof-against-poison","name":"Periapt of Proof against Poison","kind":"gear","sub":"Magic item · Wondrous Item, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This delicate silver chain has a brilliant-cut black gem pendant.","text":"This delicate silver chain has a brilliant-cut black gem pendant. While you wear it, you have Immunity to the Poisoned condition and Poison damage."},{"id":"periapt-of-wound-closure","name":"Periapt of Wound Closure","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While wearing this pendant, you gain the following benefits.","text":"While wearing this pendant, you gain the following benefits.\nLife Preservation.\nWhenever you make a Death Saving Throw, you can change a roll of 9 or lower to a 10, turning a failed save into a successful one. Natural Healing Boost. Whenever you roll a Hit Point Die to regain Hit Points, double the number of Hit Points it restores."},{"id":"philter-of-love","name":"Philter of Love","kind":"gear","sub":"Magic item · Potion, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0.5,"c":200,"notes":"The next time you see a creature within 10 minutes after drinking this philter, you are charmed by that creature and have the Charmed condition for 1 hour.","text":"The next time you see a creature within 10 minutes after drinking this philter, you are charmed by that creature and have the Charmed condition for 1 hour. This rose-hued, effervescent liquid contains one easy-to-miss bubble shaped like a heart.","stack":true},{"id":"pipes-of-haunting","name":"Pipes of Haunting","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"These pipes have 3 charges and regain 1d3 expended charges daily at dawn.","text":"These pipes have 3 charges and regain 1d3 expended charges daily at dawn. You can take a Magic action to play them and expend 1 charge to create an eerie, spellbinding tune. Each creature of your choice within 30 feet of you must succeed on a DC 15 Wisdom saving throw or have the Frightened condition for 1 minute. A creature that fails the save repeats it at the end of each of its turns, ending the effect on itself on a success. A creature that succeeds on its save is immune to the effect of these pipes for 24 hours."},{"id":"pipes-of-the-sewers","name":"Pipes of the Sewers","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While these pipes are on your person, ordinary rats and giant rats are Indifferent toward you and won’t attack you unless you threaten or harm them.","text":"While these pipes are on your person, ordinary rats and giant rats are Indifferent toward you and won’t attack you unless you threaten or harm them. The pipes have 3 charges and regain 1d3 expended charges daily at dawn. If you play the pipes as a Magic action, you can take a Bonus Action to expend 1 to 3 charges, calling forth one Swarm of Rats with each expended charge if enough rats are within half a mile of you to be called in this fashion (as determined by the GM). If there aren’t enough rats to form a swarm, the charge is wasted. Called swarms move toward the music by the shortest available route but aren’t under your control otherwise. Whenever a Swarm of Rats that isn’t under another creature’s control comes within 30 feet of you while you are playing the pipes, the swarm makes a DC 15 Wisdom saving throw. On a successful save, the swarm behaves as it normally would and can’t be swayed by the pipes’ music for the next 24 hours. On a failed save, the swarm is swayed by the pipes’ music and becomes Friendly to you and your allies for as long as you continue to play the pipes each round as a Magic action. A Friendly swarm obeys your commands. If you issue no commands to a Friendly swarm, it defends itself but otherwise takes no actions. If a Friendly swarm starts its turn more than 30 feet away from you, your control over that swarm ends, and the swarm behaves as it normally would and can’t be swayed by the pipes’ music for the next 24 hours."},{"id":"plate-armor-of-etherealness","name":"Plate Armor of Etherealness","kind":"gear","sub":"Magic item · Armor (Half Plate Armor or Plate Armor), Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"While you’re wearing this armor, you can take a Magic action and use a command word to gain the effect of the Etherealness spell.","text":"While you’re wearing this armor, you can take a Magic action and use a command word to gain the effect of the Etherealness spell. The spell ends immediately if you remove the armor or take a Magic action to repeat the command word. This property of the armor can’t be used again until the next dawn."},{"id":"portable-hole","name":"Portable Hole","kind":"gear","sub":"Magic item · Wondrous Item, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"This fine black cloth, soft as silk, is folded up to the dimensions of a handkerchief.","text":"This fine black cloth, soft as silk, is folded up to the dimensions of a handkerchief. It unfolds into a circular sheet 6 feet in diameter. You can take a Magic action to unfold a Portable Hole and place it on or against a solid surface, whereupon the Portable Hole creates an extradimensional hole 10 feet deep. The cylindrical space within the hole exists on a different plane of existence, so it can’t be used to create open passages. Any creature inside an open Portable Hole can exit the hole by climbing out of it. You can take a Magic action to close a Portable Hole by taking hold of the edges of the cloth and folding it up. Folding the cloth closes the hole, and any creatures or objects within remain in the extradimensional space. No matter what’s in it, the hole weighs next to nothing. If the hole is folded up, a creature within the hole’s extradimensional space can take an action to make a DC 10 Strength (Athletics) check. On a successful check, the creature forces its way out and appears within 5 feet of the Portable Hole . A closed Portable Hole holds enough air for 1 hour of breathing, divided by the number of breathing creatures inside. Placing a Portable Hole inside an extradimensional space created by a Bag of Holding , Handy Haversack , or similar item instantly destroys both items and opens a gate to the Astral Plane. The gate originates where the one item was placed inside the other. Any creature within 10 feet of the gate and not behind Total Cover is sucked through it and deposited in a random location on the Astral Plane. The gate then closes. The gate is one-way only and can’t be reopened."},{"id":"potion-of-animal-friendship","name":"Potion of Animal Friendship","kind":"gear","sub":"Magic item · Potion, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0.5,"c":200,"notes":"When you drink this potion, you can cast the level 3 version of the Animal Friendship spell (save DC 13).","text":"When you drink this potion, you can cast the level 3 version of the Animal Friendship spell (save DC 13). Agitating this potion’s muddy liquid brings little bits into view: a fish scale, a hummingbird feather, a cat claw, or a squirrel hair.","stack":true},{"id":"potion-of-clairvoyance","name":"Potion of Clairvoyance","kind":"gear","sub":"Magic item · Potion, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0.5,"c":2000,"notes":"When you drink this potion, you gain the effect of the Clairvoyance spell (no Concentration required).","text":"When you drink this potion, you gain the effect of the Clairvoyance spell (no Concentration required). An eyeball bobs in this potion’s yellowish liquid but vanishes when the potion is opened.","stack":true},{"id":"potion-of-climbing","name":"Potion of Climbing","kind":"gear","sub":"Magic item · Potion, Common","magic":true,"rarity":"Common","attunement":false,"w":0.5,"c":50,"notes":"When you drink this potion, you gain a Climb Speed equal to your Speed for 1 hour.","text":"When you drink this potion, you gain a Climb Speed equal to your Speed for 1 hour. During this time, you have Advantage on Strength (Athletics) checks to climb. This potion is separated into brown, silver, and gray layers resembling bands of stone. Shaking the bottle fails to mix the colors.","stack":true},{"id":"potion-of-diminution","name":"Potion of Diminution","kind":"gear","sub":"Magic item · Potion, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0.5,"c":2000,"notes":"When you drink this potion, you gain the “reduce” effect of the Enlarge/Reduce spell for 1d4 hours (no Concentration required).","text":"When you drink this potion, you gain the “reduce” effect of the Enlarge/Reduce spell for 1d4 hours (no Concentration required). The red in the potion’s liquid continuously contracts to a tiny bead and then expands to color the clear liquid around it. Shaking the bottle fails to interrupt this process.","stack":true},{"id":"potion-of-flying","name":"Potion of Flying","kind":"gear","sub":"Magic item · Potion, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0.5,"c":20000,"notes":"When you drink this potion, you gain a Fly Speed equal to your Speed for 1 hour and can hover.","text":"When you drink this potion, you gain a Fly Speed equal to your Speed for 1 hour and can hover. If you’re in the air when the potion wears off, you fall unless you have some other means of staying aloft. This potion’s clear liquid floats at the top of its container and has cloudy white impurities drifting in it.","stack":true},{"id":"potion-of-gaseous-form","name":"Potion of Gaseous Form","kind":"gear","sub":"Magic item · Potion, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0.5,"c":2000,"notes":"When you drink this potion, you gain the effect of the Gaseous Form spell for 1 hour (no Concentration required) or until you end the effect as a Bonus Action.","text":"When you drink this potion, you gain the effect of the Gaseous Form spell for 1 hour (no Concentration required) or until you end the effect as a Bonus Action. This potion’s container seems to hold fog that moves and pours like water.","stack":true},{"id":"potion-of-giant-strength","name":"Potion of Giant Strength","kind":"gear","sub":"Magic item · Potion, Rarity Varies","magic":true,"rarity":"Varies","attunement":false,"w":0.5,"c":0,"notes":"When you drink this potion, your Strength score changes for 1 hour.","text":"When you drink this potion, your Strength score changes for 1 hour. The type of giant determines the score (see the table below). The potion has no effect on you if your Strength is equal to or greater than that score. This potion’s transparent liquid has floating in it a sliver of light resembling a giant’s fingernail.\nPotion Str. Rarity\nPotion of Giant Strength (hill) 21 Uncommon\nPotion of Giant Strength (frost or\nstone)\n23 Rare\nPotion of Giant Strength (fire) 25 Rare\nPotion of Giant Strength (cloud) 27 Very Rare\nPotion of Giant Strength (storm) 29 Legendary","stack":true},{"id":"potion-of-growth","name":"Potion of Growth","kind":"gear","sub":"Magic item · Potion, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0.5,"c":200,"notes":"When you drink this potion, you gain the “enlarge” effect of the Enlarge/Reduce spell for 10 minutes (no Concentration required).","text":"When you drink this potion, you gain the “enlarge” effect of the Enlarge/Reduce spell for 10 minutes (no Concentration required). The red in the potion’s liquid continuously expands from a tiny bead to color the clear liquid around it and then contracts. Shaking the bottle fails to interrupt this process.","stack":true},{"name":"Potion of Healing","kind":"gear","sub":"Magic item · Potion, Common","magic":true,"rarity":"Common","attunement":false,"w":0.5,"c":50,"notes":"Drink it (Bonus Action) to regain 2d4 + 2 Hit Points.","text":"As a Bonus Action, you can drink this potion or give it to a creature within 5 feet. The creature regains 2d4 + 2 Hit Points.\nYou regain Hit Points when you drink this potion.\nThe number of Hit Points depends on the potion’s rarity, as shown in the table below. Whatever its potency, the potion’s red liquid glimmers when agitated.\nPotion HP Regained Rarity\nPotion of Healing 2d4 + 2 Common\nPotion of Healing\n(greater)\n4d4 + 4 Uncommon\nPotion of Healing\n(superior)\n8d4 + 8 Rare\nPotion of Healing\n(supreme)\n10d4 + 20 Very Rare","stack":true,"id":"potion-of-healing","heal":"2d4+2"},{"name":"Potion of Healing (Greater)","kind":"gear","sub":"Magic item · Potion, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0.5,"c":200,"notes":"Drink it (Bonus Action) to regain 4d4 + 4 Hit Points.","text":"As a Bonus Action, you can drink this potion or give it to a creature within 5 feet. The creature regains 4d4 + 4 Hit Points.\nYou regain Hit Points when you drink this potion.\nThe number of Hit Points depends on the potion’s rarity, as shown in the table below. Whatever its potency, the potion’s red liquid glimmers when agitated.\nPotion HP Regained Rarity\nPotion of Healing 2d4 + 2 Common\nPotion of Healing\n(greater)\n4d4 + 4 Uncommon\nPotion of Healing\n(superior)\n8d4 + 8 Rare\nPotion of Healing\n(supreme)\n10d4 + 20 Very Rare","stack":true,"id":"potion-of-healing-greater","heal":"4d4+4"},{"name":"Potion of Healing (Superior)","kind":"gear","sub":"Magic item · Potion, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0.5,"c":2000,"notes":"Drink it (Bonus Action) to regain 8d4 + 8 Hit Points.","text":"As a Bonus Action, you can drink this potion or give it to a creature within 5 feet. The creature regains 8d4 + 8 Hit Points.\nYou regain Hit Points when you drink this potion.\nThe number of Hit Points depends on the potion’s rarity, as shown in the table below. Whatever its potency, the potion’s red liquid glimmers when agitated.\nPotion HP Regained Rarity\nPotion of Healing 2d4 + 2 Common\nPotion of Healing\n(greater)\n4d4 + 4 Uncommon\nPotion of Healing\n(superior)\n8d4 + 8 Rare\nPotion of Healing\n(supreme)\n10d4 + 20 Very Rare","stack":true,"id":"potion-of-healing-superior","heal":"8d4+8"},{"name":"Potion of Healing (Supreme)","kind":"gear","sub":"Magic item · Potion, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0.5,"c":20000,"notes":"Drink it (Bonus Action) to regain 10d4 + 20 Hit Points.","text":"As a Bonus Action, you can drink this potion or give it to a creature within 5 feet. The creature regains 10d4 + 20 Hit Points.\nYou regain Hit Points when you drink this potion.\nThe number of Hit Points depends on the potion’s rarity, as shown in the table below. Whatever its potency, the potion’s red liquid glimmers when agitated.\nPotion HP Regained Rarity\nPotion of Healing 2d4 + 2 Common\nPotion of Healing\n(greater)\n4d4 + 4 Uncommon\nPotion of Healing\n(superior)\n8d4 + 8 Rare\nPotion of Healing\n(supreme)\n10d4 + 20 Very Rare","stack":true,"id":"potion-of-healing-supreme","heal":"10d4+20"},{"id":"potion-of-heroism","name":"Potion of Heroism","kind":"gear","sub":"Magic item · Potion, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0.5,"c":2000,"notes":"When you drink this potion, you gain 10 Temporary Hit Points that last for 1 hour.","text":"When you drink this potion, you gain 10 Temporary Hit Points that last for 1 hour. For the same duration, you are under the effect of the Bless spell (no Concentration required). This potion’s blue liquid bubbles and steams as if boiling.","stack":true},{"id":"potion-of-invisibility","name":"Potion of Invisibility","kind":"gear","sub":"Magic item · Potion, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0.5,"c":2000,"notes":"This potion’s container looks empty but feels as though it holds liquid.","text":"This potion’s container looks empty but feels as though it holds liquid. When you drink the potion, you have the Invisible condition for 1 hour. The effect ends early if you make an attack roll, deal damage, or cast a spell.","stack":true},{"id":"potion-of-invulnerability","name":"Potion of Invulnerability","kind":"gear","sub":"Magic item · Potion, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0.5,"c":2000,"notes":"For 1 minute after you drink this potion, you have Resistance to all damage.","text":"For 1 minute after you drink this potion, you have Resistance to all damage. This potion’s syrupy liquid looks like liquefied iron.","stack":true},{"id":"potion-of-longevity","name":"Potion of Longevity","kind":"gear","sub":"Magic item · Potion, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0.5,"c":20000,"notes":"When you drink this potion, your physical age is reduced by 1d6 + 6 years, to a minimum of 13 years.","text":"When you drink this potion, your physical age is reduced by 1d6 + 6 years, to a minimum of 13 years. Each time you subsequently drink a Potion of Longevity , there is 10 percent cumulative chance that you instead age by 1d6 + 6 years. Suspended in this amber liquid is a tiny heart that, against all reason, is still beating. These ingredients vanish when the potion is opened.","stack":true},{"id":"potion-of-mind-reading","name":"Potion of Mind Reading","kind":"gear","sub":"Magic item · Potion, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0.5,"c":2000,"notes":"When you drink this potion, you gain the effect of the Detect Thoughts spell (save DC 13) for 10 minutes (no Concentration required).","text":"When you drink this potion, you gain the effect of the Detect Thoughts spell (save DC 13) for 10 minutes (no Concentration required). This potion’s dense, purple liquid has an ovoid cloud of pink floating in it.","stack":true},{"id":"potion-of-poison","name":"Potion of Poison","kind":"gear","sub":"Magic item · Potion, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0.5,"c":200,"notes":"This concoction looks, smells, and tastes like a Potion of Healing or another beneficial potion.","text":"This concoction looks, smells, and tastes like a Potion of Healing or another beneficial potion. However, it is actually poison masked by illusion magic. Identify reveals its true nature. If you drink this potion, you take 4d6 Poison damage and must succeed on a DC 13 Constitution saving throw or have the Poisoned condition for 1 hour.","stack":true},{"id":"potion-of-resistance","name":"Potion of Resistance","kind":"gear","sub":"Magic item · Potion, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0.5,"c":200,"notes":"When you drink this potion, you have Resistance to one type of damage for 1 hour.","text":"When you drink this potion, you have Resistance to one type of damage for 1 hour. The GM chooses the type or determines it randomly by rolling on the following table.\n1d10 Damage Type 1d10 Damage Type\n1 Acid 6 Necrotic\n2 Cold 7 Poison\n3 Fire 8 Psychic\n4 Force 9 Radiant\n5 Lightning 10 Thunder","stack":true},{"id":"potion-of-speed","name":"Potion of Speed","kind":"gear","sub":"Magic item · Potion, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0.5,"c":20000,"notes":"When you drink this potion, you gain the effect of the Haste spell for 1 minute (no Concentration required) without suffering the wave of lethargy that typically occurs when the effect ends.","text":"When you drink this potion, you gain the effect of the Haste spell for 1 minute (no Concentration required) without suffering the wave of lethargy that typically occurs when the effect ends. This potion’s yellow fluid is streaked with black and swirls on its own.","stack":true},{"id":"potion-of-vitality","name":"Potion of Vitality","kind":"gear","sub":"Magic item · Potion, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0.5,"c":20000,"notes":"When you drink this potion, it removes any Exhaustion levels you have and ends the Poisoned condition on you.","text":"When you drink this potion, it removes any Exhaustion levels you have and ends the Poisoned condition on you. For the next 24 hours, you regain the maximum number of Hit Points for any Hit Point Die you spend. This potion’s crimson liquid regularly pulses with dull light, calling to mind a heartbeat.","stack":true},{"id":"potion-of-water-breathing","name":"Potion of Water Breathing","kind":"gear","sub":"Magic item · Potion, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0.5,"c":200,"notes":"You can breathe underwater for 24 hours after drinking this potion.","text":"You can breathe underwater for 24 hours after drinking this potion.\nThis potion’s cloudy green fluid smells of the sea and has a jellyfish-like bubble floating in it.","stack":true},{"id":"quarterstaff-of-the-acrobat","name":"Quarterstaff of the Acrobat","kind":"gear","sub":"Magic item · Weapon (Quarterstaff), Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"You have a +2 bonus to attack rolls and damage rolls made with this magic weapon.","text":"You have a +2 bonus to attack rolls and damage rolls made with this magic weapon. While holding this weapon, you can cause it to emit green Dim Light out to 10 feet, either as a Bonus Action or after you roll Initiative, or you can extinguish the light as a Bonus Action. While holding this weapon, you can take a Bonus Action to alter its form, turning it into a 6-inch rod (for ease of storage) or a 10-foot pole, or reverting it a Quarterstaff; the weapon will elongate only as far as the surrounding space allows. In certain forms, the weapon has the following additional properties. Acrobatic Assist (Quarterstaff and 10-Foot Pole Forms Only). While holding this weapon, you have Advantage on Dexterity (Acrobatics) checks. Attack Deflection (Quarterstaff Form Only). When you are hit by an attack while holding the weapon, you can take a Reaction to twirl the weapon around you, gaining a +5 bonus to your Armor Class against the triggering attack, potentially causing the attack to miss you. You can’t use this property again until you finish a Short or Long Rest. Ranged Weapon (Quarterstaff Form Only). This weapon has the Thrown property with a normal range of 30 feet and a long range of 120 feet. Immediately after you make a ranged attack with the weapon, it flies back to your hand."},{"id":"ring-of-animal-influence","name":"Ring of Animal Influence","kind":"gear","sub":"Magic item · Ring, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"This ring has 3 charges, and it regains 1d3 expended charges daily at dawn.","text":"This ring has 3 charges, and it regains 1d3 expended charges daily at dawn. While wearing the ring, you can expend 1 charge to cast one of the following spells (save DC 13) from it: • Animal Friendship • Fear (affects Beasts only) • Speak with Animals"},{"id":"ring-of-djinni-summoning","name":"Ring of Djinni Summoning","kind":"gear","sub":"Magic item · Ring, Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"While wearing this ring, you can take a Magic action to summon a particular Djinni from the Elemental Plane of Air.","text":"While wearing this ring, you can take a Magic action to summon a particular Djinni from the Elemental Plane of Air. The djinni appears in an unoccupied space you choose within 120 feet of yourself. It remains as long as you maintain Concentration, to a maximum of 1 hour, or until it drops to 0 Hit Points. While summoned, the djinni is Friendly to you and your allies, and it obeys your commands. If you fail to command it, the djinni defends itself against attackers but takes no other actions. After the djinni departs, it can’t be summoned again for 24 hours, and the ring becomes nonmagical if the djinni dies. Rings of Djinni Summoning are often created by the djinn they summon and given to mortals as gifts of friendship or tokens of esteem."},{"id":"ring-of-elemental-command","name":"Ring of Elemental Command","kind":"gear","sub":"Magic item · Ring, Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"Each Ring of Elemental Command is linked to one of the four Elemental Planes.","text":"Each Ring of Elemental Command is linked to one of the four Elemental Planes. The GM chooses or randomly determines the linked plane. For example, a Ring of Elemental Command (air) is linked to the Elemental Plane of Air. Every Ring of Elemental Command has the following two properties: Elemental Bane. While wearing the ring, you have Advantage on attack rolls against Elementals and they have Disadvantage on attack rolls against you. Elemental Compulsion. While wearing the ring, you can take a Magic action to try to compel an Elemental you see within 60 feet of yourself. The Elemental makes a DC 18 Wisdom saving throw. On a failed save, the Elemental has the Charmed condition until the start your next turn, and you determine what it does with its move and action on its next turn. Elemental Focus. While wearing the ring, you benefit from additional properties corresponding to the ring’s linked Elemental Plane: Air. You know Auran, you have Resistance to Lightning damage, and you have a Fly Speed equal to your Speed and can hover. Earth. You know Terran, and you have Resistance to Acid damage. Terrain composed of rubble, rocks, or dirt isn’t Difficult Terrain for you. In addition, you can move through solid earth or rock as if those areas were Difficult Terrain without disturbing the matter through which you pass. If you end your turn in solid earth or rock, you are shunted out to the nearest unoccupied space you last occupied. Fire. You know Ignan, and you have Immunity to Fire damage. Water. You know Aquan, you gain a Swim Speed of 60 feet, and you can breathe underwater. Spellcasting. The ring has 5 charges and regains 1d4 + 1 expended charges daily at dawn. While wearing the ring, you can cast a spell from it. Choose the spell from the list of available spells based on the Elemental Plane the ring is linked to, as shown in the following table. The table indicates how many charges you must expend to cast the spell, which has a save DC of 18.\nPlane Spells (Charges)\nAir Chain Lightning (3 charges), Feather Fall (0\ncharges), Gust of Wind (2 charges), Wind\nWall (1 charge)\nEarth Earthquake (5 charges), Stone Shape (2\ncharges), Stoneskin (3 charges), Wall of Stone\n(3 charges)\nFire Burning Hands (1 charge), Fireball (2 charges),\nFire Storm (4 charges), Wall of Fire (3 charges)\nWater Create or Destroy Water (1 charge), Ice Storm\n(2 charges), Tsunami (5 charges), Wall of Ice\n(3 charges), Water Walk (2 charges)"},{"id":"ring-of-evasion","name":"Ring of Evasion","kind":"gear","sub":"Magic item · Ring, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This ring has 3 charges, and it regains 1d3 expended charges daily at dawn.","text":"This ring has 3 charges, and it regains 1d3 expended charges daily at dawn. When you fail a Dexterity saving throw while wearing the ring, you can take a Reaction to expend 1 charge to succeed on that save instead."},{"id":"ring-of-feather-falling","name":"Ring of Feather Falling","kind":"gear","sub":"Magic item · Ring, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"When you fall while wearing this ring, you descend 60 feet per round and take no damage from falling.","text":"When you fall while wearing this ring, you descend 60 feet per round and take no damage from falling."},{"id":"ring-of-free-action","name":"Ring of Free Action","kind":"gear","sub":"Magic item · Ring, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"While you wear this ring, Difficult Terrain doesn’t cost you extra movement.","text":"While you wear this ring, Difficult Terrain doesn’t cost you extra movement. In addition, magic can neither reduce any of your Speeds nor cause you to have the Paralyzed or Restrained condition."},{"id":"ring-of-invisibility","name":"Ring of Invisibility","kind":"gear","sub":"Magic item · Ring, Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"While wearing this ring, you can take a Magic action to give yourself the Invisible condition.","text":"While wearing this ring, you can take a Magic action to give yourself the Invisible condition. You remain Invisible until the ring is removed or until you take a Bonus Action to become visible again."},{"id":"ring-of-jumping","name":"Ring of Jumping","kind":"gear","sub":"Magic item · Ring, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While wearing this ring, you can cast Jump from it, but can target only yourself when you do so.","text":"While wearing this ring, you can cast Jump from it, but can target only yourself when you do so."},{"id":"ring-of-mind-shielding","name":"Ring of Mind Shielding","kind":"gear","sub":"Magic item · Ring, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While wearing this ring, you are immune to magic that allows other creatures to read your thoughts, determine whether you are lying, know your alignment, or know your creature type.","text":"While wearing this ring, you are immune to magic that allows other creatures to read your thoughts, determine whether you are lying, know your alignment, or know your creature type. Creatures can telepathically communicate with you only if you allow it. You can take a Magic action to cause the ring to become imperceptible until you take another Magic action to make it perceptible, until you remove the ring, or until you die. If you die while wearing the ring, your soul enters it, unless it already houses a soul. You can remain in the ring or depart for the afterlife. As long as your soul is in the ring, you can telepathically communicate with any creature wearing it. A wearer can’t prevent this telepathic communication."},{"id":"ring-of-protection","name":"Ring of Protection","kind":"gear","sub":"Magic item · Ring, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"You gain a +1 bonus to Armor Class and saving throws while wearing this ring.","text":"You gain a +1 bonus to Armor Class and saving throws while wearing this ring."},{"id":"ring-of-regeneration","name":"Ring of Regeneration","kind":"gear","sub":"Magic item · Ring, Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"While wearing this ring, you regain 1d6 Hit Points every 10 minutes if you have at least 1 Hit Point.","text":"While wearing this ring, you regain 1d6 Hit Points every 10 minutes if you have at least 1 Hit Point. If you lose a body part, the ring causes the missing part to regrow and return to full functionality after 1d6 + 1 days if you have at least 1 Hit Point the whole time."},{"id":"ring-of-resistance","name":"Ring of Resistance","kind":"gear","sub":"Magic item · Ring, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"You have Resistance to one damage type while wearing this ring.","text":"You have Resistance to one damage type while wearing this ring. The gemstone in the ring indicates the type, which the GM chooses or determines randomly by rolling on the following table.\n1d10 Damage Type Gemstone\n1 Acid Pearl\n2 Cold Tourmaline\n3 Fire Garnet\n4 Force Sapphire\n5 Lightning Citrine\n6 Necrotic Jet\n7 Poison Amethyst\n8 Psychic Jade\n9 Radiant Topaz\n10 Thunder Spinel"},{"id":"ring-of-shooting-stars","name":"Ring of Shooting Stars","kind":"gear","sub":"Magic item · Ring, Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"You can cast Dancing Lights or Light from the ring.","text":"You can cast Dancing Lights or Light from the ring.\nThe ring has 6 charges and regains 1d6 expended charges daily at dawn. You can expend its charges to use the properties below. Faerie Fire. You can expend 1 charge to cast Faerie Fire from the ring. Lightning Spheres. You can expend 2 charges as a Magic action to create up to four 3-foot-diameter spheres of lightning. Each sphere appears in an unoccupied space you can see within 120 feet of yourself. The spheres last as long as you maintain Concentration, up to 1 minute. Each sphere sheds Dim Light in a 30-foot radius. As a Bonus Action, you can move each sphere up to 30 feet, but no farther than 120 feet away from yourself. The first time the sphere comes within 5 feet of a creature other than you that isn’t behind Total Cover, the sphere discharges lightning at that creature and disappears. That creature makes a DC 15 Dexterity saving throw. On a failed save, the creature takes Lightning damage based on the number of spheres you created, as shown in the following table. On a successful save, the creature takes half as much damage.\nNumber of\nSpheres\nLightning\nDamage\nNumber of\nSpheres\nLightning\nDamage\n1 4d12 3 2d6\n2 5d4 4 2d4\nShooting Stars.\nYou can expend 1 to 3 charges as a Magic action. For every charge you expend, you launch a glowing mote of light from the ring at a point you can see within 60 feet of yourself. Each creature in a 15-foot Cube originating from that point is showered in sparks and makes a DC 15 Dexterity saving throw, taking 5d4 Radiant damage on a failed save or half as much damage on a successful one."},{"id":"ring-of-spell-storing","name":"Ring of Spell Storing","kind":"gear","sub":"Magic item · Ring, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This ring stores spells cast into it, holding them until the attuned wearer uses them.","text":"This ring stores spells cast into it, holding them until the attuned wearer uses them. The ring can store up to 5 levels worth of spells at a time. When found, it contains 1d6 − 1 levels of stored spells chosen by the GM. Any creature can cast a spell of level 1 through 5 into the ring by touching the ring as the spell is cast. The spell has no effect other than to be stored in the ring. If the ring can’t hold the spell, the spell is expended without effect. The level of the slot used to cast the spell determines how much space it uses. While wearing this ring, you can cast any spell stored in it. The spell uses the slot level, spell save DC, spell attack bonus, and spellcasting ability of the original caster but is otherwise treated as if you cast the spell. The spell cast from the ring is no longer stored in it, freeing up space."},{"id":"ring-of-spell-turning","name":"Ring of Spell Turning","kind":"gear","sub":"Magic item · Ring, Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"While wearing this ring, you have Advantage on saving throws against spells.","text":"While wearing this ring, you have Advantage on saving throws against spells. If you succeed on the save for a spell of level 7 or lower, the spell has no effect on you. If that spell targeted only you and didn’t create an area of effect, you can take a Reaction to deflect the spell back at the spell’s caster; the caster must make a saving throw against the spell using their own spell save DC."},{"id":"ring-of-swimming","name":"Ring of Swimming","kind":"gear","sub":"Magic item · Ring, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"You have a Swim Speed of 40 feet while wearing this ring.","text":"You have a Swim Speed of 40 feet while wearing this ring."},{"id":"ring-of-telekinesis","name":"Ring of Telekinesis","kind":"gear","sub":"Magic item · Ring, Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"While wearing this ring, you can cast Telekinesis from it.","text":"While wearing this ring, you can cast Telekinesis from it."},{"id":"ring-of-the-ram","name":"Ring of the Ram","kind":"gear","sub":"Magic item · Ring, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This ring has 3 charges and regains 1d3 expended charges daily at dawn.","text":"This ring has 3 charges and regains 1d3 expended charges daily at dawn. While wearing the ring, you can take a Magic action to expend 1 to 3 charges to make a ranged spell attack against one creature you can see within 60 feet of yourself. The ring produces a spectral ram’s head and makes its attack roll with a +7 bonus. On a hit, for each charge you spend, the target takes 2d10 Force damage and is pushed 5 feet away from you. Alternatively, you can expend 1 to 3 of the ring’s charges as a Magic action to try to break a nonmagical object you can see within 60 feet of yourself that isn’t being worn or carried. The ring makes a Strength check with a +5 bonus for each charge you spend."},{"id":"ring-of-three-wishes","name":"Ring of Three Wishes","kind":"gear","sub":"Magic item · Ring, Legendary","magic":true,"rarity":"Legendary","attunement":false,"w":0,"c":200000,"notes":"While wearing this ring, you can expend 1 of its 3 charges to cast Wish from it.","text":"While wearing this ring, you can expend 1 of its 3 charges to cast Wish from it. The ring becomes nonmagical when you use the last charge."},{"id":"ring-of-warmth","name":"Ring of Warmth","kind":"gear","sub":"Magic item · Ring, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"If you take Cold damage while wearing this ring, the ring reduces the damage you take by 2d8.","text":"If you take Cold damage while wearing this ring, the ring reduces the damage you take by 2d8. In addition, while wearing this ring, you and everything you wear and carry are unharmed by temperatures of 0 degrees Fahrenheit or lower."},{"id":"ring-of-water-walking","name":"Ring of Water Walking","kind":"gear","sub":"Magic item · Ring, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"While wearing this ring, you cast Water Walk from it, targeting only yourself.","text":"While wearing this ring, you cast Water Walk from it, targeting only yourself."},{"id":"ring-of-x-ray-vision","name":"Ring of X-ray Vision","kind":"gear","sub":"Magic item · Ring, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"While wearing this ring, you can take a Magic action to gain X-ray vision with a range of 30 feet for 1 minute.","text":"While wearing this ring, you can take a Magic action to gain X-ray vision with a range of 30 feet for 1 minute. To you, solid objects within that radius appear transparent and don’t prevent light from passing through them. The vision can penetrate 1 foot of stone, 1 inch of common metal, or up to 3 feet of wood or dirt. Thicker substances or a thin sheet of lead block the vision. Whenever you use the ring again before taking a Long Rest, you must succeed on a DC 15 Constitution saving throw or gain 1 Exhaustion level."},{"id":"robe-of-eyes","name":"Robe of Eyes","kind":"gear","sub":"Magic item · Wondrous Item, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This robe is adorned with eyelike patterns.","text":"This robe is adorned with eyelike patterns. While you wear the robe, you gain the following benefits: All-Around Vision. The robe gives you Advantage on Wisdom (Perception) checks that rely on sight. Special Senses. You have Darkvision and Truesight, both with a range of 120 feet. Drawbacks. A Light spell cast on the robe or a Daylight spell cast within 5 feet of the robe gives you the Blinded condition for 1 minute. At the end of each of your turns, you make a Constitution saving throw (DC 11 for Light or DC 15 for Daylight ), ending the condition on yourself on a success."},{"id":"robe-of-scintillating-colors","name":"Robe of Scintillating Colors","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"This robe has 3 charges, and it regains 1d3 expended charges daily at dawn.","text":"This robe has 3 charges, and it regains 1d3 expended charges daily at dawn. While you wear it, you can take a Magic action and expend 1 charge to cause the garment to display a shifting pattern of dazzling hues until the end of your next turn. During this time, the robe sheds Bright Light in a 30-foot radius and Dim Light for an additional 30 feet, and creatures that can see you have Disadvantage on attack rolls against you. Any creature in the Bright Light that can see you when the robe’s power is activated must succeed on a DC 15 Wisdom saving throw or have the Stunned condition until the effect ends."},{"id":"robe-of-stars","name":"Robe of Stars","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"This black or dark-blue robe is embroidered with small white or silver stars.","text":"This black or dark-blue robe is embroidered with small white or silver stars. You gain a +1 bonus to saving throws while you wear it. Six stars, located on the robe’s upper-front portion, are particularly large. While wearing this robe, you can take a Magic action to remove one of the stars and expend it to cast the level 5 version of Magic Missile . Daily at dusk, 1d6 removed stars reappear on the robe. While you wear the robe, you can take a Magic action to enter the Astral Plane along with everything you are wearing and carrying. You remain there until you take a Magic action to return to the plane you were on. You reappear in the last space you occupied or, if that space is occupied, the nearest unoccupied space."},{"id":"robe-of-the-archmagi","name":"Robe of the Archmagi","kind":"gear","sub":"Magic item · Wondrous Item, Legendary (Requires Attunement by a Sorcerer, Warlock, or Wizard)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"This elegant garment is made from exquisite cloth and adorned with runes.","text":"This elegant garment is made from exquisite cloth and adorned with runes. You gain these benefits while wearing the robe. Armor. If you aren’t wearing armor, your base Armor Class is 15 plus your Dexterity modifier. Magic Resistance. You have Advantage on saving throws against spells and other magical effects. War Mage. Your spell save DC and spell attack bonus each increase by 2."},{"id":"robe-of-useful-items","name":"Robe of Useful Items","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"This robe has cloth patches of various shapes and colors covering it.","text":"This robe has cloth patches of various shapes and colors covering it. While wearing the robe, you can take a Magic action to detach one of the patches, causing it to become the object or creature it represents. Once the last patch is removed, the robe becomes an ordinary garment. The robe has two of each of the following patches: • Bullseye Lantern (filled and lit) • Dagger • Mirror • Pole • Rope (coiled) • Sack In addition, the robe has 4d4 other patches. The GM chooses the patches or determines them randomly by rolling on the following table.\n1d100 Patch\n01–08 Bag of 100 GP\n09–15 Silver coffer (1 foot long, 6 inches wide and\ndeep) worth 500 GP\n16–22 Iron door (up to 10 feet wide and 10 feet high,\nbarred on one side of your choice), which you\ncan place in an opening you can reach; it con-\nforms to fit the opening, attaching and hinging\nitself\n23–30 10 gems worth 100 GP each\n31–44 Wooden ladder (24 feet long)\n45–51 Riding Horse with a Riding Saddle\n52–59 Open pit (a 10-foot Cube), which you can\nplace on the ground within 10 feet of yourself\n60–68 4 Potions of Healing\n69–75 Rowboat (12 feet long)\n76–83 Spell Scroll containing one spell of level 1, 2, or\n3 (your choice)\n1d100 Patch\n84–90 2 Mastiffs\n91–96 Window (2 feet by 4 feet, up to 2 feet deep),\nwhich you can place on a vertical surface you\ncan reach\n97–00 Portable Ram"},{"id":"rod-of-absorption","name":"Rod of Absorption","kind":"gear","sub":"Magic item · Rod, Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"While holding this rod, you can take a Reaction to absorb a spell that is targeting only you and doesn’t create an area of effect.","text":"While holding this rod, you can take a Reaction to absorb a spell that is targeting only you and doesn’t create an area of effect. The absorbed spell’s effect is canceled, and the spell’s energy—not the spell itself—is stored in the rod. The energy has the same level as the spell when it was cast. A canceled spell dissipates with no effect, and any resources used to cast it are wasted. The rod can absorb and store up to 50 levels of energy over the course of its existence. Once the rod absorbs 50 levels of energy, it can’t absorb more. If you are targeted by a spell that the rod can’t store, the rod has no effect on that spell. When you become attuned to the rod, you know how many levels of energy the rod has absorbed over the course of its existence and how many levels of spell energy it currently has stored. If you are a spellcaster holding the rod, you can convert energy stored in it into spell slots to cast spells you have prepared or know. You can create spell slots only of a level equal to or lower than your own spell slots, up to a maximum of level 5. You use the stored levels in place of your slots but otherwise cast the spell as normal. For example, you can use 3 levels stored in the rod as a level 3 spell slot. A newly found rod typically has 1d10 levels of spell energy stored in it. A rod that can no longer absorb spell energy and has no energy remaining becomes nonmagical."},{"id":"rod-of-alertness","name":"Rod of Alertness","kind":"gear","sub":"Magic item · Rod, Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"This rod has the following properties.","text":"This rod has the following properties.\nAlertness.\nWhile holding the rod, you have Advantage on Wisdom (Perception) checks and on Initiative rolls. Spells. While holding the rod, you can cast the following spells from it: • Detect Evil and Good • Detect Magic • Detect Poison and Disease • See Invisibility Protective Aura. As a Magic action, you can plant the haft end of the rod in the ground, whereupon the rod’s head sheds Bright Light in a 60-foot radius and Dim Light for an additional 60 feet. While in that Bright Light, you and your allies gain a +1 bonus to Armor Class and saving throws and can sense the location of any Invisible creature that is also in the Bright Light. The rod’s head stops glowing and the effect ends after 10 minutes or when a creature takes a Magic action to pull the rod from the ground. Once used, this property can’t be used again until the next dawn."},{"id":"rod-of-lordly-might","name":"Rod of Lordly Might","kind":"gear","sub":"Magic item · Rod, Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"This rod has a flanged head, and it functions as a magic Mace that grants a +3 bonus to attack rolls and damage rolls made with it.","text":"This rod has a flanged head, and it functions as a magic Mace that grants a +3 bonus to attack rolls and damage rolls made with it. The rod has properties associated with six different buttons that are set in a row along the haft. It has three other properties as well, detailed below. Buttons. You can press one of the following buttons as a Bonus Action; a button’s effect lasts until you push a different button or until you push the same button again, which causes the rod to revert to its normal form: Button 1. A fiery blade sprouts from the end opposite the rod’s flanged head. The flames shed Bright Light in a 40-foot radius and Dim Light for an additional 40 feet, and the blade functions as a magic Longsword or Shortsword (your choice) that deals an extra 2d6 Fire damage on a hit. Button 2. The rod’s flanged head folds down and two crescent-shaped blades spring out, transforming the rod into a magic Battleaxe that grants a +3 bonus to attack rolls and damage rolls made with it. Button 3. The rod’s flanged head folds down, a spear point springs from the rod’s tip, and the rod’s handle lengthens into a 6-foot haft, transforming the rod into a magic Spear that grants a +3 bonus to attack rolls and damage rolls made with it. Button 4. The rod transforms into a climbing pole up to 50 feet long (you specify the length), though the rod’s buttons remain within your reach. In surfaces as hard as granite, a spike at the bottom and three hooks at the top anchor the pole. Horizontal bars 3 inches long fold out from the sides, 1 foot apart, forming a ladder. The pole can bear up to 4,000 pounds. More weight or lack of solid anchoring causes the rod to revert to its normal form. Button 5. The rod transforms into a handheld battering ram and grants its user a +10 bonus to Strength (Athletics) checks made to break through doors, barricades, and other barriers. Button 6. The rod assumes or remains in its normal form and indicates magnetic north. (Nothing happens if this function of the rod is used in a location that has no magnetic north.) The rod also gives you knowledge of your approximate depth beneath the ground or your height above it. Drain Life. When you hit a creature with a melee attack using the rod, you can force the target to make a DC 17 Constitution saving throw. On a failed save, the target takes an extra 4d6 Necrotic damage, and you regain a number of Hit Points equal to half that Necrotic damage. Once used, this property can’t be used again until the next dawn. Paralyze. When you hit a creature with a melee attack using the rod, you can force the target to make a DC 17 Constitution saving throw. On a failed save, the target has the Paralyzed condition for 1 minute. The target repeats the save at the end of each of its turns, ending the effect on a success. Once used, this property can’t be used again until the next dawn. Terrify. While holding the rod, you can take a Magic action to force each creature you can see within 30 feet of yourself to make a DC 17 Wisdom saving throw. On a failed save, a target has the Frightened condition for 1 minute. A Frightened target repeats the save at the end of each of its turns, ending the effect on itself on a success. Once used, this property can’t be used again until the next dawn."},{"id":"rod-of-resurrection","name":"Rod of Resurrection","kind":"gear","sub":"Magic item · Rod, Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"The rod has 5 charges.","text":"The rod has 5 charges. While you hold it, you can cast one of the following spells from it: Heal (expends 1 charge) or Resurrection (expends 5 charges). The rod regains 1 expended charge daily at dawn. If you expend the last charge, roll 1d20. On a 1, the rod disappears in a harmless burst of radiance."},{"id":"rod-of-rulership","name":"Rod of Rulership","kind":"gear","sub":"Magic item · Rod, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"You can take a Magic action to present the rod and command obedience from each creature of your choice that you can see within 120 feet of yourself.","text":"You can take a Magic action to present the rod and command obedience from each creature of your choice that you can see within 120 feet of yourself. Each target must succeed on a DC 15 Wisdom saving throw or have the Charmed condition for 8 hours. While Charmed in this way, the creature regards you as its trusted leader. If harmed by you or your allies or commanded to do something contrary to its nature, a target ceases to be Charmed in this way. Once used, this property can’t be used again until the next dawn."},{"id":"rod-of-security","name":"Rod of Security","kind":"gear","sub":"Magic item · Rod, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0,"c":40000,"notes":"While holding this rod, you can take a Magic action to activate it.","text":"While holding this rod, you can take a Magic action to activate it. The rod then instantly transports you and up to 199 other willing creatures you can see to a demiplane. You choose the form the demiplane takes. It could be a tranquil garden, a cheery tavern, an immense palace, a tropical island, a fantastic carnival, or whatever else you can imagine. Regardless of its nature, the demiplane contains enough water and food to sustain its visitors, and the demiplane’s environment can’t harm its occupants. Everything else that can be interacted with there can exist only there. For example, a flower picked from a garden there disappears if it is taken outside the demiplane. For each hour spent in the demiplane, a visitor regains Hit Points as if it had spent 1 Hit Point Die. Also, creatures don’t age while there, although time passes normally. Visitors can remain there for up to 200 days divided by the number of creatures present (round down). When the time runs out or you take a Magic action to end the effect, all visitors reappear in the location they occupied when you activated the rod or an unoccupied space nearest that location. Once used, this property can’t be used again until 10 days have passed."},{"id":"rope-of-climbing","name":"Rope of Climbing","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"This 60-foot length of rope can hold up to 3,000 pounds.","text":"This 60-foot length of rope can hold up to 3,000 pounds. While holding one end of the rope, you can take a Magic action to command the other end of the rope to animate and move toward a destination you choose, up to the rope’s length away from you. That end moves 10 feet on your turn when you first command it and 10 feet at the start of each of your subsequent turns until reaching its destination or until you tell it to stop. You can also tell the rope to fasten itself securely to an object or to unfasten itself, to knot or unknot itself, or to coil itself for carrying. If you tell the rope to knot, large knots appear at 1-foot intervals along the rope. While knotted, the rope shortens to a 50-foot length and grants Advantage on ability checks made to climb using the rope. The rope has AC 20, HP 20, and Immunity to Poison and Psychic damage. It regains 1 Hit Point every 5 minutes as long as it has at least 1 Hit Point. If the rope drops to 0 Hit Points, it is destroyed."},{"id":"rope-of-entanglement","name":"Rope of Entanglement","kind":"gear","sub":"Magic item · Wondrous Item, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"This rope is 30 feet long.","text":"This rope is 30 feet long. While holding one end of the rope, you can take a Magic action to command the other end to dart forward and entangle one creature you can see within 20 feet of yourself. The target must succeed on a DC 15 Dexterity saving throw or have the Restrained condition. You can release the target by letting go of your end of the rope (causing the rope to coil up in the target’s space) or by using a Bonus Action to repeat the command (causing the rope to coil up in your hand). A target Restrained by the rope can take an action to make its choice of a DC 15 Strength (Athletics) or Dexterity (Acrobatics) check. On a successful check, the target is no longer Restrained by the rope. If you’re still holding onto the rope when a target escapes from it, you can take a Reaction to command the rope to coil up in your hand; otherwise, the rope coils up in the target’s space. The rope has AC 20, HP 20, and Immunity to Poison and Psychic damage. It regains 1 Hit Point every 5 minutes as long as it has at least 1 Hit Point. If the rope drops to 0 Hit Points, it is destroyed."},{"id":"scarab-of-protection","name":"Scarab of Protection","kind":"gear","sub":"Magic item · Wondrous Item, Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"This beetle-shaped medallion provides three benefits while it is on your person.","text":"This beetle-shaped medallion provides three benefits while it is on your person. Defense. You gain a +1 bonus to Armor Class. Preservation. The scarab has 12 charges. If you fail a saving throw against a Necromancy spell or a harmful effect originating from an Undead, you can take a Reaction to expend 1 charge and turn the failed save into a successful one. The scarab crumbles into powder and is destroyed when its last charge is expended. Spell Resistance. You have Advantage on saving throws against spells."},{"id":"scimitar-of-speed","name":"Scimitar of Speed","kind":"gear","sub":"Magic item · Weapon (Scimitar), Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon.","text":"You gain a +2 bonus to attack rolls and damage rolls made with this magic weapon. In addition, you can make one attack with it as a Bonus Action on each of your turns."},{"id":"sending-stones","name":"Sending Stones","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon Sending Stones","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"come in pairs, with each stone carved to match the other so the pairing is easily recognized.","text":"come in pairs, with each stone carved to match the other so the pairing is easily recognized. While you touch one stone, you can cast Sending from it. The target is the bearer of the other stone. If no creature bears the other stone, you know that fact as soon as you use the stone, and you don’t cast the spell. Once Sending is cast using either stone, the stones can’t be used again until the next dawn. If one of the stones in a pair is destroyed, the other one becomes nonmagical."},{"id":"sentinel-shield","name":"Sentinel Shield","kind":"gear","sub":"Magic item · Armor (Shield), Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"While holding this Shield, you have Advantage on Initiative rolls and Wisdom (Perception) checks.","text":"While holding this Shield, you have Advantage on Initiative rolls and Wisdom (Perception) checks. The Shield is emblazoned with a symbol of an eye."},{"id":"shield-plus1-plus2-or-plus3","name":"Shield, +1, +2, or +3","kind":"gear","sub":"Magic item · Armor (Shield), Uncommon (+1), Rare (+2), or Very Rare (+3)","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"While holding this Shield, you have a bonus to Armor Class determined by the Shield’s rarity, in addition to the Shield’s normal bonus to AC.","text":"While holding this Shield, you have a bonus to Armor Class determined by the Shield’s rarity, in addition to the Shield’s normal bonus to AC."},{"id":"shield-of-missile-attraction","name":"Shield of Missile Attraction","kind":"gear","sub":"Magic item · Armor (Shield), Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"While holding this Shield, you have Resistance to damage from attacks made with Ranged weapons.","text":"While holding this Shield, you have Resistance to damage from attacks made with Ranged weapons. Curse. This Shield is cursed. Attuning to it curses you until you are targeted by a Remove Curse spell or similar magic. Removing the Shield fails to end the curse on you. Whenever an attack with a Ranged weapon targets a creature within 10 feet of you, the curse causes you to become the target instead."},{"id":"shield-of-the-cavalier","name":"Shield of the Cavalier","kind":"gear","sub":"Magic item · Armor (Shield), Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"While holding this Shield, you have a +2 bonus to Armor Class.","text":"While holding this Shield, you have a +2 bonus to Armor Class. This bonus is in addition to the Shield’s normal bonus to AC. The Shield has the following additional properties that you can use while holding it. Forceful Bash . When you take the Attack action, you can make one of the attack rolls using the Shield against a target within 5 feet of yourself. Apply your Proficiency Bonus and Strength modifier to the attack roll. On a hit, the Shield deals Force damage to the target equal to 2d6 + 2 plus your Strength modifier, and if the target is a creature, you can push it up to 10 feet directly away from yourself. If the creature is your size or smaller, you can also knock it down, giving it the Prone condition. Protective Field. As a Reaction, when you or an ally you can see within 5 feet of you is targeted by an attack or makes a saving throw against an area of effect, you can use the Shield to create an immobile 5-foot Emanation originating from you. When the Emanation appears, any creatures or objects not fully contained within it are pushed into the nearest unoccupied spaces outside it. The attack or area of effect that triggered the Reaction has no effect on creatures and objects inside the Emanation, which lasts as long as you maintain Concentration, up to 1 minute. Nothing can pass into or out of the Emanation. A creature or object inside the Emanation can’t be damaged by attacks or effects originating from outside, nor can a creature inside the Emanation damage anything outside it. Once this property is used, it can’t be used again until the next dawn."},{"id":"slippers-of-spider-climbing","name":"Slippers of Spider Climbing","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While you wear these light shoes, you can move up, down, and across vertical surfaces and along ceilings, while leaving your hands free.","text":"While you wear these light shoes, you can move up, down, and across vertical surfaces and along ceilings, while leaving your hands free. You have a Climb Speed equal to your Speed. However, the slippers don’t allow you to move this way on a slippery surface, such as one covered by ice or oil."},{"id":"sovereign-glue","name":"Sovereign Glue","kind":"gear","sub":"Magic item · Wondrous Item, Legendary","magic":true,"rarity":"Legendary","attunement":false,"w":0,"c":200000,"notes":"This viscous, milky-white substance can form a permanent adhesive bond between any two objects.","text":"This viscous, milky-white substance can form a permanent adhesive bond between any two objects. It must be stored in a jar or flask that has been coated inside with Oil of Slipperiness . When found, a container contains 1d6 + 1 ounces. One ounce of the glue can cover a 1-foot square surface. Applying an ounce of Sovereign Glue takes a Utilize action, and the applied glue takes 1 minute to set. Once it has done so, the bond it creates can be broken only by the application of Universal Solvent or Oil of Etherealness , or with a Wish spell."},{"id":"spellguard-shield","name":"Spellguard Shield","kind":"gear","sub":"Magic item · Armor (Shield), Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"While holding this Shield, you have Advantage on saving throws against spells and other magical effects, and spell attack rolls have Disadvantage against you.","text":"While holding this Shield, you have Advantage on saving throws against spells and other magical effects, and spell attack rolls have Disadvantage against you."},{"id":"spell-scroll","name":"Spell Scroll","kind":"gear","sub":"Magic item · Scroll, Rarity Varies","magic":true,"rarity":"Varies","attunement":false,"w":0,"c":0,"notes":"A Spell Scroll bears the words of a single spell, written in a mystical cipher.","text":"A Spell Scroll bears the words of a single spell, written in a mystical cipher. If the spell is on your spell list, you can read the scroll and cast its spell without Material components. Otherwise, the scroll is unintelligible. Casting the spell by reading the scroll requires the spell’s normal casting time. Once the spell is cast, the scroll crumbles to dust. If the casting is interrupted, the scroll isn’t lost. If the spell is on your spell list but of a higher level than you can normally cast, you make an ability check using your spellcasting ability to determine whether you cast the spell. The DC equals 10 plus the spell’s level. On a failed check, the spell disappears from the scroll with no other effect. The level of the spell on the scroll determines the spell’s saving throw DC and attack bonus, as well as the scroll’s rarity, as shown in the following table.\nSpell Level Rarity Save DC Attack Bonus\nCantrip Common 13 +5\n1 Common 13 +5\n2 Uncommon 13 +5\n3 Uncommon 15 +7\nSpell Level Rarity Save DC Attack Bonus\n4 Rare 15 +7\n5 Rare 17 +9\n6 Very Rare 17 +9\n7 Very Rare 18 +10\n8 Very Rare 18 +10\n9 Legendary 19 +11\nCopying a Scroll into a Spellbook.\nA Wizard spell on a Spell Scroll can be copied into a spellbook.\nWhen a spell is copied in this way, the copier must succeed on an Intelligence (Arcana) check with a DC equal to 10 plus the spell’s level. On a successful check, the spell is copied. Whether the check succeeds or fails, the Spell Scroll is destroyed.","stack":true},{"id":"sphere-of-annihilation","name":"Sphere of Annihilation","kind":"gear","sub":"Magic item · Wondrous Item, Legendary","magic":true,"rarity":"Legendary","attunement":false,"w":0,"c":200000,"notes":"This 2-foot-diameter black sphere is a hole in the multiverse, hovering in space and stabilized by a magical field surrounding it.","text":"This 2-foot-diameter black sphere is a hole in the multiverse, hovering in space and stabilized by a magical field surrounding it. The sphere obliterates all matter it passes through and all matter that passes through it. Artifacts are the exception. Unless an Artifact is susceptible to damage from a Sphere of Annihilation , it passes through the sphere unscathed. Anything else that touches the sphere but isn’t wholly engulfed and obliterated by it takes 8d10 Force damage. Controlling the Sphere. A Sphere of Annihilation is stationary until someone takes control of it. If you are within 60 feet of a sphere, you can take a Magic action to make a DC 25 Intelligence (Arcana) check. On a successful check, you control the sphere until the start of your next turn, and if it was under another creature’s control, that creature loses control of the sphere. On a failed check, the sphere moves 10 feet toward you in a straight line. While in control of the sphere, you can take a Bonus Action to cause it to move in one direction of your choice, up to a number of feet equal to 5 times your Intelligence modifier (minimum 5 feet). Any creature whose space the sphere enters must succeed on a DC 19 Dexterity saving throw or be touched by it, taking 8d10 Force damage. A creature reduced to 0 Hit Points by this damage is obliterated, leaving its possessions behind but no other physical remains. Sphere Interactions. If the sphere comes into contact with a planar portal (such as that created by the Gate spell) or an extradimensional space (such as that within a Portable Hole ), the GM determines randomly what happens using the following table.\n1d100 Result\n01–50 The sphere is destroyed.\n51–85 The sphere moves through the portal or into\nthe extradimensional space.\n86–00 A spatial rift sends the sphere and each crea-\nture and object within 180 feet of the sphere\nto a random plane of existence."},{"id":"staff-of-charming","name":"Staff of Charming","kind":"gear","sub":"Magic item · Staff, Rare (Requires Attunement by a Bard, Cleric, Druid, Sorcerer, Warlock, or Wizard)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This staff has 10 charges.","text":"This staff has 10 charges. While holding the staff, you can use any of its properties: Cast Spell. You can expend 1 of the staff’s charges to cast Charm Person , Command , or Comprehend Languages from it using your spell save DC. Reflect Enchantment. If you succeed on a saving throw against an Enchantment spell that targets only you, you can take a Reaction to expend 1 charge from the staff and turn the spell back on its caster as if you had cast the spell. Resist Enchantment. If you fail a saving throw against an Enchantment spell that targets only you, you can turn your failed save into a successful one. You can’t use this property of the staff again until the next dawn. Regaining Charges. The staff regains 1d8 + 2 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff crumbles to dust and is destroyed."},{"id":"staff-of-fire","name":"Staff of Fire","kind":"gear","sub":"Magic item · Staff, Very Rare (Requires Attunement by a Druid, Sorcerer, Warlock, or Wizard)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"You have Resistance to Fire damage while you hold this staff.","text":"You have Resistance to Fire damage while you hold this staff.\nSpells.\nThe staff has 10 charges. While holding the staff, you can cast one of the spells on the following table from it, using your spell save DC. The table indicates how many charges you must expend to cast the spell.\nSpell\nCharge\nCost Spell\nCharge\nCost\nBurning Hands 1 Wall of Fire 4\nFireball 3\nRegaining Charges.\nThe staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff crumbles into cinders and is destroyed."},{"id":"staff-of-frost","name":"Staff of Frost","kind":"gear","sub":"Magic item · Staff, Very Rare (Requires Attunement by a Druid, Sorcerer, Warlock, or Wizard)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"You have Resistance to Cold damage while you hold this staff.","text":"You have Resistance to Cold damage while you hold this staff.\nSpells.\nThe staff has 10 charges. While holding the staff, you can cast one of the spells on the following table from it, using your spell save DC. The table indicates how many charges you must expend to cast the spell.\nSpell\nCharge\nCost Spell\nCharge\nCost\nCone of Cold 5 Ice Storm 4\nFog Cloud 1 Wall of Ice 4\nRegaining Charges.\nThe staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff turns to water and is destroyed."},{"id":"staff-of-healing","name":"Staff of Healing","kind":"gear","sub":"Magic item · Staff, Rare (Requires Attunement by a Bard, Cleric, or Druid)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This staff has 10 charges.","text":"This staff has 10 charges. While holding the staff, you can cast one of the spells on the following table from it, using your spellcasting ability modifier. The table indicates how many charges you must expend to cast the spell.\nSpell Charge Cost\nCure Wounds 1 charge per spell level\n(maximum 4 for a level 4\nspell)\nLesser Restoration 2\nMass Cure Wounds 5\nRegaining Charges.\nThe staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff vanishes in a flash of light, lost forever."},{"id":"staff-of-power","name":"Staff of Power","kind":"gear","sub":"Magic item · Staff, Very Rare (Requires Attunement by a Sorcerer, Warlock, or Wizard)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"This staff has 20 charges and can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it.","text":"This staff has 20 charges and can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it. While holding it, you gain a +2 bonus to Armor Class, saving throws, and spell attack rolls. Spells. While holding the staff, you can cast one of the spells on the following table from it, using your spell save DC. The table indicates how many charges you must expend to cast the spell.\nSpell\nCharge\nCost\nCone of Cold 5\nFireball (level 5 version) 5\nGlobe of Invulnerability 6\nHold Monster 5\nLevitate 2\nLightning Bolt (level 5 version) 5\nMagic Missile 1\nRay of Enfeeblement 1\nWall of Force 5\nRegaining Charges.\nThe staff regains 2d8 + 4 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff retains its +2 bonus to attack rolls and damage rolls but loses all other properties. On a 20, the staff regains 1d8 + 2 charges. Retributive Strike. You can take a Magic action to break the staff over your knee or against a solid surface. The staff is destroyed and releases its magic in an explosion that fills a 30-foot Emanation originating from itself. You have a 50 percent chance to instantly travel to a random plane of existence, avoiding the explosion. If you fail to avoid the effect, you take Force damage equal to 16 times the number of charges in the staff. Each other creature in the area makes a DC 17 Dexterity saving throw. On a failed save, a creature takes Force damage equal to 4 times the number of charges in the staff. On a successful save, a creature takes half as much damage."},{"id":"staff-of-striking","name":"Staff of Striking","kind":"gear","sub":"Magic item · Staff, Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"This staff can be wielded as a magic Quarterstaff that grants a +3 bonus to attack rolls and damage rolls made with it.","text":"This staff can be wielded as a magic Quarterstaff that grants a +3 bonus to attack rolls and damage rolls made with it. The staff has 10 charges. When you hit with a melee attack using it, you can expend up to 3 charges. For each charge you expend, the target takes an extra 1d6 Force damage. Regaining Charges. The staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff becomes a nonmagical Quarterstaff."},{"id":"staff-of-swarming-insects","name":"Staff of Swarming Insects","kind":"gear","sub":"Magic item · Staff, Rare (Requires Attunement by a Bard, Cleric, Druid, Sorcerer, Warlock, or Wizard)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This staff has 10 charges.","text":"This staff has 10 charges.\nInsect Cloud.\nWhile holding the staff, you can take a Magic action and expend 1 charge to cause a swarm of harmless flying insects to fill a 30- foot Emanation originating from you. The insects remain for 10 minutes, making the area Heavily Obscured for creatures other than you. A strong wind (like that created by Gust of Wind ) disperses the swarm and ends the effect. Spells. While holding the staff, you can cast one of the spells on the following table from it, using your spell save DC and spell attack modifier. The table indicates how many charges you must expend to cast the spell.\nSpell Charge\nCost\nGiant Insect 4\nInsect Plague 5\nRegaining Charges.\nThe staff regains 1d6 + 4 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, a swarm of insects consumes and destroys the staff, then disperses."},{"id":"staff-of-the-magi","name":"Staff of the Magi","kind":"gear","sub":"Magic item · Staff, Legendary (Requires Attunement by a Sorcerer, Warlock, or Wizard)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"This staff has 50 charges and can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it.","text":"This staff has 50 charges and can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it. While you hold it, you gain a +2 bonus to spell attack rolls. Spell Absorption. While holding the staff, you have Advantage on saving throws against spells. In addition, you can take a Reaction when another creature casts a spell that targets only you. If you do, the staff absorbs the magic of the spell, canceling its effect and gaining a number of charges equal to the absorbed spell’s level. However, if doing so brings the staff’s total number of charges above 50, the staff explodes as if you activated its Retributive Strike (see below). Spells. While holding the staff, you can cast one of the spells on the following table from it, using your spell save DC. The table indicates how many charges you must expend to cast the spell.\nSpell\nCharge\nCost\nArcane Lock 0\nConjure Elemental 7\nDetect Magic 0\nDispel Magic 3\nEnlarge/Reduce 0\nFireball (level 7 version) 7\nFlaming Sphere 2\nIce Storm 4\nInvisibility 2\nKnock 2\nLight 0\nLightning Bolt (level 7 version) 7\nSpell\nCharge\nCost\nMage Hand 0\nPasswall 5\nPlane Shift 7\nProtection from Evil and Good 0\nTelekinesis 5\nWall of Fire 4\nWeb 2\nRegaining Charges.\nThe staff regains 4d6 + 2 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 20, the staff regains 1d12 + 1 charges. Retributive Strike. You can take a Magic action to break the staff over your knee or against a solid surface. The staff is destroyed and releases its magic in an explosion that fills a 30-foot Emanation originating from itself. You have a 50 percent chance to instantly travel to a random plane of existence, avoiding the explosion. If you fail to avoid the effect, you take Force damage equal to 16 times the number of charges in the staff. Each other creature in the area makes a DC 17 Dexterity saving throw. On a failed save, a creature takes Force damage equal to 6 times the number of charges in the staff. On a successful save, a creature takes half as much damage."},{"id":"staff-of-the-python","name":"Staff of the Python","kind":"gear","sub":"Magic item · Staff, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"As a Magic action, you can throw this staff so that it lands in an unoccupied space within 10 feet of you, causing the staff to become a Giant Constrictor Snake in that space.","text":"As a Magic action, you can throw this staff so that it lands in an unoccupied space within 10 feet of you, causing the staff to become a Giant Constrictor Snake in that space. The snake is under your control and shares your Initiative count, taking its turn immediately after yours. On your turn, you can mentally command the snake (no action required) if it is within 60 feet of you and you don’t have the Incapacitated condition. You decide what action the snake takes and where it moves during its turn, or you can issue it a general command, such as to attack your enemies or guard a location. Absent commands from you, the snake defends itself. As a Bonus Action, you can command the snake to revert to staff form in its current space, and you can’t use the staff’s property again for 1 hour. If the snake is reduced to 0 Hit Points, it dies and reverts to its staff form; the staff then shatters and is destroyed. If the snake reverts to staff form before losing all its Hit Points, it regains all of them."},{"id":"staff-of-the-woodlands","name":"Staff of the Woodlands","kind":"gear","sub":"Magic item · Staff, Rare (Requires Attunement by a Druid)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This staff has 6 charges and can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it.","text":"This staff has 6 charges and can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it. While holding it, you have a +2 bonus to spell attack rolls. Spells. While holding the staff, you can cast one of the spells on the following table from it, using your spell save DC. The table indicates how many charges you must expend to cast the spell.\nSpell Charge\nCost\nAnimal Friendship 1\nAwaken 5\nBarkskin 2\nLocate Animals or Plants 2\nPass without Trace 2\nSpeak with Animals 1\nSpeak with Plants 3\nWall of Thorns 6\nTree Form.\nYou can take a Magic action to plant one end of the staff in earth in an unoccupied space and expend 1 charge to transform the staff into a healthy tree. The tree is 60 feet tall and has a 5-foot-diameter trunk, and its branches at the top spread out in a 20-foot radius. The tree appears ordinary but radiates a faint aura of Transmutation magic that can be discerned with the Detect Magic spell. While touching the tree and using a Magic action, you return the staff to its normal form. Any creature in the tree falls when the tree reverts to a staff. Regaining Charges. The staff regains 1d6 expended charges daily at dawn. If you expend the last charge, roll 1d20. On a 1, the staff loses its properties and becomes a nonmagical Quarterstaff."},{"id":"staff-of-thunder-and-lightning","name":"Staff of Thunder and Lightning","kind":"gear","sub":"Magic item · Staff, Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"This staff can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it.","text":"This staff can be wielded as a magic Quarterstaff that grants a +2 bonus to attack rolls and damage rolls made with it. It also has the following additional properties. Once one of these properties is used, it can’t be used again until the next dawn. Lightning. When you hit with a melee attack using the staff, you can cause the target to take an extra 2d6 Lightning damage (no action required). Thunder. When you hit with a melee attack using the staff, you can cause the staff to emit a crack of thunder audible out to 300 feet (no action required). The target you hit must succeed on a DC 17 Constitution saving throw or have the Stunned condition until the end of your next turn. Thunder and Lightning. Immediately after you hit with a melee attack using the staff, you can take a Bonus Action to use the Lightning and Thunder properties (see above) at the same time. Doing so doesn’t expend the daily use of those properties, only the use of this one. Lightning Strike. You can take a Magic action to cause a bolt of lightning to leap from the staff’s tip in a Line that is 5 feet wide and 120 feet long. Each creature in that Line makes a DC 17 Dexterity saving throw, taking 9d6 Lightning damage on a failed save or half as much damage on a successful one. Thunderclap. You can take a Magic action to cause the staff to produce a thunderclap audible out to 600 feet. Every creature within a 60-foot Emanation originating from you makes a DC 17 Constitution saving throw. On a failed save, a creature takes 2d6 Thunder damage and has the Deafened condition for 1 minute. On a successful save, a creature takes half as much damage only."},{"id":"staff-of-withering","name":"Staff of Withering","kind":"gear","sub":"Magic item · Staff, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This staff has 3 charges and regains 1d3 expended charges daily at dawn.","text":"This staff has 3 charges and regains 1d3 expended charges daily at dawn. The staff can be wielded as a magic Quarterstaff. On a hit, it deals damage as a normal Quarterstaff, and you can expend 1 charge to deal an extra 2d10 Necrotic damage to the target and force it to make a DC 15 Constitution saving throw. On a failed save, the target has Disadvantage for 1 hour on any ability check or saving throw that uses Strength or Constitution."},{"id":"stone-of-controlling-earth-elementals","name":"Stone of Controlling Earth Elementals","kind":"gear","sub":"Magic item · Wondrous Item, Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"While touching this 5-pound stone to the ground, you can take a Magic action to summon an Earth Elemental .","text":"While touching this 5-pound stone to the ground, you can take a Magic action to summon an Earth Elemental . The elemental appears in an unoccupied space you choose within 30 feet of yourself, obeys your commands, and takes its turn immediately after you on your Initiative count. The elemental disappears after 1 hour, when it dies, or when you dismiss it as a Bonus Action. The stone can’t be used this way again until the next dawn."},{"id":"stone-of-good-luck-luckstone","name":"Stone of Good Luck (Luckstone)","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While this polished agate is on your person, you gain a +1 bonus to ability checks and saving throws.","text":"While this polished agate is on your person, you gain a +1 bonus to ability checks and saving throws."},{"id":"sun-blade","name":"Sun Blade","kind":"gear","sub":"Magic item · Weapon (Longsword), Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This item appears to be a sword hilt.","text":"This item appears to be a sword hilt.\nBlade of Radiance.\nWhile grasping the hilt, you can take a Bonus Action to cause a blade of pure radiance to spring into existence or make the blade disappear. While the blade exists, this magic weapon functions as a Longsword with the Finesse property. If you are proficient with Longswords or Shortswords, you are proficient with the Sun Blade . You gain a +2 bonus to attack rolls and damage rolls made with this weapon, which deals Radiant damage instead of Slashing damage. When you hit an Undead with it, that target takes an extra 1d8 Radiant damage. Sunlight. The sword’s luminous blade emits Bright Light in a 15-foot radius and Dim Light for an additional 15 feet. The light is sunlight. While the blade persists, you can take a Magic action to expand or reduce its radius of Bright Light and Dim Light by 5 feet each, to a maximum of 30 feet each or a minimum of 10 feet each."},{"id":"sword-of-life-stealing","name":"Sword of Life Stealing","kind":"gear","sub":"Magic item · Weapon (Glaive, Greatsword, Longsword, Rapier, Scimitar, or Shortsword), Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"When you attack a creature with this magic weapon and roll a 20 on the d20 for the attack roll, that target takes an extra 15 Necrotic damage if it isn’t a Construct or an Undead, and you gain Tempora","text":"When you attack a creature with this magic weapon and roll a 20 on the d20 for the attack roll, that target takes an extra 15 Necrotic damage if it isn’t a Construct or an Undead, and you gain Temporary Hit Points equal to the amount of Necrotic damage taken."},{"id":"sword-of-sharpness","name":"Sword of Sharpness","kind":"gear","sub":"Magic item · Weapon (Glaive, Greatsword, Longsword, or Scimitar), Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"When you attack an object with this magic weapon and hit, maximize your weapon damage dice against the target.","text":"When you attack an object with this magic weapon and hit, maximize your weapon damage dice against the target. When you attack a creature with this weapon and roll a 20 on the d20 for the attack roll, that target takes an extra 14 Slashing damage and gains 1 Exhaustion level."},{"id":"sword-of-wounding","name":"Sword of Wounding","kind":"gear","sub":"Magic item · Weapon (Glaive, Greatsword, Longsword, Rapier, Scimitar, or Shortsword), Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"When you hit a creature with an attack using this magic weapon, the target takes an extra 2d6 Necrotic damage and must succeed on a DC 15 Constitution saving throw or be unable to regain Hit Points for 1 hour.","text":"When you hit a creature with an attack using this magic weapon, the target takes an extra 2d6 Necrotic damage and must succeed on a DC 15 Constitution saving throw or be unable to regain Hit Points for 1 hour. The target repeats the save at the end of each of its turns, ending the effect on itself on a success."},{"id":"talisman-of-pure-good","name":"Talisman of Pure Good","kind":"gear","sub":"Magic item · Wondrous Item, Legendary (Requires Attunement by a Cleric or Paladin)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"This talisman is a mighty symbol of goodness.","text":"This talisman is a mighty symbol of goodness. A Fiend or an Undead that touches the talisman takes 8d6 Radiant damage and takes the damage again each time it ends its turn holding or carrying the talisman. Holy Symbol. You can use the talisman as a Holy Symbol. You gain a +2 bonus to spell attack rolls while you wear or hold it. Pure Rebuke. The talisman has 7 charges. While wearing or holding the talisman, you can take a Magic action to expend 1 charge and target one creature you can see on the ground within 120 feet of yourself. A flaming fissure opens under the target, and the target makes a DC 20 Dexterity saving throw. If the target is a Fiend or an Undead, it has Disadvantage on the save. On a failed save, the target falls into the fissure and is destroyed, leaving no remains. On a successful save, the target isn’t cast into the fissure but takes 4d6 Psychic damage from the ordeal. In either case, the fissure then closes, leaving no trace of its existence. When you expend the last charge, the talisman disperses into motes of golden light and is destroyed."},{"id":"talisman-of-the-sphere","name":"Talisman of the Sphere","kind":"gear","sub":"Magic item · Wondrous Item, Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"While holding or wearing this talisman, you have Advantage on any Intelligence (Arcana) check you make to control a Sphere of Annihilation .","text":"While holding or wearing this talisman, you have Advantage on any Intelligence (Arcana) check you make to control a Sphere of Annihilation . In addition, when you start your turn in control of a Sphere of Annihilation , you can take a Magic action to move it 10 feet plus a number of additional feet equal to 10 times your Intelligence modifier. This movement doesn’t have to be in a straight line."},{"id":"talisman-of-ultimate-evil","name":"Talisman of Ultimate Evil","kind":"gear","sub":"Magic item · Wondrous Item, Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"This item symbolizes unrepentant evil.","text":"This item symbolizes unrepentant evil. A creature that isn’t a Fiend or an Undead that touches the talisman takes 8d6 Necrotic damage and takes the damage again each time it ends its turn holding or carrying the talisman. Holy Symbol. You can use the talisman as a Holy Symbol. You gain a +2 bonus to spell attack rolls while you wear or hold it. Ultimate End. The talisman has 6 charges. While wearing or holding the talisman, you can take a Magic action to expend 1 charge and target one creature you can see on the ground within 120 feet of yourself. A flaming fissure opens under the target, and the target makes a DC 20 Dexterity saving throw. If the target is a Celestial, it has Disadvantage on the save. On a failed save, the target falls into the fissure and is destroyed, leaving no remains. On a successful save, the target isn’t cast into the fissure but takes 4d6 Psychic damage from the ordeal. In either case, the fissure then closes, leaving no trace of its existence. When you expend the last charge, the talisman dissolves into foul-smelling slime and is destroyed."},{"id":"thunderous-greatclub","name":"Thunderous Greatclub","kind":"gear","sub":"Magic item · Weapon (Greatclub), Very Rare (Requires Attunement)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"While you are attuned to this magic weapon, your Strength is 20 unless your Strength is already equal to or greater than that score.","text":"While you are attuned to this magic weapon, your Strength is 20 unless your Strength is already equal to or greater than that score. The weapon deals an extra 1d8 Thunder damage to any creature it hits and an extra 3d8 Thunder damage to objects it hits that aren’t being worn or carried. The weapon has the following additional properties. Clap of Thunder. As a Magic action, you can strike the weapon against a hard surface to create a loud clap of thunder audible out to 300 feet. You also create a 30-foot Cone of thunderous energy. Each creature in the Cone must succeed on a DC 15 Strength saving throw or have the Prone condition. Nonmagical objects in the Cone that aren’t being worn or carried take 3d8 Thunder damage. Earthquake. As a Magic action, you can strike the weapon against the ground to create an intense seismic disturbance in a 50-foot-radius circle centered on the point of impact. Structures in contact with the ground in that area take 50 Bludgeoning damage, and each creature on the ground in that area must succeed on a DC 20 Dexterity saving throw or have the Prone condition. If that creature is also concentrating, it must succeed on a DC 20 Constitution saving throw, or its Concentration is broken. In addition, you can cause a 30-foot-deep, 10-foot-wide fissure to open up on the ground anywhere in the area. Any creature on a spot where the fissure opens must make a DC 20 Dexterity saving throw, falling into the fissure on a failed save or moving with the fissure’s edge on a successful one. Any structure on a spot where the fissure opens collapses into the fissure. Once you use this property, it can’t be used again until the next dawn."},{"id":"tome-of-clear-thought","name":"Tome of Clear Thought","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0,"c":40000,"notes":"This book contains memory and logic exercises, and its words are charged with magic.","text":"This book contains memory and logic exercises, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book’s contents and practicing its guidelines, your Intelligence increases by 2, to a maximum of 30. The manual then loses its magic but regains it in a century."},{"id":"tome-of-leadership-and-influence","name":"Tome of Leadership and Influence","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0,"c":40000,"notes":"This book contains guidelines for influencing and charming others, and its words are charged with magic.","text":"This book contains guidelines for influencing and charming others, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book’s contents and practicing its guidelines, your Charisma increases by 2, to a maximum of 30. The manual then loses its magic but regains it in a century."},{"id":"tome-of-understanding","name":"Tome of Understanding","kind":"gear","sub":"Magic item · Wondrous Item, Very Rare","magic":true,"rarity":"Very Rare","attunement":false,"w":0,"c":40000,"notes":"This book contains intuition and insight exercises, and its words are charged with magic.","text":"This book contains intuition and insight exercises, and its words are charged with magic. If you spend 48 hours over a period of 6 days or fewer studying the book’s contents and practicing its guidelines, your Wisdom increases by 2, to a maximum of 30. The manual then loses its magic, but regains it in a century."},{"id":"trident-of-fish-command","name":"Trident of Fish Command","kind":"gear","sub":"Magic item · Weapon (Trident), Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"This magic weapon has 3 charges, and it regains 1d3 expended charges daily at dawn.","text":"This magic weapon has 3 charges, and it regains 1d3 expended charges daily at dawn. While you carry it, you can expend 1 charge to cast Dominate Beast (save DC 15) from it on a Beast that has a Swim Speed."},{"id":"universal-solvent","name":"Universal Solvent","kind":"gear","sub":"Magic item · Wondrous Item, Legendary","magic":true,"rarity":"Legendary","attunement":false,"w":0,"c":200000,"notes":"This tube holds milky liquid with a strong alcohol smell.","text":"This tube holds milky liquid with a strong alcohol smell. When found, a tube contains 1d6 + 1 ounces. You can take a Utilize action to pour 1 or more ounces of solvent from the tube onto a surface within reach. Each ounce instantly dissolves up to 1 square foot of adhesive it touches, including Sovereign Glue ."},{"id":"vicious-weapon","name":"Vicious Weapon","kind":"gear","sub":"Magic item · Weapon (Any Simple or Martial), Rare","magic":true,"rarity":"Rare","attunement":false,"w":0,"c":4000,"notes":"This magic weapon deals an extra 2d6 damage to any creature it hits.","text":"This magic weapon deals an extra 2d6 damage to any creature it hits. This extra damage is of the same type as the weapon’s normal damage."},{"id":"vorpal-sword","name":"Vorpal Sword","kind":"gear","sub":"Magic item · Weapon (Glaive, Greatsword, Longsword, or Scimitar), Legendary (Requires Attunement)","magic":true,"rarity":"Legendary","attunement":true,"w":0,"c":200000,"notes":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon.","text":"You gain a +3 bonus to attack rolls and damage rolls made with this magic weapon. In addition, the weapon ignores Resistance to Slashing damage. When you use this weapon to attack a creature that has at least one head and roll a 20 on the d20 for the attack roll, you cut off one of the creature’s heads. The creature dies if it can’t survive without the lost head. A creature is immune to this effect if it has Immunity to Slashing damage, if it doesn’t have or need a head, or if the GM decides that the creature is too big for its head to be cut off with this weapon. Such a creature instead takes an extra 30 Slashing damage from the hit. If the creature has Legendary Resistance, it can expend one daily use of that trait to avoid losing its head, taking the extra damage instead."},{"id":"wand-of-binding","name":"Wand of Binding","kind":"gear","sub":"Magic item · Wand, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This wand has 7 charges.","text":"This wand has 7 charges.\nSpells.\nWhile holding the wand, you can cast one of the spells (save DC 17) on the following table from it. The table indicates how many charges you must expend to cast the spell.\nSpell Charge\nCost\nHold Monster 5\nHold Person 2\nRegaining Charges.\nThe wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand’s last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed."},{"id":"wand-of-enemy-detection","name":"Wand of Enemy Detection","kind":"gear","sub":"Magic item · Wand, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This wand has 7 charges.","text":"This wand has 7 charges. While holding it, you can take a Magic action to expend 1 charge. For 1 minute, you know the direction of the nearest creature Hostile to you within 60 feet, but not its distance from you. The wand can sense the presence of Hostile creatures that are Invisible, ethereal, disguised, or hidden, as well as those in plain sight. The effect ends if you stop holding the wand. Regaining Charges. The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand’s last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed."},{"id":"wand-of-fear","name":"Wand of Fear","kind":"gear","sub":"Magic item · Wand, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This wand has 7 charges.","text":"This wand has 7 charges.\nSpells.\nWhile holding the wand, you can cast one of the spells (save DC 15) on the following table from it. The table indicates how many charges you must expend to cast the spell.\nSpell\nCharge\nCost\nCommand (“flee” or “grovel” only) 1\nFear (60-foot Cone) 3\nRegaining Charges.\nThe wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand’s last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed."},{"id":"wand-of-fireballs","name":"Wand of Fireballs","kind":"gear","sub":"Magic item · Wand, Rare (Requires Attunement by a Spellcaster)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This wand has 7 charges.","text":"This wand has 7 charges. While holding it, you can expend no more than 3 charges to cast Fireball (save DC 15) from it. For 1 charge, you cast the level 3 version of the spell. You can increase the spell’s level by 1 for each additional charge you expend. Regaining Charges. The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand’s last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed."},{"id":"wand-of-lightning-bolts","name":"Wand of Lightning Bolts","kind":"gear","sub":"Magic item · Wand, Rare (Requires Attunement by a Spellcaster)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This wand has 7 charges.","text":"This wand has 7 charges. While holding it, you can expend no more than 3 charges to cast Lightning Bolt (save DC 15) from it. For 1 charge, you cast the level 3 version of the spell. You can increase the spell’s level by 1 for each additional charge you expend. Regaining Charges. The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand’s last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed."},{"id":"wand-of-magic-detection","name":"Wand of Magic Detection","kind":"gear","sub":"Magic item · Wand, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"This wand has 3 charges.","text":"This wand has 3 charges. While holding it, you can expend 1 charge to cast Detect Magic from it. The wand regains 1d3 expended charges daily at dawn."},{"id":"wand-of-magic-missiles","name":"Wand of Magic Missiles","kind":"gear","sub":"Magic item · Wand, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"This wand has 7 charges.","text":"This wand has 7 charges. While holding it, you can expend no more than 3 charges to cast Magic Missile from it. For 1 charge, you cast the level 1 version of the spell. You can increase the spell’s level by 1 for each additional charge you expend. Regaining Charges. The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand’s last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed."},{"id":"wand-of-paralysis","name":"Wand of Paralysis","kind":"gear","sub":"Magic item · Wand, Rare (Requires Attunement by a Spellcaster)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This wand has 7 charges.","text":"This wand has 7 charges. While holding it, you can take a Magic action to expend 1 charge to cause a thin blue ray to streak from the tip toward a creature you can see within 60 feet of yourself. The target must succeed on a DC 15 Constitution saving throw or have the Paralyzed condition for 1 minute. At the end of each of the target’s turns, it repeats the save, ending the effect on itself on a success. Regaining Charges. The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand’s last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed."},{"id":"wand-of-polymorph","name":"Wand of Polymorph","kind":"gear","sub":"Magic item · Wand, Very Rare (Requires Attunement by a Spellcaster)","magic":true,"rarity":"Very Rare","attunement":true,"w":0,"c":40000,"notes":"This wand has 7 charges.","text":"This wand has 7 charges. While holding it, you can expend 1 charge to cast Polymorph (save DC 15) from it. Regaining Charges. The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand’s last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed."},{"id":"wand-of-secrets","name":"Wand of Secrets","kind":"gear","sub":"Magic item · Wand, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"This wand has 3 charges and regains 1d3 expended charges daily at dawn.","text":"This wand has 3 charges and regains 1d3 expended charges daily at dawn. While holding it, you can take a Magic action to expend 1 charge, and if a secret door or trap is within 60 feet of you, the wand pulses and points at the one nearest to you."},{"id":"wand-of-the-war-mage-plus1-plus2-or-plus3","name":"Wand of the War Mage, +1, +2, or +3","kind":"gear","sub":"Magic item · Wand, Uncommon (+1), Rare (+2), or Very Rare (+3) (Requires Attunement by a Spellcaster)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"While holding this wand, you gain a bonus to spell attack rolls determined by the wand’s rarity.","text":"While holding this wand, you gain a bonus to spell attack rolls determined by the wand’s rarity. In addition, you ignore Half Cover when making a spell attack roll."},{"id":"wand-of-web","name":"Wand of Web","kind":"gear","sub":"Magic item · Wand, Uncommon (Requires Attunement by a Spellcaster)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"This wand has 7 charges.","text":"This wand has 7 charges. While holding it, you can expend 1 charge to cast Web (save DC 13) from it. Regaining Charges. The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand’s last charge, roll 1d20. On a 1, the wand crumbles into ashes and is destroyed."},{"id":"wand-of-wonder","name":"Wand of Wonder","kind":"gear","sub":"Magic item · Wand, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"This wand has 7 charges.","text":"This wand has 7 charges. While holding it, you can take a Magic action to expend 1 charge while choosing a point within 120 feet of yourself. That location becomes the point of origin of a spell or other magical effect determined by rolling on the Wand of Wonder Effects table. Spells cast from the wand have a save DC of 15. If a spell’s maximum range is normally less than 120 feet, it becomes 120 feet when cast from the wand. If an effect has multiple possible subjects, the GM determines randomly which among them are affected. Regaining Charges. The wand regains 1d6 + 1 expended charges daily at dawn. If you expend the wand’s last charge, roll 1d20. On a 1, the wand crumbles into dust and is destroyed.\nWand of Wonder Effects\n1d100 Effect\n01–20 You cast a spell originating from the chosen\npoint. Roll 1d10 to determine the spell: on a\n1–2, Darkness ; on a 3–4, Faerie Fire ; on a 5–6,\nFireball ; on a 7–8, Slow ; on a 9–10, Stinking\nCloud .\n21–25 Nothing happens at the chosen point of origin.\nInstead, you have the Stunned condition until\nthe start of your next turn, believing some-\nthing awesome just happened.\n26–30 You cast Gust of Wind . The Line created by the\nspell extends from you to the chosen point of\norigin.\n31–35 Nothing happens at the chosen point of origin.\nInstead, you take 1d6 Psychic damage.\n36–40 Heavy rain falls for 1 minute in a 120-foot-\nhigh, 60-foot-radius Cylinder centered on the\nchosen point of origin. During that time, the\narea of effect is Lightly Obscured.\n41–45 A cloud of 600 oversized butterflies fills a\n60-foot-high, 30-foot-radius Cylinder centered\non the chosen point of origin. The butterflies\nremain for 10 minutes, during which time the\narea of effect is Heavily Obscured.\n46–50 You cast Lightning Bolt . The Line created by the\nspell extends from you to the chosen point of\norigin.\n51–55 The creature closest to the chosen point of\norigin is enlarged as if you had cast Enlarge/\nReduce on it. If the target isn’t you and can’t be\naffected by that spell, you become the target\ninstead.\n56–60 A magically formed creature appears in an\nunoccupied space as close to the chosen point\nof origin as possible. The creature isn’t under\nyour control, acts as it normally would, and\ndisappears after 1 hour or when it drops to 0\nHit Points. Roll 1d4 to determine which crea-\nture appears. On a 1, a Rhinoceros appears;\non a 2, an Elephant appears; and on a 3–4, a\nRat appears.\n61–64 Grass covers a 60-foot-radius circle of ground,\nwith the center of that circle as close to the\nchosen point of origin as possible. Grass that’s\nalready there grows to ten times its normal\nsize and remains overgrown for 1 minute.\n1d100 Effect\n65–68 An object of the GM’s choice disappears into\nthe Ethereal Plane. The object must be neither\nworn nor carried, within 120 feet of the cho-\nsen point of origin, and no larger than 10 feet\nin any dimension. If there are no such objects\nin range, nothing happens.\n69–72 Nothing happens at the chosen point of origin.\nInstead, you shrink as if you had cast Enlarge/\nReduce on yourself and remain in that state for\n1 minute.\n73–77 Leaves grow from the creature nearest to the\nchosen point of origin. Unless they are picked\noff, the leaves turn brown and fall off after 24\nhours.\n78–82 Nothing happens at the chosen point of origin.\nInstead, a burst of colorful, shimmering light\nextends from you in a 30-foot Emanation.\nEach creature in the area must succeed on a\nDC 15 Constitution saving throw or have the\nBlinded condition for 1 minute. A creature re-\npeats the save at the end of each of its turns,\nending the effect on itself on a success.\n83–87 Nothing happens at the chosen point of origin.\nInstead, you cast Invisibility on yourself.\n88–92 Nothing happens at the chosen point of ori-\ngin. Instead, a stream of 1d4 × 10 gems, each\nworth 1 GP, shoots from the wand’s tip in a\nLine 30 feet long and 5 feet wide toward the\nchosen point of origin. Each gem deals 1 Blud-\ngeoning damage, and the total damage of the\ngems is divided equally among all creatures in\nthe Line.\n93–97 You cast Polymorph , targeting the creature\nclosest to the chosen point of origin. Roll 1d4\nto determine the target’s new form. On a 1,\nthe new form is a Black Bear; on a 2, the\nnew form is a Giant Wasp; on a 3–4, the new\nform is a Frog.\n98–00 The creature closest to the chosen point of\norigin makes a DC 15 Constitution saving\nthrow. On a failed save, the creature has the\nRestrained condition and begins to turn to\nstone. While Restrained in this way, the crea-\nture repeats the save at the end of its next\nturn. On a successful save, the effect ends.\nOn a failed save, the creature has the Petrified\ncondition instead of the Restrained condition.\nThe petrification lasts until the creature is\nfreed by the Greater Restoration spell or similar\nmagic."},{"id":"weapon-plus1-plus2-or-plus3","name":"Weapon, +1, +2, or +3","kind":"gear","sub":"Magic item · Weapon (Any Simple or Martial), Uncommon (+1), Rare (+2), or Very Rare (+3)","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"You have a bonus to attack rolls and damage rolls made with this magic weapon.","text":"You have a bonus to attack rolls and damage rolls made with this magic weapon. The bonus is determined by the weapon’s rarity."},{"id":"weapon-of-warning","name":"Weapon of Warning","kind":"gear","sub":"Magic item · Weapon (Any Simple or Martial), Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"As long as this weapon is within your reach and you are attuned to it, you and allies within 30 feet of you gain the following benefits.","text":"As long as this weapon is within your reach and you are attuned to it, you and allies within 30 feet of you gain the following benefits. Alarm. The weapon magically awakens each subject who is sleeping naturally when combat begins. This benefit doesn’t wake a subject from magically induced sleep. Supernatural Readiness. Each subject has Advantage on its Initiative rolls."},{"id":"well-of-many-worlds","name":"Well of Many Worlds","kind":"gear","sub":"Magic item · Wondrous Item, Legendary","magic":true,"rarity":"Legendary","attunement":false,"w":0,"c":200000,"notes":"This fine black cloth, soft as silk, is folded up to the dimensions of a handkerchief.","text":"This fine black cloth, soft as silk, is folded up to the dimensions of a handkerchief. It unfolds into a circular sheet 6 feet in diameter. You can take a Magic action to unfold the Well of Many Worlds and place it on a solid surface, whereupon it forms a two-way, 6-foot-diameter, circular portal to another world or plane of existence. Each time the item opens a portal, the GM decides where it leads. The portal remains open until a creature within 5 feet of it takes a Magic action to close it by taking hold of the edges of the cloth and folding it up. Once the Well of Many Worlds has opened a portal, it can’t do so again for 1d8 hours."},{"id":"wind-fan","name":"Wind Fan","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon","magic":true,"rarity":"Uncommon","attunement":false,"w":0,"c":400,"notes":"While holding this fan, you can cast Gust of Wind (save DC 13) from it.","text":"While holding this fan, you can cast Gust of Wind (save DC 13) from it. Each subsequent time the fan is used before the next dawn, it has a cumulative 20 percent chance of not working; if the fan fails to work, it tears into useless, nonmagical tatters."},{"id":"winged-boots","name":"Winged Boots","kind":"gear","sub":"Magic item · Wondrous Item, Uncommon (Requires Attunement)","magic":true,"rarity":"Uncommon","attunement":true,"w":0,"c":400,"notes":"These boots have 4 charges and regain 1d4 expended charges daily at dawn.","text":"These boots have 4 charges and regain 1d4 expended charges daily at dawn. While wearing the boots, you can take a Magic action to expend 1 charge, gaining a Fly Speed of 30 feet for 1 hour. If you are flying when the duration expires, you descend at a rate of 30 feet per round until you land."},{"id":"wings-of-flying","name":"Wings of Flying","kind":"gear","sub":"Magic item · Wondrous Item, Rare (Requires Attunement)","magic":true,"rarity":"Rare","attunement":true,"w":0,"c":4000,"notes":"While wearing this cloak, you can take a Magic action to turn the cloak into a pair of wings on your back.","text":"While wearing this cloak, you can take a Magic action to turn the cloak into a pair of wings on your back. The wings lasts for 1 hour or until you end the effect early as a Magic action. The wings give you a Fly Speed of 60 feet. If you are aloft when the wings disappear, you fall. When the wings disappear, you can’t use them again for 1d12 hours."}] });
})(window);
